/// A Campus with no Library is the expensive half of a research city bought
/// and the cheap half declined. That debt was only ever paid at war.
#[test]
fn a_campus_without_its_library_carries_a_debt_in_peacetime_too() {
    let mut game = Game::new(2, 32, 24, 5_414, 250, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("starting settler");
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("found city");
    let city = game.player_city_ids(0)[0];
    install_ai_test_district(&mut game, city, "campus");
    game.players[0].techs.insert(crate::name!("writing"));
    game.turn = 60;

    let mut ai = AdvancedAi::new();
    ai.refresh_research_weight(&game);
    let legacy = AdvancedAi::legacy();
    let plan = StrategicPlan {
        strategy: GrandStrategy::Religion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let counts = ai.counts(&game, 0);
    let library = Item::Building {
        building: crate::name!("library"),
    };
    assert!(game.can_produce(0, city, &library));

    let treated = ai.production_value(&game, 0, city, &library, &plan, &counts);
    let control = legacy.production_value(&game, 0, city, &library, &plan, &counts);
    assert!(
        treated > control * 2.0,
        "the peacetime Campus-building debt must be paid: {treated} vs {control}"
    );

    // And it is owed for the Campus, not for every building in the city.
    let monument = Item::Building {
        building: crate::name!("monument"),
    };
    let treated_monument = ai.production_value(&game, 0, city, &monument, &plan, &counts);
    let control_monument = legacy.production_value(&game, 0, city, &monument, &plan, &counts);
    assert!(
        treated_monument <= control_monument * 1.05,
        "an unrelated building must not collect the research debt: \
             {treated_monument} vs {control_monument}"
    );
}

/// ★★★★ Seven Campuses, three Libraries, one University at t150 of run
/// civvis-20260816T223457Z: the Great Merchant race outranked the Campus
/// buildings in every city (`commercial_hub_investment = 124` vs
/// `university = 44` in Rome; `48` vs `library = 26` in Arpinum). See
/// `buildings_before_projects`: while the city can produce a Library,
/// University, Research Lab or Workshop it lacks, its repeatable project
/// is capped below them; once nothing is owed the project is priced as
/// before; the frozen and stock controllers never cap.
#[test]
fn a_district_project_waits_behind_the_science_buildings_the_city_can_build() {
    let mut game = Game::new(2, 32, 24, 5_414, 250, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("starting settler");
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("found city");
    let city = game.player_city_ids(0)[0];
    // The measured shape: a Commercial Hub WITH its Market (so the
    // project's own family owes nothing) beside a Campus WITHOUT its
    // Library.
    install_ai_test_district(&mut game, city, "campus");
    install_ai_test_district(&mut game, city, "commercial_hub");
    game.cities
        .get_mut(&city)
        .unwrap()
        .buildings
        .push(crate::name!("market"));
    game.players[0].techs.insert(crate::name!("writing"));
    game.players[0].techs.insert(crate::name!("currency"));
    game.turn = 60;
    // A race worth running: the empire is close to a Great Merchant.
    game.players[0].gpp.insert("merchant".to_string(), 30.0);

    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let library = Item::Building {
        building: crate::name!("library"),
    };
    let project = Item::Project {
        project: crate::name!("commercial_hub_investment"),
    };
    assert!(game.can_produce(0, city, &library), "the Library is owed");
    assert!(game.can_produce(0, city, &project), "the race is open");

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(
        live.buildings_before_projects,
        "the live seat carries the treatment"
    );
    live.refresh_research_weight(&game);
    let mut lax = AdvancedAi::new();
    lax.enable_live_bridge();
    lax.disable_buildings_before_projects();
    lax.refresh_research_weight(&game);
    let counts = live.counts(&game, 0);

    let capped = live.district_project_value(&game, 0, city, "commercial_hub_investment", &plan);
    let free = lax.district_project_value(&game, 0, city, "commercial_hub_investment", &plan);
    assert!(
        capped <= PROJECT_BEHIND_BUILDINGS_CAP,
        "capped while the Library is owed: {capped}"
    );
    assert!(
        free > capped,
        "the withheld arm prices the race in full: {free}"
    );
    let library_value = live.production_value(&game, 0, city, &library, &plan, &counts);
    let project_value = live.production_value(&game, 0, city, &project, &plan, &counts);
    assert!(
        library_value > project_value,
        "the Library outranks the race while it is owed: {library_value} vs {project_value}"
    );
    assert!(project_value > 0.0, "the project stays a positive fallback");

    // Library built, University not yet reachable: nothing owed, the race
    // is priced as before.
    game.cities
        .get_mut(&city)
        .unwrap()
        .buildings
        .push(crate::name!("library"));
    assert!(!game.can_produce(0, city, &library));
    let university = Item::Building {
        building: crate::name!("university"),
    };
    assert!(!game.can_produce(0, city, &university), "no Education yet");
    let uncapped = live.district_project_value(&game, 0, city, "commercial_hub_investment", &plan);
    let control = lax.district_project_value(&game, 0, city, "commercial_hub_investment", &plan);
    assert_eq!(
        uncapped, control,
        "with nothing owed the treatment is a no-op"
    );

    assert!(!AdvancedAi::new().buildings_before_projects);
    assert!(!AdvancedAi::legacy().buildings_before_projects);
}

/// Host competitions move the diplomatic race outside the ordinary Congress
/// ballot. The exact score table must therefore make World Games and either
/// Aid Request project legal and compelling, while the World's Fair rewards
/// the Great Person points existing district projects already produce.
#[test]
fn live_competitions_price_host_projects_and_worlds_fair_production() {
    let mut game = Game::new(2, 32, 24, 5_415, 250, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("starting settler");
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("found city");
    let city = game.player_city_ids(0)[0];
    game.turn = 180;
    game.players[0].techs.insert(crate::name!("pottery"));
    let plan = StrategicPlan {
        strategy: GrandStrategy::Diplomacy,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.refresh_research_weight(&game);
    let athlete = Item::Project {
        project: crate::name!("train_athletes"),
    };
    let aid = Item::Project {
        project: crate::name!("send_aid"),
    };
    let granary = Item::Building {
        building: crate::name!("granary"),
    };
    assert!(game.can_produce(0, city, &granary));
    assert!(
        !game.can_produce(0, city, &athlete),
        "the host-only project cannot escape into a native menu"
    );
    assert!(
        !game.can_produce(0, city, &aid),
        "the shared Aid Request project cannot escape into a native menu"
    );

    game.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_WORLD_GAMES".to_string(),
        ends: game.turn + 50,
        ours: 0.0,
        leader: 50.0,
    }]);
    assert!(game.can_produce(0, city, &athlete));
    let resumed: Game = serde_json::from_value(
        serde_json::to_value(&game).expect("the live competition checkpoint saves"),
    )
    .expect("the live competition checkpoint reloads");
    assert_eq!(resumed.host_competitions, game.host_competitions);
    assert!(
        resumed.can_produce(0, city, &athlete),
        "a resumed live mirror keeps the host-granted project legal"
    );
    let counts = ai.counts(&game, 0);
    let athlete_value = ai.production_value(&game, 0, city, &athlete, &plan, &counts);
    let granary_value = ai.production_value(&game, 0, city, &granary, &plan, &counts);
    assert!(
        athlete_value > granary_value,
        "a 50-point project that catches the World Games leader must outrank ordinary infrastructure: {athlete_value} vs {granary_value}"
    );

    // Once the host competition ends, the bridge withdraws both legality and
    // its valuation; a stale project must never survive as a neutral fallback.
    game.replace_host_competitions(Vec::new());
    assert!(!game.can_produce(0, city, &athlete));
    assert!(ai.production_value(&game, 0, city, &athlete, &plan, &counts) < -1_000.0);

    // Firaxis grants the same 200-point Send Aid project for either kind of
    // request. Each individual host kind must make it legal and compelling;
    // treating the plural rules row as an AND would silently lose one aid
    // emergency.
    for kind in ["EMERGENCY_SEND_AID", "EMERGENCY_SEND_MILITARY_AID"] {
        game.replace_host_competitions(vec![crate::game::HostCompetition {
            kind: kind.to_string(),
            ends: game.turn + 50,
            ours: 0.0,
            leader: 200.0,
        }]);
        assert!(
            game.can_produce(0, city, &aid),
            "{kind} grants the shared Send Aid project"
        );
        let aid_value = ai.production_value(&game, 0, city, &aid, &plan, &counts);
        assert!(
            aid_value > granary_value,
            "the 200-point Send Aid project must outrank ordinary infrastructure during {kind}: {aid_value} vs {granary_value}"
        );
    }
    game.replace_host_competitions(vec![
        crate::game::HostCompetition {
            kind: "EMERGENCY_SEND_AID".to_string(),
            ends: game.turn + 1,
            ours: 0.0,
            leader: 200.0,
        },
        crate::game::HostCompetition {
            kind: "EMERGENCY_SEND_MILITARY_AID".to_string(),
            ends: game.turn + 50,
            ours: 0.0,
            leader: 200.0,
        },
    ]);
    let best_live_aid_value = ai.production_value(&game, 0, city, &aid, &plan, &counts);
    assert!(
        best_live_aid_value > granary_value,
        "when both kinds are active, the viable military request must win over an expiring ordinary request: {best_live_aid_value} vs {granary_value}"
    );
    game.replace_host_competitions(Vec::new());
    assert!(
        !game.can_produce(0, city, &aid),
        "with neither aid emergency live the shared project is withdrawn"
    );
    assert!(ai.production_value(&game, 0, city, &aid, &plan, &counts) < -1_000.0);

    install_ai_test_district(&mut game, city, "campus");
    let grants = Item::Project {
        project: crate::name!("campus_research_grants"),
    };
    assert!(game.can_produce(0, city, &grants));
    let baseline = ai.production_value(&game, 0, city, &grants, &plan, &counts);
    game.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_WORLDS_FAIR".to_string(),
        ends: game.turn + 50,
        ours: 0.0,
        leader: 10.0,
    }]);
    let boosted = ai.production_value(&game, 0, city, &grants, &plan, &counts);
    assert!(
        boosted > baseline + 50.0,
        "a Campus project's Great Scientist points must close the live World's Fair race: {boosted} vs {baseline}"
    );
}

/// Firaxis counts selected Great Person points in its Nobel competitions just
/// as it counts every class for the World's Fair. A hosted Nobel Physics race
/// should therefore pull a Scientist project, while Literature should pull a
/// Writer/Artist/Musician project—and neither race may price the other class.
#[test]
fn live_nobel_competitions_price_only_matching_great_person_projects() {
    let mut game = Game::new(2, 32, 24, 5_416, 250, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("starting settler");
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("found city");
    let city = game.player_city_ids(0)[0];
    game.turn = 180;
    install_ai_test_district(&mut game, city, "campus");
    install_ai_test_district(&mut game, city, "theater_square");

    let plan = StrategicPlan {
        strategy: GrandStrategy::Diplomacy,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.refresh_research_weight(&game);
    let scientist = Item::Project {
        project: crate::name!("campus_research_grants"),
    };
    let literature = Item::Project {
        project: crate::name!("theater_square_festival"),
    };
    assert!(game.can_produce(0, city, &scientist));
    assert!(game.can_produce(0, city, &literature));
    let counts = ai.counts(&game, 0);
    let scientist_baseline = ai.production_value(&game, 0, city, &scientist, &plan, &counts);
    let literature_baseline = ai.production_value(&game, 0, city, &literature, &plan, &counts);

    game.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_PHYSICS".to_string(),
        ends: game.turn + 50,
        ours: 0.0,
        leader: 10.0,
    }]);
    let physics_scientist = ai.production_value(&game, 0, city, &scientist, &plan, &counts);
    let physics_literature = ai.production_value(&game, 0, city, &literature, &plan, &counts);
    assert!(
        physics_scientist > scientist_baseline + 50.0,
        "Nobel Physics must price a project's Great Scientist points: {physics_scientist} vs {scientist_baseline}"
    );
    assert_eq!(
        physics_literature, literature_baseline,
        "Nobel Physics must not claim Writer/Artist/Musician points"
    );

    game.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_LITERATURE".to_string(),
        ends: game.turn + 50,
        ours: 0.0,
        leader: 15.0,
    }]);
    let literature_scientist = ai.production_value(&game, 0, city, &scientist, &plan, &counts);
    let literature_project = ai.production_value(&game, 0, city, &literature, &plan, &counts);
    assert_eq!(
        literature_scientist, scientist_baseline,
        "Nobel Literature must not claim Great Scientist points"
    );
    assert!(
        literature_project > literature_baseline + 50.0,
        "Nobel Literature must price Writer/Artist/Musician project points: {literature_project} vs {literature_baseline}"
    );
}

/// Nobel Peace is unlike the other Nobel competitions: its score source is
/// Favor generated during the competition.  A live seat that can finish the
/// Foreign Ministry in time must therefore value its +3-per-turn stream, but
/// no unrelated competition or already-expired Peace contest may borrow it.
#[test]
fn live_nobel_peace_prices_favor_buildings_only_before_its_deadline() {
    let mut game = Game::new(2, 32, 24, 5_417, 250, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("starting settler");
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("found city");
    let city = game.player_city_ids(0)[0];
    game.turn = 180;
    install_ai_test_district(&mut game, city, "government_plaza");
    game.cities
        .get_mut(&city)
        .expect("capital")
        .buildings
        .push(crate::name!("ancestral_hall"));
    // Keep the fixture inside Nobel Peace's short clock without changing the
    // Foreign Ministry's real cost or its prerequisite chain.
    game.observed_city_yield_adjustments.insert(
        city,
        Yields {
            production: 120.0,
            ..Yields::default()
        },
    );
    let foreign_ministry = Item::Building {
        building: crate::name!("foreign_ministry"),
    };
    assert!(
        game.can_produce(0, city, &foreign_ministry),
        "the completed Plaza and its first tier unlock Foreign Ministry"
    );
    assert_eq!(
        game.rules.buildings[&crate::name!("foreign_ministry")]
            .effects
            .get("diplomatic_favor"),
        Some(&3.0),
        "the fixture uses the host's real +3 Favor-per-turn source"
    );

    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.refresh_research_weight(&game);
    let counts = ai.counts(&game, 0);
    let baseline = ai.production_value(&game, 0, city, &foreign_ministry, &plan, &counts);

    game.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_LITERATURE".to_string(),
        ends: game.turn + 30,
        ours: 0.0,
        leader: 50.0,
    }]);
    assert_eq!(
        ai.production_value(&game, 0, city, &foreign_ministry, &plan, &counts),
        baseline,
        "Nobel Literature scores Great Person points, not generated Favor"
    );

    game.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_PEACE".to_string(),
        ends: game.turn + 30,
        ours: 0.0,
        leader: 50.0,
    }]);
    let peace = ai.production_value(&game, 0, city, &foreign_ministry, &plan, &counts);
    assert!(
        peace > baseline + 50.0,
        "a timely +3 Favor stream must close the Nobel Peace race: {peace} vs {baseline}"
    );

    game.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_PEACE".to_string(),
        ends: game.turn + 1,
        ours: 0.0,
        leader: 50.0,
    }]);
    assert_eq!(
        ai.production_value(&game, 0, city, &foreign_ministry, &plan, &counts),
        baseline,
        "a building that cannot generate Favor before the deadline receives no stale score"
    );
}

/// Monarchy's Star Fort modifier is not stored on Renaissance Walls itself:
/// the engine grants its Favor from the government to every completed member
/// of that building family.  Nobel Peace must price that generated stream for
/// both the generic building and Georgia's Tsikhe replacement, but no earlier
/// wall tier or other government can claim it.
#[test]
fn live_nobel_peace_prices_monarchy_renaissance_wall_favor() {
    let mut game = Game::new(2, 32, 24, 5_418, 250, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("starting settler");
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("found city");
    let city = game.player_city_ids(0)[0];
    game.turn = 180;
    game.players[0].government = Some("monarchy".to_string());
    game.players[0].techs.insert(crate::name!("siege_tactics"));
    game.cities
        .get_mut(&city)
        .expect("capital")
        .buildings
        .extend([crate::name!("walls"), crate::name!("medieval_walls")]);
    let wall_hp = game.city_max_wall_hp(&game.cities[&city]);
    game.cities.get_mut(&city).expect("capital").wall_hp = wall_hp;
    // Keep this defensive building inside Nobel Peace's short clock without
    // changing its real cost or prerequisite chain.
    game.observed_city_yield_adjustments.insert(
        city,
        Yields {
            production: 120.0,
            ..Yields::default()
        },
    );
    let renaissance_walls = Item::Building {
        building: crate::name!("renaissance_walls"),
    };
    assert!(game.can_produce(0, city, &renaissance_walls));
    assert_eq!(
        game.rules.buildings[&crate::name!("renaissance_walls")]
            .effects
            .get("diplomatic_favor"),
        None,
        "the source is Monarchy's Star Fort modifier, not a field on the wall"
    );
    assert_eq!(
        game.gov_effects(0).walled_city_diplomatic_favor,
        2.0,
        "the fixture uses Monarchy's real +2 Favor-per-wall-per-turn modifier"
    );

    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.refresh_research_weight(&game);
    let counts = ai.counts(&game, 0);
    let baseline = ai.production_value(&game, 0, city, &renaissance_walls, &plan, &counts);
    let medieval_walls = Item::Building {
        building: crate::name!("medieval_walls"),
    };
    let medieval_baseline = ai.production_value(&game, 0, city, &medieval_walls, &plan, &counts);

    game.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_LITERATURE".to_string(),
        ends: game.turn + 30,
        ours: 0.0,
        leader: 50.0,
    }]);
    assert_eq!(
        ai.production_value(&game, 0, city, &renaissance_walls, &plan, &counts),
        baseline,
        "Nobel Literature must not claim Monarchy's generated Favor"
    );

    game.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_PEACE".to_string(),
        ends: game.turn + 30,
        ours: 0.0,
        leader: 50.0,
    }]);
    let peace = ai.production_value(&game, 0, city, &renaissance_walls, &plan, &counts);
    assert!(
        peace > baseline + 50.0,
        "a timely Monarchy wall must close the Nobel Peace race: {peace} vs {baseline}"
    );
    assert_eq!(
        ai.production_value(&game, 0, city, &medieval_walls, &plan, &counts),
        medieval_baseline,
        "the earlier wall tier must not claim Monarchy's Star Fort Favor"
    );

    game.players[0].government = Some("merchant_republic".to_string());
    let other_government_peace =
        ai.production_value(&game, 0, city, &renaissance_walls, &plan, &counts);
    game.replace_host_competitions(Vec::new());
    let other_government_baseline =
        ai.production_value(&game, 0, city, &renaissance_walls, &plan, &counts);
    assert_eq!(
        other_government_peace, other_government_baseline,
        "another government must not borrow Monarchy's wall Favor"
    );

    game.players[0].government = Some("monarchy".to_string());
    game.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_PEACE".to_string(),
        ends: game.turn + 1,
        ours: 0.0,
        leader: 50.0,
    }]);
    assert_eq!(
        ai.production_value(&game, 0, city, &renaissance_walls, &plan, &counts),
        baseline,
        "a wall that cannot generate Favor before the deadline receives no stale score"
    );

    game.players[0].civ = "Georgia".to_string();
    let tsikhe = Item::Building {
        building: crate::name!("tsikhe"),
    };
    assert!(game.can_produce(0, city, &tsikhe));
    assert!(
        game.building_is_family(crate::name!("tsikhe"), crate::name!("renaissance_walls")),
        "Tsikhe is the real Renaissance Walls replacement the engine checks"
    );
    let tsikhe_baseline = ai.production_value(&game, 0, city, &tsikhe, &plan, &counts);
    game.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_PEACE".to_string(),
        ends: game.turn + 30,
        ours: 0.0,
        leader: 50.0,
    }]);
    let tsikhe_peace = ai.production_value(&game, 0, city, &tsikhe, &plan, &counts);
    assert!(
        tsikhe_peace > tsikhe_baseline + 50.0,
        "the Tsikhe replacement must receive the same Nobel Peace Favor score: {tsikhe_peace} vs {tsikhe_baseline}"
    );
}

/// Nobel Peace scores Favor generated during the competition. A city-state
/// suzerainty is a +1 Favor-per-turn source, so when the free Envoys already
/// in hand can secure one this turn it must beat a normally better-aligned
/// city-state. Other Nobel types and a Peace clock too short for next-turn
/// Favor retain the ordinary allocation.
#[test]
fn live_nobel_peace_envoys_price_an_affordable_suzerainty_favor_stream() {
    let board = || {
        let mut game = Game::new_full(2, 32, 24, 5_419, 250, 2, false);
        let minors: Vec<usize> = game
            .players
            .iter()
            .filter(|player| player.alive && player.is_minor && !player.is_barbarian)
            .map(|player| player.id)
            .collect();
        assert_eq!(minors.len(), 2, "the fixture needs two city-states");
        for minor in minors.iter().copied() {
            game.record_contact(0, minor);
        }
        // Contact may grant its own discovery Envoy. This test prices only
        // the three Envoys the player is choosing between now.
        game.players[0].envoys.clear();
        game.players[0].envoys_free = 3;
        let peace_target = minors[0];
        let science_target = minors[1];
        game.players[peace_target].civ = "Cahokia".to_string();
        game.players[science_target].civ = "Hattusa".to_string();
        // Hattusa is the ordinary Science favorite but eleven Envoys away
        // from a takeover. Cahokia is the one current three-Envoy route to a
        // new Favor source, so a live Peace clock must change the choice.
        game.players[1].envoys = vec![(science_target, 10)];
        (game, peace_target, science_target)
    };

    let (mut ordinary, peace_target, science_target) = board();
    AdvancedAi::new().advanced_envoys(&mut ordinary, 0, GrandStrategy::Science, None);
    assert_eq!(ordinary.envoys_at(0, peace_target), 0);
    assert_eq!(ordinary.envoys_at(0, science_target), 3);

    let (mut wrong_nobel, peace_target, science_target) = board();
    wrong_nobel.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_LITERATURE".to_string(),
        ends: wrong_nobel.turn + 30,
        ours: 0.0,
        leader: 30.0,
    }]);
    AdvancedAi::new().advanced_envoys(&mut wrong_nobel, 0, GrandStrategy::Science, None);
    assert_eq!(wrong_nobel.envoys_at(0, peace_target), 0);
    assert_eq!(wrong_nobel.envoys_at(0, science_target), 3);

    let (mut peace, peace_target, science_target) = board();
    peace.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_PEACE".to_string(),
        ends: peace.turn + 30,
        ours: 0.0,
        leader: 30.0,
    }]);
    AdvancedAi::new().advanced_envoys(&mut peace, 0, GrandStrategy::Science, None);
    assert_eq!(
        peace.envoys_at(0, peace_target),
        3,
        "the current pool reaches a live Favor source immediately"
    );
    assert_eq!(peace.suzerain_of(peace_target), Some(0));
    assert_eq!(peace.envoys_at(0, science_target), 0);
    assert_eq!(peace.players[0].envoys_free, 0);

    let (mut expiring, peace_target, science_target) = board();
    expiring.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_PEACE".to_string(),
        ends: expiring.turn + 1,
        ours: 0.0,
        leader: 30.0,
    }]);
    AdvancedAi::new().advanced_envoys(&mut expiring, 0, GrandStrategy::Science, None);
    assert_eq!(
        expiring.envoys_at(0, peace_target),
        0,
        "a suzerainty whose Favor starts after the clock receives no stale score"
    );
    assert_eq!(expiring.envoys_at(0, science_target), 3);
}

/// Nobel Peace scores Favor generated while its host clock is live.  A
/// non-Diplomacy plan therefore needs to take a fitting wildcard from its
/// ordinary deck for a direct Favor card now, then give the seat back once the
/// host withdraws the contest.  The Dark Age Broadcast Center bargain remains
/// out: its Science/Culture downside is not free score.
#[test]
fn live_nobel_peace_preempts_a_wildcard_for_direct_favor_then_releases_it() {
    let board = || {
        let mut game = Game::new(2, 32, 24, 5_420, 250, 0);
        let settler = game
            .player_unit_ids(0)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .expect("starting settler");
        game.apply(0, &Action::FoundCity { unit: settler })
            .expect("found city");
        game.turn = 180;
        game.world_era = 7;
        game.players[0].age = "dark".to_string();
        game.players[0].government = Some("autocracy".to_string());
        game.players[0].civics.extend([
            crate::name!("political_philosophy"),
            crate::name!("exodus_imperative"),
            crate::name!("smart_power_doctrine"),
        ]);
        game.apply(
            0,
            &Action::SlotPolicy {
                policy: crate::name!("future_victory_science"),
            },
        )
        .expect("the ordinary Science wildcard fits");
        assert!(
            game.available_policies(0)
                .contains(&crate::name!("future_victory_diplomatic")),
            "the fixture needs the real +4 Favor-per-turn policy"
        );
        assert!(
            game.available_policies(0)
                .contains(&crate::name!("disinformation_campaign")),
            "the fixture also exposes the Dark Age Broadcast Center bargain"
        );
        game
    };
    let policies = |game: &mut Game| {
        let mut ai = AdvancedAi::new();
        ai.refresh_research_weight(game);
        ai.strategic_policies(game, 0, GrandStrategy::Science);
    };

    let mut ordinary = board();
    policies(&mut ordinary);
    assert!(ordinary.players[0]
        .policies
        .contains(&crate::name!("future_victory_science")));
    assert!(!ordinary.players[0]
        .policies
        .contains(&crate::name!("future_victory_diplomatic")));

    let mut wrong_nobel = board();
    wrong_nobel.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_LITERATURE".to_string(),
        ends: wrong_nobel.turn + 30,
        ours: 0.0,
        leader: 50.0,
    }]);
    policies(&mut wrong_nobel);
    assert!(wrong_nobel.players[0]
        .policies
        .contains(&crate::name!("future_victory_science")));
    assert!(!wrong_nobel.players[0]
        .policies
        .contains(&crate::name!("future_victory_diplomatic")));

    let mut peace = board();
    peace.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_PEACE".to_string(),
        ends: peace.turn + 30,
        ours: 0.0,
        leader: 50.0,
    }]);
    policies(&mut peace);
    assert!(peace.players[0]
        .policies
        .contains(&crate::name!("future_victory_diplomatic")));
    assert!(
        !peace.players[0]
            .policies
            .contains(&crate::name!("future_victory_science")),
        "the timed +4 Favor stream must replace the ordinary wildcard while Peace is live"
    );
    assert!(
        !peace.players[0]
            .policies
            .contains(&crate::name!("disinformation_campaign")),
        "the -10% Science/-10% Culture Dark Age bargain is not free Nobel Peace score"
    );

    peace.replace_host_competitions(Vec::new());
    policies(&mut peace);
    assert!(peace.players[0]
        .policies
        .contains(&crate::name!("future_victory_science")));
    assert!(!peace.players[0]
        .policies
        .contains(&crate::name!("future_victory_diplomatic")));

    let mut expiring = board();
    expiring.replace_host_competitions(vec![crate::game::HostCompetition {
        kind: "EMERGENCY_NOBEL_PRIZE_PEACE".to_string(),
        ends: expiring.turn + 1,
        ours: 0.0,
        leader: 50.0,
    }]);
    policies(&mut expiring);
    assert!(expiring.players[0]
        .policies
        .contains(&crate::name!("future_victory_science")));
    assert!(!expiring.players[0]
        .policies
        .contains(&crate::name!("future_victory_diplomatic")));
}

#[test]
fn saturated_wartime_economy_values_core_infrastructure_and_caps_units() {
    let ai = AdvancedAi::new();
    let legacy = AdvancedAi::legacy();
    let one_science = Yields {
        science: 1.0,
        ..Yields::default()
    };
    let one_culture = Yields {
        culture: 1.0,
        ..Yields::default()
    };
    assert!(
        ai.yield_value(one_science, GrandStrategy::Conquest)
            >= ai.yield_value(one_science, GrandStrategy::Expansion)
    );
    assert!(
        ai.yield_value(one_culture, GrandStrategy::Conquest)
            >= ai.yield_value(one_culture, GrandStrategy::Expansion),
        "an active war must not make civic progress less useful than expansion"
    );
    assert_eq!(
        legacy.yield_value(one_science, GrandStrategy::Conquest),
        1.7,
        "the advanced_v1 evaluation anchor keeps its historical science weight"
    );
    assert_eq!(
        legacy.yield_value(one_culture, GrandStrategy::Conquest),
        0.8,
        "the advanced_v1 evaluation anchor keeps its historical culture weight"
    );

    let mut game = Game::new(2, 24, 16, 73_101, 250, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("starting settler");
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("found city");
    let city = game.player_city_ids(0)[0];
    clear_barbarian_fixture(&mut game);
    install_ai_test_district(&mut game, city, "campus");
    install_ai_test_district(&mut game, city, "theater_square");
    game.players[0].techs.insert(crate::name!("writing"));
    game.players[0].civics.insert(crate::name!("drama_poetry"));
    for _ in 0..4 {
        game.spawn_test_unit("warrior", 0, game.cities[&city].pos);
    }
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: game.player_city_ids(1).first().copied(),
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let counts = ai.counts(&game, 0);
    let warrior = Item::Unit {
        unit: crate::name!("warrior"),
    };
    let library = Item::Building {
        building: crate::name!("library"),
    };
    let amphitheater = Item::Building {
        building: crate::name!("amphitheater"),
    };
    let campus_project = Item::Project {
        project: crate::name!("campus_research_grants"),
    };
    let theater_project = Item::Project {
        project: crate::name!("theater_square_festival"),
    };
    assert!(game.can_produce(0, city, &library));
    assert!(game.can_produce(0, city, &amphitheater));
    assert!(
        ai.production_value(&game, 0, city, &warrior, &plan, &counts) < -1_000.0,
        "five land units for one safe city are beyond the conquest ceiling"
    );
    assert!(
        legacy.production_value(&game, 0, city, &warrior, &plan, &counts) > -1_000.0,
        "the new unit ceiling stays outside the advanced_v1 evaluation anchor"
    );
    let library_value = ai.production_value(&game, 0, city, &library, &plan, &counts);
    let amphitheater_value = ai.production_value(&game, 0, city, &amphitheater, &plan, &counts);
    assert!(
        library_value > ai.production_value(&game, 0, city, &campus_project, &plan, &counts),
        "the missing first Campus building must beat a quiet repeatable project"
    );
    assert!(
        amphitheater_value > ai.production_value(&game, 0, city, &theater_project, &plan, &counts),
        "the missing first Theater building must beat a quiet repeatable project"
    );

    game.players[0].government = Some("theocracy".to_string());
    game.players[0].civics.extend([
        crate::name!("recorded_history"),
        crate::name!("medieval_faires"),
        crate::name!("the_enlightenment"),
        crate::name!("opera_ballet"),
    ]);
    game.players[0].policies.clear();
    ai.strategic_policies(&mut game, 0, GrandStrategy::Conquest);
    assert!(
        game.players[0]
            .policies
            .contains(&crate::name!("rationalism")),
        "a saturated army should use an economic slot to multiply Campus buildings"
    );
    assert!(
        game.players[0]
            .policies
            .contains(&crate::name!("grand_opera")),
        "a saturated army should use the other economic slot for Theater buildings"
    );
}

#[test]
fn conquest_without_city_objective_holds_a_garrison_until_the_target_exists() {
    let mut game = Game::new_full(2, 24, 16, 73_102, 250, 0, false);
    for pid in 0..2 {
        game.current = pid;
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .expect("starting settler");
        game.apply(pid, &Action::FoundCity { unit: settler })
            .expect("found city");
    }
    game.current = 0;
    let home = game.player_city_ids(0)[0];
    let target = game.player_city_ids(1)[0];
    for unit in game.player_unit_ids(0) {
        if game.rules.units[game.units[&unit].kind].class == "military" {
            game.remove_unit(unit);
        }
    }
    let position = game.cities[&home].pos;
    game.spawn_test_unit("warrior", 0, position);
    game.spawn_test_unit("warrior", 0, position);
    game.players[0].gold = 0.0;
    game.players[0].gold_per_turn = -8.0;

    let no_objective = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let appointed = StrategicPlan {
        target_city: Some(target),
        ..no_objective.clone()
    };
    let ai = AdvancedAi::new();
    let warrior = Item::Unit {
        unit: crate::name!("warrior"),
    };
    let counts = ai.counts(&game, 0);

    assert_eq!(counts.military, 2);
    assert!(
        ai.production_value(&game, 0, home, &warrior, &no_objective, &counts) < -1_000.0,
        "a conquest label without a city objective must not keep buying units"
    );
    assert!(
        ai.production_value(&game, 0, home, &warrior, &appointed, &counts) > 0.0,
        "appointing a real city must reopen the offensive force package"
    );
}

fn found_nearby_test_city(game: &mut Game, owner: usize, anchor: Pos) -> u32 {
    let position = game
        .map
        .tiles
        .iter()
        .filter(|(_, tile)| {
            tile.owner_city.is_none() && game.rules.is_passable(tile) && !game.rules.is_water(tile)
        })
        .map(|(position, _)| *position)
        .find(|position| {
            (4..=10).contains(&game.wdist(anchor, *position))
                    && game
                        .cities
                        .values()
                        .all(|city| game.wdist(city.pos, *position) >= 4)
                    // Units staged here must be able to walk out: skip sites
                    // ringed by water and mountains.
                    && game
                        .nbrs(*position)
                        .iter()
                        .filter(|neighbour| {
                            game.map.get(**neighbour).is_some_and(|tile| {
                                game.rules.is_passable(tile) && !game.rules.is_water(tile)
                            })
                        })
                        .count()
                        >= 3
        })
        .expect("test map has a nearby city site");
    game.found_city_for(owner, position, None)
}

/// A small Pangaea on which the shipped rush has exactly one legal victim
/// and a starting land melee unit can route to its staging ring.
fn connected_rush_fixture() -> Game {
    for seed in 560_000..560_064 {
        let mut game = Game::new_full(2, 24, 16, seed, 200, 0, false);
        for pid in 0..2 {
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .expect("each major starts with a settler");
            let position = game.units[&settler].pos;
            game.found_city_for(pid, position, None);
            game.remove_unit(settler);
        }
        game.current = 0;
        game.record_contact(0, 1);
        let mut rush = AdvancedAi::new();
        rush.early_rush = true;
        let Some((target, capital)) = rush.early_rush_victim(&game, 0) else {
            continue;
        };
        if target != 1 {
            continue;
        }
        let objective = game.cities[&capital].pos;
        let connected = game.player_unit_ids(0).into_iter().any(|unit| {
            let spec = &game.rules.units[game.units[&unit].kind];
            spec.class == "military"
                && spec.is_melee_capable()
                && !matches!(spec.domain.as_deref(), Some("sea" | "air"))
                && game.wdist(game.units[&unit].pos, objective) > RUSH_STAGING_RANGE
                && game
                    .route_step(unit, objective, RUSH_STAGING_RANGE)
                    .is_some()
        });
        if connected {
            return game;
        }
    }
    panic!("the fixed seed window needs one route-connected rush fixture")
}

/// Turn the ring immediately outside the selector's staging range into
/// water. A pre-embarkation land unit then has no route to any tile within
/// the range, while the capital's geometric distance remains unchanged.
fn split_capital_from_land_route(game: &mut Game, capital: Pos) {
    let barrier: BTreeSet<Pos> = game
        .wdisk(capital, RUSH_STAGING_RANGE + 1)
        .into_iter()
        .filter(|position| game.wdist(*position, capital) == RUSH_STAGING_RANGE + 1)
        .collect();
    for tile in game.map.tiles.values_mut() {
        if barrier.contains(&tile.pos) {
            tile.terrain = crate::name!("ocean");
            tile.feature = None;
        }
    }
}

/// One city, at war with a rival far too strong to fight, and no enemy
/// anywhere near home — `assess`'s first arm, with only its power-gap half
/// true.
fn outgunned_at_war_fixture() -> (Game, AdvancedAi) {
    let mut game = Game::new_full(2, 24, 16, 5_150, 200, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|id| game.units[id].kind == "settler")
        .expect("a starting settler");
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let rival_settler = game
        .player_unit_ids(1)
        .into_iter()
        .find(|id| game.units[id].kind == "settler")
        .expect("a rival settler");
    // Not `Action::FoundCity`: it is player 0's turn and the engine refuses.
    game.found_city_for(1, game.units[&rival_settler].pos, None);
    // Make the rival overwhelming, at home, so `threatened_city` stays
    // None and only the power gap can fire the arm.
    let rival_home = game.cities[&game.player_city_ids(1)[0]].pos;
    for position in game.wdisk(rival_home, 3) {
        if game.units_at(position).is_empty() && !game.rules.is_water(&game.map.tiles[&position]) {
            game.spawn_test_unit("swordsman", 1, position);
        }
    }
    game.at_war.insert((0, 1));
    game.at_war.insert((1, 0));
    (game, AdvancedAi::new())
}

#[test]
fn a_defensive_posture_that_cannot_win_is_not_held_for_ever() {
    let (mut game, ai) = outgunned_at_war_fixture();
    let opening = ai.assess(&game, 0);
    assert_eq!(
        opening.strategy,
        GrandStrategy::Recovery,
        "the fixture must exercise the defensive-war arm"
    );
    assert!(
        opening.threatened_city.is_none(),
        "only the power-gap half of the trigger may be true here"
    );

    // Held it for longer than a battlefield posture is worth. Untreated,
    // the arm re-fires for ever: its own condition is one Recovery cannot
    // resolve, which is how a live run spent 160 turns here.
    game.turn = 100;
    let mut untreated = AdvancedAi::new();
    // Production enables the bound by default; disable it explicitly for
    // this counterfactual control.
    untreated.bounded_recovery = false;
    untreated.plan = Some(opening.clone());
    untreated.major_war_since = Some(0);
    assert_eq!(untreated.assess(&game, 0).strategy, GrandStrategy::Recovery);

    let mut bounded = AdvancedAi::new();
    bounded.bounded_recovery = true;
    bounded.plan = Some(opening.clone());
    bounded.major_war_since = Some(0);
    assert_ne!(
        bounded.assess(&game, 0).strategy,
        GrandStrategy::Recovery,
        "a posture the empire has held past the limit must release"
    );

    // ⚠ And it must NOT release early: a battlefield posture is allowed to
    // do its job first.
    let mut fresh = AdvancedAi::new();
    fresh.bounded_recovery = true;
    fresh.plan = Some(opening);
    fresh.major_war_since = Some(game.turn.saturating_sub(1));
    assert_eq!(
        fresh.assess(&game, 0).strategy,
        GrandStrategy::Recovery,
        "the bound must not fire on a war that started last turn"
    );
}

#[test]
fn an_impossible_victory_denial_keeps_a_stale_major_war_defensive() {
    let (mut game, _) = outgunned_at_war_fixture();
    game.turn = 100;
    game.players[1].science_projects.extend([
        "launch_earth_satellite".to_string(),
        "launch_moon_landing".to_string(),
        "launch_mars_colony".to_string(),
        "exoplanet_expedition".to_string(),
    ]);
    game.players[1].exoplanet_distance = 42.0;

    let mut ai = AdvancedAi::new();
    ai.major_war_since = Some(0);
    assert_eq!(
        ai.victory_denial(&game, 0),
        Some((1, GrandStrategy::Conquest)),
        "the fixture needs a terminal Science counter"
    );
    assert!(
        game.military_power(0) * 2.0 < game.military_power(1),
        "the fixture needs an impossible counterattack"
    );
    let mut anchor = AdvancedAi::legacy();
    anchor.bounded_recovery = true;
    anchor.major_war_since = Some(0);
    assert_eq!(
        anchor.assess(&game, 0).strategy,
        GrandStrategy::Conquest,
        "advanced_v1 keeps the historical stale-denial path"
    );
    assert_eq!(
        ai.assess(&game, 0).strategy,
        GrandStrategy::Recovery,
        "a stale defense must not send its last army into an impossible denial"
    );
}

#[test]
fn a_released_recovery_posture_does_not_rearm_next_turn() {
    let (mut game, _) = outgunned_at_war_fixture();
    game.turn = 100;

    let mut bounded = AdvancedAi::new();
    bounded.bounded_recovery = true;
    bounded.major_war_since = Some(0);
    let released = bounded.assess(&game, 0);
    assert_ne!(released.strategy, GrandStrategy::Recovery);

    // ⚠ The regression this pins. Keyed on the PLAN's age, leaving Recovery
    // reset the clock and the very next assessment fell straight back into
    // it — a 1-in-25 duty cycle rather than a release. Keyed on the war's
    // age it stays out, because the war did not get younger.
    bounded.plan = Some(released);
    for turn in [101u32, 102, 110, 140] {
        game.turn = turn;
        assert_ne!(
            bounded.assess(&game, 0).strategy,
            GrandStrategy::Recovery,
            "the bound re-armed on turn {turn}"
        );
    }
}

#[test]
fn connected_rush_matches_the_unconditional_plan_on_pangaea() {
    let game = connected_rush_fixture();
    let mut unconditional = AdvancedAi::new();
    unconditional.early_rush = true;
    let expected = unconditional.assess(&game, 0);
    assert!(expected.rush, "the fixture must exercise the treatment");

    let mut connected = AdvancedAi::new();
    connected.early_rush = true;
    connected.route_connected_rush = true;
    assert!(connected.freeze_rush_route_targets(&game, 0));
    assert_eq!(connected.assess(&game, 0), expected);
}

#[test]
fn disconnected_rush_stays_on_the_ordinary_plan() {
    let mut game = connected_rush_fixture();
    let capital = game.cities[&game.player_city_ids(1)[0]].pos;
    split_capital_from_land_route(&mut game, capital);

    let mut connected = AdvancedAi::new();
    connected.early_rush = true;
    connected.route_connected_rush = true;
    assert!(connected.freeze_rush_route_targets(&game, 0));
    assert_eq!(connected.rush_route_targets, Some(BTreeSet::new()));

    let ordinary = AdvancedAi::new().assess(&game, 0);
    let selected = connected.assess(&game, 0);
    assert!(!selected.rush);
    assert_eq!(selected, ordinary);
}

#[test]
fn rush_route_targets_are_frozen_after_the_first_complete_capital_state() {
    let mut game = connected_rush_fixture();
    let mut connected = AdvancedAi::new();
    connected.early_rush = true;
    connected.route_connected_rush = true;
    assert!(connected.freeze_rush_route_targets(&game, 0));
    let frozen = connected.rush_route_targets.clone();
    assert_eq!(frozen, Some(BTreeSet::from([1])));

    for unit in game.player_unit_ids(0) {
        game.remove_unit(unit);
    }
    assert!(!connected.freeze_rush_route_targets(&game, 0));
    assert_eq!(connected.rush_route_targets, frozen);
}

#[test]
fn a_committed_connected_rush_finishes_after_the_route_changes() {
    let mut game = connected_rush_fixture();
    let mut connected = AdvancedAi::new();
    connected.early_rush = true;
    connected.route_connected_rush = true;
    assert!(connected.freeze_rush_route_targets(&game, 0));

    let capital = game.cities[&game.player_city_ids(1)[0]].pos;
    split_capital_from_land_route(&mut game, capital);
    game.at_war.insert((0, 1));
    game.turn = RUSH_WINDOW_CLOSES + 1;

    assert_eq!(
        connected
            .early_rush_victim(&game, 0)
            .map(|(target, _)| target),
        Some(1)
    );
    assert!(connected.assess(&game, 0).rush);
}

#[test]
fn conquest_ai_spends_a_device_on_the_hard_city_but_spares_its_own() {
    let mut game = Game::new_full(2, 24, 16, 91_802, 200, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.found_city_for(pid, game.units[&settler].pos, None);
        game.remove_unit(settler);
    }
    let target_city = game.player_city_ids(1)[0];
    let target = game.cities[&target_city].pos;
    game.at_war.insert((0, 1));
    game.players[0]
        .counters
        .insert("project_effect:thermonuclear_devices".to_string(), 1);
    game.players[0].explored.insert(target);
    game.cities.get_mut(&target_city).unwrap().wall_hp = 300;
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: Some(target_city),
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    };
    let ai = AdvancedAi::targeting(VictoryTarget::Domination);

    // A friendly scout in the blast must hold the launch.
    let radius = game.rules.wmds["thermonuclear_device"].blast_radius;
    let picket_pos =
        game.wdisk(target, radius)
            .into_iter()
            .find(|position| {
                *position != target
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
                    && game.units_at(*position).is_empty()
            })
            .expect("blast ring has an open land tile");
    let picket = game.spawn_test_unit("scout", 0, picket_pos);
    ai.advanced_wmd_strikes(&mut game, 0, &plan);
    assert_eq!(
        game.players[0].counters["project_effect:thermonuclear_devices"], 1,
        "no launch while a friendly unit stands in the blast"
    );

    game.remove_unit(picket);
    ai.advanced_wmd_strikes(&mut game, 0, &plan);
    assert_eq!(
        game.players[0].counters["project_effect:thermonuclear_devices"], 0,
        "the hard city draws the device once the blast is clean"
    );
    assert!(game.map.tiles[&target].fallout_until > game.turn);
}

