#[test]
fn strategic_plan_denies_an_imminent_victory_instead_of_farming_a_weak_rival() {
    let establish_capitals = |game: &mut Game| {
        for pid in 0..3 {
            let settler = game
                .player_unit_ids(pid)
                .into_iter()
                .find(|unit| game.units[unit].kind == "settler")
                .unwrap();
            game.current = pid;
            game.apply(pid, &Action::FoundCity { unit: settler })
                .unwrap();
        }
        game.current = 0;
        game.turn = 190;
        for rival in 1..game.players.len() {
            game.record_contact(0, rival);
        }
    };

    let mut science = Game::new_full(3, 36, 22, 761, 300, 0, false);
    establish_capitals(&mut science);
    science.players[2].science_projects.extend([
        "launch_earth_satellite".to_string(),
        "launch_moon_landing".to_string(),
        "launch_mars_colony".to_string(),
        "exoplanet_expedition".to_string(),
    ]);
    science.players[2].exoplanet_distance = 42.0;
    let ai = AdvancedAi::new();
    let pressure = ai.rival_victory_pressure(&science, 2);
    assert_eq!(pressure.strategy, GrandStrategy::Science);
    assert!(pressure.progress >= 95);
    let plan = ai.assess(&science, 0);
    assert_eq!(plan.strategy, GrandStrategy::Conquest);
    assert_eq!(plan.target_player, Some(2));

    let mut culture = Game::new_full(3, 36, 22, 762, 300, 0, false);
    establish_capitals(&mut culture);
    culture.players[1].tourism_lifetime = 300_000.0;
    culture.players[0].culture_lifetime = 100.0;
    culture.players[2].culture_lifetime = 100.0;
    let pressure = ai.rival_victory_pressure(&culture, 1);
    assert_eq!(pressure.strategy, GrandStrategy::Culture);
    assert_eq!(pressure.progress, 100);
    let plan = ai.assess(&culture, 0);
    assert_eq!(plan.strategy, GrandStrategy::Culture);
    assert_eq!(plan.target_player, Some(1));
}

#[test]
fn science_denial_starts_when_the_final_expedition_launches() {
    let mut game = Game::new_full(3, 36, 22, 76_120, 300, 0, false);
    for pid in 0..3 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    game.turn = 190;
    for rival in 1..game.players.len() {
        game.record_contact(0, rival);
    }
    game.players[2]
        .science_projects
        .insert("exoplanet_expedition".to_string());

    let ai = AdvancedAi::new();
    let pressure = ai.rival_victory_pressure(&game, 2);
    assert_eq!(pressure.strategy, GrandStrategy::Science);
    assert_eq!(pressure.progress, 78);
    assert_eq!(
        ai.victory_denial(&game, 0),
        Some((2, GrandStrategy::Conquest)),
        "the final launch must leave the defender time to begin its counter-campaign"
    );
    let plan = ai.assess(&game, 0);
    assert_eq!(plan.strategy, GrandStrategy::Conquest);
    assert_eq!(plan.target_player, Some(2));

    // The three response shapes on one position, so the arms cannot
    // silently converge: ship declares, `counter_in_lane` races the same
    // rival, `counter_stand_down` lets this threat pass. All three read
    // the identical pressure, so what separates them is the answer and
    // never the perception.
    let mut in_lane = AdvancedAi::new();
    in_lane.counter_in_lane = true;
    assert_eq!(
        in_lane.victory_denial(&game, 0),
        Some((2, GrandStrategy::Science))
    );

    let mut stand_down = AdvancedAi::new();
    stand_down.counter_stand_down = true;
    assert_eq!(stand_down.victory_denial(&game, 0), None);
    assert_eq!(stand_down.rival_victory_pressure(&game, 2).progress, 78);
}

/// ★★★★ In the last quarter the shipped score term reads whoever leads on
/// score as "close to winning", and the stock counter is a war: run
/// civvis-20260816T110555Z declared on a rival with twice its score at
/// t211 and lost a city. See `counter_in_lane`. On the live seat the same
/// alarm asks for the Expansion lane; the stock controller still declares.
#[test]
fn the_live_seat_races_the_score_leader_instead_of_declaring_on_it() {
    let mut game = Game::new_full(3, 36, 22, 76_121, 300, 0, false);
    for pid in 0..3 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    game.turn = 240; // the last quarter of 300
    for rival in 1..game.players.len() {
        game.record_contact(0, rival);
    }
    // Rival 2 leads the tally by a wide margin: sixty techs at two points each.
    let techs: Vec<Name> = game.rules.techs.keys().take(60).copied().collect();
    for tech in techs {
        game.players[2].techs.insert(tech);
    }
    assert!(
        game.score(2) > 2 * game.score(0),
        "fixture precondition: rival 2 leads on score ({} vs {})",
        game.score(2),
        game.score(0)
    );

    let stock = AdvancedAi::new();
    let pressure = stock.rival_victory_pressure(&game, 2);
    assert_eq!(
        pressure.strategy,
        GrandStrategy::Expansion,
        "the score clock names the leader"
    );
    assert!(
        pressure.progress >= 78,
        "and calls it close to winning ({})",
        pressure.progress
    );
    assert_eq!(
        stock.victory_denial(&game, 0),
        Some((2, GrandStrategy::Conquest)),
        "the stock controller answers the score leader with a war"
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(live.counter_in_lane, "the live seat carries the treatment");
    assert_eq!(
        live.victory_denial(&game, 0),
        Some((2, GrandStrategy::Expansion)),
        "the live seat races the leader in its lane and declares on nobody"
    );
    let plan = live.assess(&game, 0);
    assert_ne!(
        (plan.strategy, plan.target_player),
        (GrandStrategy::Conquest, Some(2)),
        "no denial war on the live seat: {:?}",
        (plan.strategy, plan.target_player)
    );

    // Withheld: the same seat declares as the stock controller does.
    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge();
    withheld.disable_counter_in_lane();
    assert_eq!(
        withheld.victory_denial(&game, 0),
        Some((2, GrandStrategy::Conquest))
    );
    assert!(!AdvancedAi::new().counter_in_lane);
    assert!(!AdvancedAi::legacy().counter_in_lane);
}

#[test]
fn religious_match_point_interrupts_before_the_winning_conversion() {
    let mut game = Game::new_full(4, 42, 24, 7_621, 300, 0, false);
    for pid in 0..4 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    game.turn = 150;
    for rival in 1..game.players.len() {
        game.record_contact(0, rival);
    }
    game.players[3].religion = Some("Runaway Faith".to_string());
    for owner in 1..4 {
        let city = game.player_city_ids(owner)[0];
        game.cities
            .get_mut(&city)
            .unwrap()
            .pressure
            .insert("Runaway Faith".to_string(), 1_000.0);
    }

    let ai = AdvancedAi::new();
    let pressure = ai.rival_victory_pressure(&game, 3);
    assert_eq!(pressure.strategy, GrandStrategy::Religion);
    assert_eq!(pressure.progress, 75);
    assert_eq!(
        ai.victory_denial(&game, 0),
        Some((3, GrandStrategy::Conquest)),
        "a non-founder must attack before the fourth conversion ends the game"
    );
    let plan = ai.assess(&game, 0);
    assert_eq!(plan.strategy, GrandStrategy::Conquest);
    assert_eq!(plan.target_player, Some(3));

    game.players[0].religion = Some("Home Faith".to_string());
    let home = game.player_city_ids(0)[0];
    game.cities
        .get_mut(&home)
        .unwrap()
        .pressure
        .insert("Home Faith".to_string(), 1_000.0);
    assert_eq!(
        ai.victory_denial(&game, 0),
        Some((3, GrandStrategy::Religion)),
        "a founder should defend its cities with its own religion"
    );
}

#[test]
fn religious_match_point_spends_the_reserve_only_in_own_faith_cities() {
    let mut game = Game::new_full(4, 42, 24, 7_622, 300, 0, false);
    for pid in 0..4 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    let converted_capital = game.player_city_ids(0)[0];
    let faithful_city = found_test_city(&mut game, 0);
    install_test_holy_site(&mut game, converted_capital);
    install_test_holy_site(&mut game, faithful_city);
    game.current = 0;
    game.turn = 150;
    game.players[0].religion = Some("Home Faith".to_string());
    game.players[0].holy_city = Some(converted_capital);
    game.players[0].techs.insert(crate::name!("astrology"));
    game.players[0].faith = 200.0;
    game.players[3].religion = Some("Runaway Faith".to_string());
    game.cities
        .get_mut(&converted_capital)
        .unwrap()
        .pressure
        .insert("Runaway Faith".to_string(), 1_000.0);
    game.cities
        .get_mut(&faithful_city)
        .unwrap()
        .pressure
        .insert("Home Faith".to_string(), 1_000.0);
    for owner in 1..4 {
        let city = game.player_city_ids(owner)[0];
        game.cities
            .get_mut(&city)
            .unwrap()
            .pressure
            .insert("Runaway Faith".to_string(), 1_000.0);
    }

    let mut ai = AdvancedAi::new();
    let emergency = ai
        .victory_denial(&game, 0)
        .is_some_and(|(_, counter)| counter == GrandStrategy::Religion);
    assert!(emergency);
    ai.religious_spending(&mut game, 0, emergency);

    let missionary = game
        .units
        .values()
        .find(|unit| unit.owner == 0 && unit.kind == "missionary")
        .expect("match-point defense should spend the ordinary Faith reserve");
    assert_eq!(missionary.religion.as_deref(), Some("Home Faith"));
    assert_eq!(missionary.pos, game.cities[&faithful_city].pos);
    assert!(game.players[0].faith < 1.0);
}

/// The military answer to a religious offensive: step onto an adjacent
/// enemy Missionary inside our own territory and condemn it.
#[test]
fn military_units_step_onto_and_condemn_enemy_missionaries() {
    let mut game = Game::new_full(2, 30, 18, 7_631, 200, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    game.at_war.insert((0, 1));
    let home = game.cities[&game.player_city_ids(0)[0]].pos;
    // Both staged tiles must be free: the capital's own starting units
    // stand in this ring, and a friendly unit already there blocks the
    // step onto the intruder.
    let soldier_tile = game
        .nbrs(home)
        .into_iter()
        .find(|p| {
            game.units_at(*p).is_empty()
                && game
                    .map
                    .get(*p)
                    .is_some_and(|t| game.rules.is_passable(t) && !game.rules.is_water(t))
        })
        .unwrap();
    // Condemning is a defense of our own territory, so the intruder has
    // to stand on a tile the capital actually owns - one that borders
    // both the soldier and the city centre.
    let intruder_tile = game
        .nbrs(soldier_tile)
        .into_iter()
        .find(|p| {
            *p != home
                && game.nbrs(home).contains(p)
                && game.units_at(*p).is_empty()
                && game
                    .map
                    .get(*p)
                    .is_some_and(|t| game.rules.is_passable(t) && !game.rules.is_water(t))
        })
        .unwrap();
    for position in [soldier_tile, intruder_tile] {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.improvement = None;
        tile.hills = false;
    }
    game.map.set_river_edge(soldier_tile, intruder_tile, false);
    let soldier = game.spawn_test_unit("warrior", 0, soldier_tile);
    let missionary = game.spawn_test_unit("missionary", 1, intruder_tile);
    game.units.get_mut(&missionary).unwrap().religion = Some("Rival Faith".to_string());

    let mut ai = AdvancedAi::new();
    assert!(ai.condemn_step(&mut game, 0, soldier), "should engage");
    assert!(
        !game.units.contains_key(&missionary),
        "the adjacent missionary should be condemned, not ignored"
    );
}

#[test]
fn non_founder_buys_adopted_faith_missionaries_to_defend_home() {
    let mut game = Game::new_full(3, 42, 24, 7_624, 300, 0, false);
    for pid in 0..3 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    let converted_capital = game.player_city_ids(0)[0];
    let adopted_city = found_test_city(&mut game, 0);
    install_test_holy_site(&mut game, adopted_city);
    game.current = 0;
    game.turn = 150;
    // Player 0 founded no religion; a living rival's faith holds their
    // capital while a founderless neighbor faith holds the second city.
    game.players[0].techs.insert(crate::name!("astrology"));
    game.players[0].faith = 600.0;
    game.players[1].religion = Some("Runaway Faith".to_string());
    game.cities
        .get_mut(&converted_capital)
        .unwrap()
        .pressure
        .insert("Runaway Faith".to_string(), 1_000.0);
    game.cities
        .get_mut(&adopted_city)
        .unwrap()
        .pressure
        .insert("Neighbor Faith".to_string(), 1_000.0);

    let mut ai = AdvancedAi::new();
    let threat = ai
        .home_conversion_threat(&game, 0)
        .expect("a rival majority in the capital is a home threat");
    assert_eq!(threat, "Runaway Faith");
    ai.religious_defense(&mut game, 0, &threat);

    let missionary = game
        .units
        .values()
        .find(|unit| unit.owner == 0 && unit.kind == "missionary")
        .expect("defense should buy a missionary of the adopted faith");
    let missionary = missionary.id;
    assert_eq!(
        game.units[&missionary].religion.as_deref(),
        Some("Neighbor Faith")
    );
    assert_eq!(game.units[&missionary].pos, game.cities[&adopted_city].pos);

    // The player founded no religion, so the unit controller must follow the
    // purchased unit's adopted faith rather than returning early. Place it in
    // the converted capital to prove it spends a charge reconverting the home
    // city instead of becoming an inert Faith sink.
    let converted_pos = game.cities[&converted_capital].pos;
    let before = game.cities[&converted_capital]
        .pressure
        .get("Neighbor Faith")
        .copied()
        .unwrap_or(0.0);
    game.units.get_mut(&missionary).unwrap().pos = converted_pos;
    game.units.get_mut(&missionary).unwrap().moves_left = 4.0;
    assert!(AdvancedAi::new().advanced_missionary_step(&mut game, 0, missionary, false));
    assert!(
        game.cities[&converted_capital]
            .pressure
            .get("Neighbor Faith")
            .copied()
            .unwrap_or(0.0)
            > before,
        "the adopted defender must spread into the threatened capital"
    );
    assert_eq!(game.units[&missionary].charges, 2);
}

#[test]
fn non_founder_buys_defense_before_an_approaching_rival_missionary_spreads() {
    let mut game = Game::new_full(3, 42, 24, 7_625, 300, 0, false);
    for pid in 0..3 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    let capital = game.player_city_ids(0)[0];
    let adopted_city = found_test_city(&mut game, 0);
    install_test_holy_site(&mut game, adopted_city);
    game.current = 0;
    game.turn = 150;
    game.players[0].techs.insert(crate::name!("astrology"));
    game.players[0].faith = 600.0;
    game.players[1].religion = Some("Runaway Faith".to_string());
    for city in [capital, adopted_city] {
        game.cities
            .get_mut(&city)
            .unwrap()
            .pressure
            .insert("Neighbor Faith".to_string(), 1_000.0);
    }

    let capital_pos = game.cities[&capital].pos;
    let approach =
        game.wdisk(capital_pos, 4)
            .into_iter()
            .find(|position| {
                game.wdist(*position, capital_pos) == 4
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
                    && game.units_at(*position).is_empty()
            })
            .expect("the capital has a clear one-turn religious approach tile");
    let rival = game.spawn_test_unit("missionary", 1, approach);
    game.units.get_mut(&rival).unwrap().religion = Some("Runaway Faith".to_string());

    let mut ai = AdvancedAi::new();
    assert_eq!(
        ai.home_conversion_threat(&game, 0).as_deref(),
        Some("Runaway Faith"),
        "the approaching rival must trigger defense before it adds pressure"
    );
    ai.religious_defense(&mut game, 0, "Runaway Faith");

    let defender = game
        .units
        .values()
        .find(|unit| unit.owner == 0 && unit.kind == "missionary")
        .expect("the still-adopted Holy Site must buy the early defender");
    assert_eq!(defender.religion.as_deref(), Some("Neighbor Faith"));
    assert_eq!(defender.pos, game.cities[&adopted_city].pos);
    assert!(game.players[0].faith < 600.0);
}

#[test]
fn apostle_launches_inquisition_before_evangelizing_when_core_is_lost() {
    let mut game = Game::new_full(2, 30, 18, 7_623, 200, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    let holy_city = game.player_city_ids(0)[0];
    let converted_city = found_test_city(&mut game, 0);
    game.current = 0;
    game.players[0].religion = Some("Home Faith".to_string());
    game.players[0].holy_city = Some(holy_city);
    game.players[0].religion_beliefs = vec!["work_ethic".to_string(), "tithe".to_string()];
    game.cities
        .get_mut(&holy_city)
        .unwrap()
        .pressure
        .insert("Home Faith".to_string(), 1_000.0);
    game.cities
        .get_mut(&converted_city)
        .unwrap()
        .pressure
        .insert("Rival Faith".to_string(), 1_000.0);
    let apostle = game.spawn_test_unit("apostle", 0, game.cities[&holy_city].pos);
    game.units.get_mut(&apostle).unwrap().religion = Some("Home Faith".to_string());

    assert!(AdvancedAi::new().advanced_religious_step(&mut game, 0, apostle, false));
    assert!(!game.units.contains_key(&apostle));
    assert_eq!(
        game.players[0]
            .counters
            .get("inquisition")
            .copied()
            .unwrap_or(0),
        1
    );
    assert_eq!(game.players[0].religion_beliefs.len(), 2);
}

#[test]
fn religious_strategy_reconverts_its_core_before_chasing_foreign_cities() {
    let mut game = Game::new_full(2, 30, 18, 763, 200, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    game.players[0].religion = Some("Our Faith".to_string());
    let home = game.player_city_ids(0)[0];
    let foreign = game.player_city_ids(1)[0];
    game.cities
        .get_mut(&home)
        .unwrap()
        .pressure
        .insert("Rival Faith".to_string(), 1_000.0);
    game.cities
        .get_mut(&foreign)
        .unwrap()
        .pressure
        .insert("Rival Faith".to_string(), 1_000.0);
    let missionary = game.spawn_test_unit("missionary", 0, game.cities[&home].pos);
    game.units.get_mut(&missionary).unwrap().religion = Some("Our Faith".to_string());

    assert!(AdvancedAi::new().advanced_missionary_step(&mut game, 0, missionary, true));
    assert!(
        game.cities[&home]
            .pressure
            .get("Our Faith")
            .copied()
            .unwrap_or(0.0)
            > 0.0
    );
    assert_eq!(game.units[&missionary].pos, game.cities[&home].pos);
}

#[test]
fn nonreligious_strategy_reinforces_its_founded_faith_before_conversion() {
    let mut game = Game::new_full(2, 30, 18, 7_634, 200, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    game.players[0].religion = Some("Our Faith".to_string());
    let home = game.player_city_ids(0)[0];
    game.cities.get_mut(&home).unwrap().pressure.extend([
        ("Our Faith".to_string(), 1_000.0),
        ("Rival Faith".to_string(), 600.0),
    ]);
    assert_eq!(game.city_religion(&game.cities[&home]), Some("Our Faith"));
    let missionary = game.spawn_test_unit("missionary", 0, game.cities[&home].pos);
    game.units.get_mut(&missionary).unwrap().religion = Some("Our Faith".to_string());
    let before = game.cities[&home].pressure["Our Faith"];

    assert!(AdvancedAi::targeting(VictoryTarget::Science)
        .advanced_missionary_step(&mut game, 0, missionary, false));
    assert!(game.cities[&home].pressure["Our Faith"] > before);
    assert_eq!(game.units[&missionary].charges, 2);
    game.units.get_mut(&missionary).unwrap().moves_left = 4.0;
    assert!(
        !AdvancedAi::targeting(VictoryTarget::Science)
            .advanced_missionary_step(&mut game, 0, missionary, false),
        "a defensive unit must hold once its home is safe instead of starting a foreign crusade"
    );
}

#[test]
fn missionary_routes_to_spread_range_around_a_mountain_detour() {
    let mut game = Game::new_full(2, 30, 18, 7_633, 200, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    game.players[0].religion = Some("Our Faith".to_string());
    let target_city = game.player_city_ids(1)[0];
    let target = game.cities[&target_city].pos;
    game.cities
        .get_mut(&target_city)
        .unwrap()
        .pressure
        .insert("Rival Faith".to_string(), 1_000.0);
    // Saturate the missionary's own capital so the rival city is the only
    // thing left to convert. This case is about *routing*, and without it
    // the answer depends on where the generated map happened to put home:
    // a capital that lands near the missionary outscores a foreign city
    // three hexes away and the unit walks west, which is a correct choice
    // about a different question.
    let home_city = game.player_city_ids(0)[0];
    game.cities
        .get_mut(&home_city)
        .unwrap()
        .pressure
        .insert("Our Faith".to_string(), 100_000.0);

    let start = (target.0 - 3, target.1);
    let direct = (target.0 - 2, target.1);
    let detour = (target.0 - 2, target.1 - 1);
    let onward = (target.0 - 1, target.1 - 1);
    for position in [start, direct, detour, onward] {
        assert!(game.map.tiles.contains_key(&position));
    }
    // Flatten the approach so the detour is the only obstacle. Reading the
    // generated terrain instead left the case at the mercy of whatever the
    // seed happened to put beside the target - a river edge or a cliff in
    // the corridor blocks the first step for reasons the case is not about.
    for position in game.wdisk(target, 4) {
        if position == target {
            continue;
        }
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
        tile.hills = false;
        tile.resource = None;
        tile.improvement = None;
        tile.district = None;
        tile.wonder = None;
        tile.cliff_edges = [false; 6];
        tile.river_edges = [false; 6];
    }
    game.map.tiles.get_mut(&direct).unwrap().terrain = crate::name!("mountain");

    let missionary = game.spawn_test_unit("missionary", 0, start);
    game.units.get_mut(&missionary).unwrap().religion = Some("Our Faith".to_string());
    let ai = AdvancedAi::new();
    assert!(ai.advanced_missionary_step(&mut game, 0, missionary, true));
    assert_eq!(
        game.wdist(game.units[&missionary].pos, target),
        3,
        "the first legal route step must accept a sideways mountain detour"
    );

    for _ in 0..8 {
        if !game.units.contains_key(&missionary) || game.units[&missionary].charges < 3 {
            break;
        }
        game.units.get_mut(&missionary).unwrap().moves_left = 4.0;
        assert!(ai.advanced_missionary_step(&mut game, 0, missionary, true));
    }
    assert!(
        !game.units.contains_key(&missionary) || game.units[&missionary].charges < 3,
        "a reachable foreign city must receive a spread instead of trapping the unit"
    );
}

#[test]
fn apostles_complete_one_worship_and_one_enhancer_belief_for_the_plan() {
    let mut game = Game::new(2, 24, 16, 7_632, 200, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    game.players[0].religion = Some("Planned Faith".to_string());
    game.players[0].religion_beliefs = vec!["work_ethic".to_string(), "tithe".to_string()];
    let ai = AdvancedAi::targeting(VictoryTarget::Science);

    let first = game.spawn_test_unit("apostle", 0, game.cities[&city].pos);
    game.units.get_mut(&first).unwrap().religion = Some("Planned Faith".to_string());
    assert!(ai.advanced_religious_step(&mut game, 0, first, false));
    assert!(game.players[0]
        .religion_beliefs
        .contains(&"wat".to_string()));

    let second = game.spawn_test_unit("apostle", 0, game.cities[&city].pos);
    game.units.get_mut(&second).unwrap().religion = Some("Planned Faith".to_string());
    assert!(ai.advanced_religious_step(&mut game, 0, second, false));
    assert_eq!(game.players[0].religion_beliefs.len(), 4);
    assert_eq!(
        game.players[0]
            .religion_beliefs
            .iter()
            .filter(|belief| game.rules.beliefs.enhancer.contains_key(*belief))
            .count(),
        1
    );
    assert_eq!(
        game.players[0]
            .religion_beliefs
            .iter()
            .filter(|belief| game.rules.beliefs.worship.contains_key(*belief))
            .count(),
        1
    );
}

#[test]
fn science_target_reserves_a_spaceport_then_queues_the_project_chain() {
    let mut g = Game::new(2, 24, 16, 71, 200, 0);
    let settler = g
        .player_unit_ids(0)
        .into_iter()
        .find(|uid| g.units[uid].kind == "settler")
        .unwrap();
    g.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = g.player_city_ids(0)[0];
    let site = g.cities[&city]
        .owned_tiles
        .iter()
        .copied()
        .find(|position| *position != g.cities[&city].pos)
        .unwrap();
    {
        let tile = g.map.tiles.get_mut(&site).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.resource = None;
        tile.hills = false;
    }
    g.players[0].techs.insert(crate::name!("rocketry"));
    let ai = AdvancedAi::targeting(VictoryTarget::Science);
    ai.science_production(&mut g, 0);
    let spaceport = match g.cities[&city].queue.first() {
        Some(Item::District { district, pos }) if district == "spaceport" => *pos,
        queued => panic!("expected a queued spaceport, got {queued:?}"),
    };

    g.cities.get_mut(&city).unwrap().queue.clear();
    g.cities
        .get_mut(&city)
        .unwrap()
        .districts
        .insert(crate::name!("spaceport"), spaceport);
    ai.science_production(&mut g, 0);
    assert!(matches!(
        g.cities[&city].queue.first(),
        Some(Item::Project { project }) if project == "launch_earth_satellite"
    ));
}

/// ★★★★ The last fifty turns of a Settler game are a tally, and the science
/// lane spent them on a launch pad (civvis-20260816T093036Z: Spaceport at
/// t226 + Manhattan Project, 871 vs 1,157; T101521Z: two Spaceports after
/// t220, 787 vs 1,198). See `score_horizon`. A one-city empire on turn 170
/// of 200 with Rocketry only cannot finish four projects, their techs and
/// fifty light-years in thirty turns: the treated seat prices the launch
/// pad at nothing and skips the space-race governor, journaling why; the
/// same seat on turn 20 races as before, as does the withheld arm.
#[test]
fn a_space_race_that_cannot_finish_before_the_turn_limit_is_not_started() {
    let fresh = || {
        let mut g = Game::new(2, 24, 16, 71, 200, 0);
        let settler = g
            .player_unit_ids(0)
            .into_iter()
            .find(|uid| g.units[uid].kind == "settler")
            .unwrap();
        g.apply(0, &Action::FoundCity { unit: settler }).unwrap();
        let city = g.player_city_ids(0)[0];
        let site = g.cities[&city]
            .owned_tiles
            .iter()
            .copied()
            .find(|position| *position != g.cities[&city].pos)
            .unwrap();
        {
            let tile = g.map.tiles.get_mut(&site).unwrap();
            tile.terrain = crate::name!("plains");
            tile.feature = None;
            tile.resource = None;
            tile.hills = false;
        }
        g.players[0].techs.insert(crate::name!("rocketry"));
        (g, city)
    };

    // Late: thirty turns left.
    let (mut late, city) = fresh();
    late.turn = 170;
    let mut live = AdvancedAi::targeting(VictoryTarget::Science);
    live.enable_live_bridge_universe();
    assert!(live.score_horizon, "the live seat carries the treatment");
    assert!(
        !live.space_race_can_finish(&late, 0),
        "four projects, their techs and fifty light-years do not fit in thirty turns"
    );
    let journal = crate::reasoning::Journal::recording();
    live.attach_journal(journal.handle());
    // The space-race governor is skipped and says why; the withheld arm
    // queues the launch pad exactly as the historical controller does.
    live.space_race_production(&mut late, 0);
    assert!(
        !late.cities[&city].queue.iter().any(|item| matches!(
            item,
            Item::District { district, .. } if district == "spaceport"
        )),
        "no Spaceport is queued thirty turns from the tally: {:?}",
        late.cities[&city].queue
    );
    assert!(
        journal
            .since(0)
            .thoughts
            .iter()
            .any(|thought| thought.headline.starts_with("The space race cannot finish")),
        "the skipped race is journaled"
    );
    let (mut late_withheld, city_withheld) = fresh();
    late_withheld.turn = 170;
    let mut withheld = AdvancedAi::targeting(VictoryTarget::Science);
    withheld.enable_live_bridge_universe();
    withheld.disable_score_horizon();
    withheld.space_race_production(&mut late_withheld, 0);
    assert!(
        matches!(
            late_withheld.cities[&city_withheld].queue.first(),
            Some(Item::District { district, .. }) if district == "spaceport"
        ),
        "the withheld arm still reserves the launch pad"
    );

    // With turns to spare the same seat still races.
    let (mut early, _) = fresh();
    early.max_turns = 100_000;
    assert!(
        live.space_race_can_finish(&early, 0),
        "with the limit far away the chain fits and the race is on"
    );

    // Nuclear lane: a bomb that cannot be finished prices zero, one that can does not.
    assert!(!live.nuclear_lane_can_finish(&late, 0, city, "manhattan_project"));
    let (mut boundless, city) = fresh();
    boundless.max_turns = 0;
    assert!(
        live.space_race_can_finish(&boundless, 0),
        "no turn limit, no horizon"
    );
    assert!(live.nuclear_lane_can_finish(&boundless, 0, city, "manhattan_project"));

    // Defaults: off for the stock and frozen controllers.
    assert!(!AdvancedAi::new().score_horizon);
    assert!(!AdvancedAi::legacy().score_horizon);
}

/// ★★★ Four cities claimed the empire-wide first-pad rung at once because
/// it counts finished districts only. Live run civvis-20260817T022159Z:
/// Aquileia t144, Ostia t146, Arretium t146, Brundisium t157 — 119
/// city-turns, 11% of everything that empire built, for one usable pad.
/// See `one_launch_pad`. Two cities with Rocketry and no pad: the treated
/// seat pays 3,000 only in the better producer and 250 in the other, and
/// once the better producer has the pad in its queue neither city claims
/// the rung again. The withheld arm pays both, as the historical
/// controller does.
#[test]
fn the_empire_reserves_one_launch_pad_in_the_city_that_would_run_the_race() {
    let mut game = Game::new(2, 32, 24, 5_414, 250, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("starting settler");
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("found city");
    let first = game.player_city_ids(0)[0];
    let second = found_test_city(&mut game, 0);
    game.players[0].techs.insert(crate::name!("rocketry"));
    game.turn = 140;
    // The turn limit is a separate treatment (`score_horizon`); hold it
    // far enough away that both cities price a real pad and the rung is
    // the only thing under test.
    game.max_turns = 100_000;
    // The measured shape: one city out-produces the other, and the race
    // would be run there.
    install_ai_test_district(&mut game, first, "industrial_zone");
    game.cities.get_mut(&first).unwrap().pop = 14;
    game.cities.get_mut(&second).unwrap().pop = 4;

    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    };
    let pad = Item::District {
        district: crate::name!("spaceport"),
        pos: game.cities[&first].pos,
    };
    let _ = second;

    let mut live = AdvancedAi::targeting(VictoryTarget::Science);
    live.enable_live_bridge_universe();
    assert!(live.one_launch_pad, "the live seat carries the treatment");
    live.refresh_research_weight(&game);
    let mut withheld = AdvancedAi::targeting(VictoryTarget::Science);
    withheld.enable_live_bridge_universe();
    withheld.disable_one_launch_pad();
    withheld.refresh_research_weight(&game);
    let counts = live.counts(&game, 0);

    let racer = live
        .launch_pad_site(&game, 0)
        .expect("no pad stands or is queued, so one city holds the rung");
    let passed = *game
        .player_city_ids(0)
        .iter()
        .find(|cid| **cid != racer)
        .expect("the empire has a second city");
    assert!(
        game.city_yields(racer).production >= game.city_yields(passed).production,
        "the rung goes to the better producer"
    );

    let held = live.production_value(&game, 0, racer, &pad, &plan, &counts);
    let passed_over = live.production_value(&game, 0, passed, &pad, &plan, &counts);
    let unrestrained = withheld.production_value(&game, 0, passed, &pad, &plan, &counts);
    assert!(
        unrestrained > passed_over,
        "the passed-over city drops the 3,000 rung it used to claim: \
             {unrestrained} withheld vs {passed_over} treated"
    );
    assert_eq!(
        held,
        withheld.production_value(&game, 0, racer, &pad, &plan, &counts),
        "the racer keeps the rung untouched"
    );
    assert!(
        passed_over > 0.0,
        "a second launch site stays a legal fallback"
    );

    // A pad already on its way ends the rung for everyone — including the
    // city building it, which does not need to be told twice.
    game.cities.get_mut(&racer).unwrap().queue.push(pad.clone());
    assert_eq!(
        live.launch_pad_site(&game, 0),
        None,
        "a queued pad is the pad the empire is getting"
    );
    let after = live.production_value(&game, 0, racer, &pad, &plan, &counts);
    assert!(
        after < held,
        "no second claim while the first is building: {after} vs {held}"
    );

    // And a pad that stands ends it too.
    game.cities.get_mut(&racer).unwrap().queue.clear();
    install_ai_test_district(&mut game, racer, "spaceport");
    assert_eq!(
        live.launch_pad_site(&game, 0),
        None,
        "a standing pad is enough"
    );

    // Defaults: off for the stock and frozen controllers.
    assert!(!AdvancedAi::new().one_launch_pad);
    assert!(!AdvancedAi::legacy().one_launch_pad);
}

#[test]
fn science_target_parallelizes_lasers_across_cities_without_local_spaceport_spam() {
    let mut game = Game::new_full(1, 34, 20, 71_002, 320, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|uid| game.units[uid].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let mut cities = game.player_city_ids(0);
    while cities.len() < 3 {
        let center = game
            .map
            .tiles
            .iter()
            .find(|(position, tile)| {
                tile.owner_city.is_none()
                    && game.rules.is_passable(tile)
                    && !game.rules.is_water(tile)
                    && cities
                        .iter()
                        .all(|city| game.wdist(**position, game.cities[city].pos) >= 7)
            })
            .map(|(position, _)| *position)
            .unwrap();
        game.found_city_for(0, center, None);
        cities = game.player_city_ids(0);
    }
    game.players[0].techs = game.rules.techs.keys().cloned().collect();
    game.players[0].civics = game.rules.civics.keys().cloned().collect();
    game.players[0].science_projects.extend([
        "launch_earth_satellite".to_string(),
        "launch_moon_landing".to_string(),
        "launch_mars_colony".to_string(),
        "exoplanet_expedition".to_string(),
    ]);
    for city in &cities {
        game.cities.get_mut(city).unwrap().pop = 12;
        for position in game.cities[city].owned_tiles.clone() {
            if position == game.cities[city].pos {
                continue;
            }
            let tile = game.map.tiles.get_mut(&position).unwrap();
            tile.terrain = crate::name!("plains");
            tile.feature = None;
            tile.hills = false;
            tile.resource = None;
            tile.improvement = None;
            tile.district = None;
            tile.district_foundation = None;
            tile.wonder = None;
        }
    }
    for city in cities.iter().take(2) {
        let position = game.cities[city]
            .owned_tiles
            .iter()
            .copied()
            .find(|position| *position != game.cities[city].pos)
            .unwrap();
        game.map.tiles.get_mut(&position).unwrap().district = Some(crate::name!("spaceport"));
        game.cities
            .get_mut(city)
            .unwrap()
            .districts
            .insert(crate::name!("spaceport"), position);
    }
    game.cities.get_mut(&cities[0]).unwrap().queue = vec![Item::Project {
        project: crate::name!("lagrange_laser_station"),
    }];

    let ai = AdvancedAi::targeting(VictoryTarget::Science);
    ai.science_production(&mut game, 0);
    assert_eq!(
        cities
            .iter()
            .filter(|city| matches!(
                game.cities[city].queue.first(),
                Some(Item::Project { project }) if project == "lagrange_laser_station"
            ))
            .count(),
        2
    );

    ai.science_production(&mut game, 0);
    assert!(matches!(
        game.cities[&cities[2]].queue.first(),
        Some(Item::District { district, .. }) if district == "spaceport"
    ));

    let duplicate = Item::District {
        district: crate::name!("spaceport"),
        pos: game.district_sites(cities[0], crate::name!("spaceport"))[0],
    };
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    assert!(
        ai.production_value(&game, 0, cities[0], &duplicate, &plan, &ai.counts(&game, 0))
            <= -10_000.0
    );
}

#[test]
fn district_search_values_unique_families_and_real_housing_need() {
    let mut game = Game::new_full(1, 20, 14, 71_001, 200, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    let site = game.cities[&city]
        .owned_tiles
        .iter()
        .copied()
        .find(|position| *position != game.cities[&city].pos)
        .unwrap();
    {
        let tile = game.map.tiles.get_mut(&site).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.resource = None;
        tile.hills = true;
    }

    for (unique, family) in [
        ("seowon", "campus"),
        ("lavra", "holy_site"),
        ("hansa", "industrial_zone"),
        ("bath", "aqueduct"),
        ("mbanza", "neighborhood"),
    ] {
        assert_eq!(game.district_family(Name::new(unique)), Name::new(family));
    }

    let ai = AdvancedAi::targeting(VictoryTarget::Science);
    let counts = ai.counts(&game, 0);
    let mut plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let seowon = Item::District {
        district: crate::name!("seowon"),
        pos: site,
    };
    let science_value = ai.production_value(&game, 0, city, &seowon, &plan, &counts);
    plan.strategy = GrandStrategy::Expansion;
    let expansion_value = ai.production_value(&game, 0, city, &seowon, &plan, &counts);
    assert!(
        science_value > expansion_value,
        "a Seowon must inherit the Campus science strategy bonus"
    );

    // The rules engine, not a second AI-only district cap, decides
    // eligibility. A high-population city with an undeveloped specialty
    // core should still recognize the urgent housing value of a
    // Neighborhood.
    for district in ["campus", "holy_site", "commercial_hub"] {
        game.cities
            .get_mut(&city)
            .unwrap()
            .districts
            .insert(Name::new(district), site);
    }
    game.cities.get_mut(&city).unwrap().pop = 12;
    let crowded = Item::District {
        district: crate::name!("neighborhood"),
        pos: site,
    };
    let crowded_value = ai.production_value(&game, 0, city, &crowded, &plan, &counts);
    game.cities.get_mut(&city).unwrap().pop = 2;
    let roomy_value = ai.production_value(&game, 0, city, &crowded, &plan, &counts);
    assert!(crowded_value > -1_000.0);
    assert!(
        crowded_value > roomy_value,
        "appeal housing must be worth more when growth is constrained"
    );
}

#[test]
fn production_search_uses_incremental_remaining_cost_for_paused_builds() {
    let mut game = Game::new_full(1, 20, 14, 71_002, 200, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.players[0].civ = "Egypt".to_string();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    let monument = Item::Building {
        building: crate::name!("monument"),
    };
    let builder = Item::Unit {
        unit: crate::name!("builder"),
    };
    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let ai = AdvancedAi::new();
    let counts = ai.counts(&game, 0);
    let fresh = ai.production_value(&game, 0, city, &monument, &plan, &counts);

    game.apply(
        0,
        &Action::Produce {
            city,
            item: monument.clone(),
        },
    )
    .unwrap();
    game.cities.get_mut(&city).unwrap().production = 20.0;
    game.apply(
        0,
        &Action::Produce {
            city,
            item: builder,
        },
    )
    .unwrap();
    let resumed = ai.production_value(&game, 0, city, &monument, &plan, &counts);

    assert_eq!(
        game.item_remaining_cost_for_city(0, city, &monument),
        game.item_cost_for_city(0, city, &monument) - 20.0
    );
    assert!(
        resumed > fresh,
        "incremental evaluation should prefer finishing invested infrastructure"
    );
}

#[test]
fn the_settling_gates_and_the_cascade_disagree_about_the_city_target() {
    // The defect this repairs is an internal disagreement, so the test states
    // both sides of it. `delegated_cities` widens the cascade's target to
    // max(city_target, desired_cities); the settling gates in advanced.rs read
    // the bare plan number. On the shipped genome that is 4 against 3 for the
    // whole opening.
    let shipped = AdvancedAi::new();
    assert!(
        shipped.plan_city_target,
        "the redirect this repairs is live in production"
    );
    let gene = shipped.base.w.city_target as usize;
    assert!(
        gene >= 4,
        "shipped genome settles toward at least four cities"
    );

    let opening = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        // What `assess` yields before the era cadence widens it.
        desired_cities: 3,
        assessed_turn: 10,
        rush: false,
    };
    assert_eq!(
        shipped.settlement_target(&opening),
        3,
        "today both settling gates stop one city short of the cascade"
    );

    let mut repaired = AdvancedAi::new();
    repaired.enable_settlement_gap_target();
    assert_eq!(
        repaired.settlement_target(&opening),
        gene,
        "the repair honours the target the cascade is already settling toward"
    );

    // It must WIDEN only. Once the plan has grown past the gene, the plan
    // wins — otherwise this would narrow late expansion, which is the failure
    // mode `city_target_floor` was removed for.
    let late = StrategicPlan {
        desired_cities: 9,
        assessed_turn: 140,
        ..opening
    };
    assert_eq!(repaired.settlement_target(&late), 9);
    assert_eq!(shipped.settlement_target(&late), 9);
}

#[test]
fn splitting_the_every_lane_composite_leaves_it_exactly_as_it_was() {
    // The halves exist to attribute a −95 Elo composite. If enabling the
    // composite stopped covering a lane it used to cover, the live bridge
    // would change behaviour and the attribution would be measured against
    // the wrong incumbent.
    let mut composite = AdvancedAi::new();
    composite.enable_governor_every_lane();
    assert!(composite.governor_victory_lanes && composite.governor_expansion_lane);

    let mut halves = AdvancedAi::new();
    halves.enable_governor_victory_lanes();
    halves.enable_governor_expansion_lane();
    assert_eq!(
        composite.governor_victory_lanes,
        halves.governor_victory_lanes
    );
    assert_eq!(
        composite.governor_expansion_lane,
        halves.governor_expansion_lane
    );

    // The withhold still clears both, so `live_without_governor_every_lane`
    // keeps measuring the whole composite.
    composite.disable_governor_every_lane();
    assert!(!composite.governor_victory_lanes && !composite.governor_expansion_lane);

    let mut victory_only = AdvancedAi::new();
    victory_only.enable_governor_victory_lanes();
    assert!(!victory_only.governor_expansion_lane);
    let mut expansion_only = AdvancedAi::new();
    expansion_only.enable_governor_expansion_lane();
    assert!(!expansion_only.governor_victory_lanes);
}

#[test]
fn the_governor_recovery_withhold_changes_who_decides_a_recovery_city() {
    // A pure routing flag can look alive in the struct and be dead in the
    // dispatch, which is how a withhold arm ends up measuring nothing. Pin
    // both halves: the shipped controller carries the governor into Recovery,
    // the withhold arm does not, and nothing else moves.
    let shipped = AdvancedAi::new();
    assert!(
        shipped.governor_in_recovery,
        "production ships with the governor deciding Recovery cities"
    );
    let mut withheld = AdvancedAi::new();
    withheld.disable_governor_in_recovery();
    assert!(!withheld.governor_in_recovery);
    assert_eq!(shipped.governor_every_lane, withheld.governor_every_lane);
    assert_eq!(shipped.victory_planning, withheld.victory_planning);
}

#[test]
fn a_spawned_builder_carries_the_charges_production_priced() {
    // `Game::builder_charges` is the number the survey prices; spawning
    // must hand out exactly the same count or the valuation is priced
    // against a unit that does not exist.
    let mut game = Game::new_full(1, 20, 14, 71_006, 200, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    let pos = game.units[&settler].pos;
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let uid = game.spawn_unit("builder", 0, pos);
    assert_eq!(game.units[&uid].charges, game.builder_charges(0));
    assert!(game.builder_charges(0) >= 1);
}

#[test]
fn the_builder_survey_prices_work_where_the_quota_priced_headcount() {
    let mut game = Game::new_full(1, 20, 14, 71_008, 200, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    let builder = Item::Unit {
        unit: crate::name!("builder"),
    };
    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let frozen = AdvancedAi::new();
    let counts = frozen.counts(&game, 0);
    let quota = frozen.production_value(&game, 0, city, &builder, &plan, &counts);

    let mut surveyed = AdvancedAi::new();
    surveyed.enable_builder_reward_survey();
    let priced = surveyed.production_value(&game, 0, city, &builder, &plan, &counts);

    // A fresh capital ringed by unimproved tiles has real jobs open, so
    // the survey bids a real number — and a different one from the flat
    // quota, which is the fires-check that the flag reaches the arm.
    let rewards = surveyed.builder_job_rewards(&game, 0, game.cities[&city].pos, plan.strategy);
    assert!(
        !rewards.is_empty(),
        "a fresh capital must have open builder jobs"
    );
    assert!(
        rewards.windows(2).all(|pair| pair[0] >= pair[1]),
        "job rewards must come back best-first"
    );
    assert!(priced > 0.0);
    assert!(
        (priced - quota).abs() > 1e-9,
        "the survey arm must not silently reproduce the quota"
    );

    // The Builders already alive claim the head of the job list: each
    // additional live Builder must never raise the next one's price.
    let mut fewer_jobs = counts;
    fewer_jobs.builders = 3;
    let saturated = surveyed.production_value(&game, 0, city, &builder, &plan, &fewer_jobs);
    assert!(
        saturated <= priced,
        "a fourth builder cannot be worth more than the first"
    );
}

#[test]
fn a_first_luxury_outbids_a_duplicate_and_a_worked_tile_outbids_an_idle_one() {
    let mut game = Game::new_full(1, 20, 14, 71_010, 200, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    // Any luxury the ruleset ties to a builder improvement; BTreeMap
    // order keeps the pick deterministic.
    let (resource, improvement) = game
        .rules
        .improvements
        .iter()
        .filter(|(_, spec)| spec.builder_buildable)
        .flat_map(|(name, spec)| {
            spec.resources
                .iter()
                .map(move |resource| (*resource, *name))
        })
        .find(|(resource, _)| {
            game.rules
                .resources
                .get(resource.as_str())
                .is_some_and(|spec| spec.class == "luxury")
        })
        .expect("the ruleset ties at least one luxury to a builder improvement");
    let pos = game.cities[&city]
        .owned_tiles
        .iter()
        .copied()
        .find(|pos| *pos != game.cities[&city].pos)
        .unwrap();
    game.map.tiles.get_mut(&pos).unwrap().resource = Some(resource);

    let ai = AdvancedAi::new();
    let strategy = GrandStrategy::Expansion;
    let holder = game.cities[&city].clone();
    let first =
        ai.surveyed_improvement_value(&game, 0, &holder, pos, &improvement, strategy, true, 2);

    // Connect a second copy elsewhere: the survey must now price this
    // tile as a duplicate.
    let other = game.cities[&city]
        .owned_tiles
        .iter()
        .copied()
        .find(|p| *p != pos && *p != game.cities[&city].pos)
        .unwrap();
    {
        let tile = game.map.tiles.get_mut(&other).unwrap();
        tile.resource = Some(resource);
        tile.improvement = Some(improvement);
    }
    let duplicate =
        ai.surveyed_improvement_value(&game, 0, &holder, pos, &improvement, strategy, true, 2);
    assert!(
        first > duplicate,
        "a first {resource} must outbid a duplicate ({first:.1} vs {duplicate:.1})"
    );

    // And the worked-likelihood weight: the same job on a tile no
    // citizen works keeps its connection value but sheds yield value.
    let idle =
        ai.surveyed_improvement_value(&game, 0, &holder, pos, &improvement, strategy, false, 2);
    assert!(
        first >= idle,
        "an unworked tile cannot be worth more than a worked one"
    );
}

#[test]
fn the_civs_own_unique_unit_earns_its_window() {
    let mut game = Game::new_full(1, 20, 14, 71_012, 200, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.players[0].civ = "Sumeria".to_string();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    let war_cart = Item::Unit {
        unit: crate::name!("war_cart"),
    };
    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let frozen = AdvancedAi::new();
    let counts = frozen.counts(&game, 0);
    let base = frozen.production_value(&game, 0, city, &war_cart, &plan, &counts);

    let mut credited = AdvancedAi::new();
    credited.enable_unit_cost_efficiency();
    let windowed = credited.production_value(&game, 0, city, &war_cart, &plan, &counts);
    assert!(
        windowed > base,
        "Sumeria's own War Cart must earn the unique window ({windowed:.1} vs {base:.1})"
    );

    // A rival civilization gets no credit for someone else's unique.
    game.players[0].civ = "Rome".to_string();
    let foreign = credited.production_value(&game, 0, city, &war_cart, &plan, &counts);
    assert!(
        foreign < windowed,
        "the window is the owner's alone ({foreign:.1} vs {windowed:.1})"
    );
}

#[test]
fn envoy_infrastructure_prices_only_reachable_future_envoys() {
    let mut game = Game::new_full(1, 20, 14, 71_004, 200, 1, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    game.players[0].government = Some("chiefdom".to_string());
    game.turn = 30;
    install_ai_test_district(&mut game, city, "diplomatic_quarter");

    let consulate = Item::Building {
        building: crate::name!("consulate"),
    };
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let stock = AdvancedAi::pre_policy_envoy();
    let mut treatment = AdvancedAi::pre_policy_envoy();
    treatment.envoy_infrastructure = true;
    let counts = stock.counts(&game, 0);
    let unseen = treatment.production_value(&game, 0, city, &consulate, &plan, &counts);
    let stock_value = stock.production_value(&game, 0, city, &consulate, &plan, &counts);
    assert_eq!(
        unseen, stock_value,
        "an unmet city-state must not leak into production valuation"
    );

    let minor = game
        .players
        .iter()
        .find(|player| player.is_minor && !player.is_barbarian && !player.is_free_city)
        .map(|player| player.id)
        .expect("fixture needs a city-state");
    game.record_contact(0, minor);
    let reachable = treatment.production_value(&game, 0, city, &consulate, &plan, &counts);
    assert!(
        reachable > stock_value,
        "a met, uncontrolled city-state must make Consulate influence valuable"
    );

    game.turn = game.max_turns;
    let expired = treatment.production_value(&game, 0, city, &consulate, &plan, &counts);
    let expired_stock = stock.production_value(&game, 0, city, &consulate, &plan, &counts);
    assert_eq!(
        expired, expired_stock,
        "income that begins after the game ends has no envoy value"
    );
}

#[test]
fn envoy_priority_reaches_adaptive_production_and_obeys_safety_gates() {
    let mut game = Game::new_full(2, 20, 14, 71_005, 500, 1, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    game.players[0].government = Some("chiefdom".to_string());
    game.players[0].techs.insert(crate::name!("mathematics"));
    game.turn = 30;
    let minor = game
        .players
        .iter()
        .find(|player| player.is_minor && !player.is_barbarian && !player.is_free_city)
        .map(|player| player.id)
        .expect("fixture needs a city-state");
    let rival = game
        .players
        .iter()
        .find(|player| {
            player.id != 0
                && player.alive
                && !player.is_minor
                && !player.is_barbarian
                && !player.is_free_city
        })
        .map(|player| player.id)
        .expect("fixture needs another major");
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    // The cleaned production default retains the direct priority route;
    // infrastructure valuation is a separate, evaluator-only arm. This
    // test pins the priority safety gates rather than that valuation.
    let treatment = AdvancedAi::new();

    let mut unmet = game.clone();
    assert!(!treatment.prioritize_envoy_infrastructure(&mut unmet, 0, &plan));
    assert!(unmet.cities[&city].queue.is_empty());

    let mut recovery = game.clone();
    recovery.record_contact(0, minor);
    let mut recovery_plan = plan.clone();
    recovery_plan.strategy = GrandStrategy::Recovery;
    assert!(!treatment.prioritize_envoy_infrastructure(&mut recovery, 0, &recovery_plan));
    assert!(recovery.cities[&city].queue.is_empty());

    let mut threatened = game.clone();
    threatened.record_contact(0, minor);
    let mut threatened_plan = plan.clone();
    threatened_plan.threatened_city = Some(city);
    assert!(!treatment.prioritize_envoy_infrastructure(&mut threatened, 0, &threatened_plan));

    let mut rushing = game.clone();
    rushing.record_contact(0, minor);
    let mut rush_plan = plan.clone();
    rush_plan.rush = true;
    assert!(!treatment.prioritize_envoy_infrastructure(&mut rushing, 0, &rush_plan));

    let mut major_war = game.clone();
    major_war.record_contact(0, minor);
    major_war.record_contact(0, rival);
    major_war
        .apply(0, &Action::DeclareWar { player: rival })
        .unwrap();
    assert!(!treatment.prioritize_envoy_infrastructure(&mut major_war, 0, &plan));

    let mut occupied = game.clone();
    occupied.record_contact(0, minor);
    let occupied_item = occupied
            .producible_items(0, city)
            .into_iter()
            .find(|item| {
                !matches!(item, Item::District { district, .. } if district == "diplomatic_quarter")
            })
            .expect("fixture needs an ordinary legal build");
    occupied
        .apply(
            0,
            &Action::Produce {
                city,
                item: occupied_item.clone(),
            },
        )
        .unwrap();
    assert!(!treatment.prioritize_envoy_infrastructure(&mut occupied, 0, &plan));
    assert_eq!(occupied.cities[&city].queue.first(), Some(&occupied_item));

    let mut quarter = game.clone();
    quarter.record_contact(0, minor);
    assert!(treatment.prioritize_envoy_infrastructure(&mut quarter, 0, &plan));
    assert!(matches!(
        quarter.cities[&city].queue.first(),
        Some(Item::District { district, .. }) if district == "diplomatic_quarter"
    ));

    // Pin the routing boundary as well as the helper. Once the opening
    // book is complete, an ordinary adaptive turn must reach this prepass
    // before `BasicAi::cities` fills the empty queue.
    let mut adaptive_turn = game.clone();
    adaptive_turn.record_contact(0, minor);
    let mut integrated = treatment.clone();
    integrated.base.book_pos = 4;
    integrated.plan = Some(plan.clone());
    integrated.last_city_count = 1;
    integrated.take_turn(&mut adaptive_turn, 0);
    assert!(matches!(
        adaptive_turn.cities[&city].queue.first(),
        Some(Item::District { district, .. }) if district == "diplomatic_quarter"
    ));

    let mut consulate = game.clone();
    consulate.record_contact(0, minor);
    install_ai_test_district(&mut consulate, city, "diplomatic_quarter");
    assert!(treatment.prioritize_envoy_infrastructure(&mut consulate, 0, &plan));
    assert!(matches!(
        consulate.cities[&city].queue.first(),
        Some(Item::Building { building }) if building == "consulate"
    ));

    let mut chancery = game.clone();
    chancery.record_contact(0, minor);
    install_ai_test_district(&mut chancery, city, "diplomatic_quarter");
    chancery
        .cities
        .get_mut(&city)
        .unwrap()
        .buildings
        .push(crate::name!("consulate"));
    chancery.players[0]
        .civics
        .insert(crate::name!("diplomatic_service"));
    assert!(treatment.prioritize_envoy_infrastructure(&mut chancery, 0, &plan));
    assert!(matches!(
        chancery.cities[&city].queue.first(),
        Some(Item::Building { building }) if building == "chancery"
    ));

    let mut expired = game.clone();
    expired.record_contact(0, minor);
    expired.turn = expired.max_turns;
    assert!(!treatment.prioritize_envoy_infrastructure(&mut expired, 0, &plan));
    assert!(expired.cities[&city].queue.is_empty());
}

#[test]
fn military_production_keeps_land_sea_and_air_force_gaps_separate() {
    let mut game = Game::new_full(1, 20, 14, 71_003, 120, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    for unit in game.player_unit_ids(0) {
        if game.rules.units[game.units[&unit].kind].class == "military" {
            game.remove_unit(unit);
        }
    }
    let water = game
        .map
        .tiles
        .iter()
        .find(|(_, tile)| game.rules.is_water(tile))
        .map(|(position, _)| *position)
        .unwrap();
    game.spawn_test_unit("galley", 0, water);
    let city = game.player_city_ids(0)[0];
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 1,
        assessed_turn: game.turn,
        rush: false,
    };
    let ai = AdvancedAi::targeting(VictoryTarget::Science);
    let counts = ai.counts(&game, 0);
    assert_eq!(counts.naval, 1);
    assert_eq!(counts.military - counts.naval - counts.aircraft, 0);

    let defender = Item::Unit {
        unit: crate::name!("warrior"),
    };
    assert!(
        ai.production_value(&game, 0, city, &defender, &plan, &counts) > 0.0,
        "a Galley cannot satisfy the empire's missing land-defense quota"
    );
}

