#[test]
fn peacetime_deterrence_redirects_an_adaptive_science_grant_into_a_defender() {
    // The live run `civvis-20260815T033005Z` reached turn 174 at 85 power
    // against the strongest met rival's 540, then repeatedly queued Campus
    // Research Grants through turn 251. It finished with two Warriors at 40
    // against India's 962. The live bridge was already raising its
    // deterrence target, but adaptive Science bypassed the production
    // governor that could spend it.
    let (mut game, city, home) = empire_with_a_capital(71_108);
    game.at_war.clear();
    game.record_contact(0, 1);
    let idle_city = found_nearby_test_city(&mut game, 0, home);
    for _ in 0..2 {
        game.spawn_test_unit("warrior", 1, anchor_at(&game, home, 15));
    }
    install_ai_test_district(&mut game, city, "campus");
    game.players[0].techs.insert(crate::name!("writing"));
    let grant = Item::Project {
        project: crate::name!("campus_research_grants"),
    };
    assert!(game.can_produce(0, city, &grant));
    game.apply(
        0,
        &Action::Produce {
            city,
            item: grant.clone(),
        },
    )
    .expect("queue Campus Research Grants");
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 1,
        assessed_turn: game.turn,
        rush: false,
    };

    // The frozen anchor leaves the science project alone: it has no live
    // peacetime deterrence treatment to turn a rival's observed army into
    // a production obligation.
    let anchor = AdvancedAi::legacy();
    anchor.redirect_repeatable_projects_for_force_gap(&mut game, 0, &plan);
    assert!(matches!(
        game.cities[&city].queue.first(),
        Some(Item::Project { project }) if *project == crate::name!("campus_research_grants")
    ));

    let mut live = AdvancedAi::new();
    live.enable_peacetime_deterrence();
    assert_eq!(
        live.enemy_weighted_army_target(&game, 0, 2),
        3,
        "the met rival raises the two-city peacetime floor before a declaration"
    );
    live.redirect_repeatable_projects_for_force_gap(&mut game, 0, &plan);
    assert!(matches!(
        game.cities[&city].queue.first(),
        Some(Item::Unit { unit }) if game.rules.units[unit].class == "military"
    ));
    assert!(matches!(
        game.cities[&idle_city].queue.first(),
        Some(Item::Unit { unit }) if game.rules.units[unit].class == "military"
    ));
}

#[test]
fn peaceful_city_plan_reclaims_a_research_grant_for_a_settler() {
    // In live run `civvis-20260815T033005Z`, Rome had four cities at
    // turn 121 when its plan rose to five. Its queues stayed on Campus
    // Research Grants until it lost a city at turn 195, then still never
    // started another Settler despite targets of six and seven. The
    // baseline governor had the widened target, but only sees empty
    // queues; this pins the handoff that reaches it.
    let (mut game, city, home) = empire_with_a_capital(71_109);
    game.at_war.clear();
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
    }
    game.cities.get_mut(&city).unwrap().pop = 3;
    install_ai_test_district(&mut game, city, "campus");
    game.players[0].techs.insert(crate::name!("writing"));
    let grant = Item::Project {
        project: crate::name!("campus_research_grants"),
    };
    assert!(game.can_produce(0, city, &grant));
    game.apply(
        0,
        &Action::Produce {
            city,
            item: grant.clone(),
        },
    )
    .expect("queue Campus Research Grants");
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 2,
        assessed_turn: game.turn,
        rush: false,
    };

    // The frozen anchor retains its existing project: this is a live
    // city-plan repair, not a new behavior for historical evaluations.
    let anchor = AdvancedAi::legacy();
    assert!(!anchor.plan_city_target);
    anchor.redirect_repeatable_projects_for_settlement_gap(&mut game, 0, &plan);
    assert_eq!(game.cities[&city].queue.first(), Some(&grant));

    let live = AdvancedAi::new();
    assert!(live.plan_city_target);

    // The handoff keeps the one-settler pipeline intact. A normal
    // in-flight Settler consumes the next planned seat, so its project is
    // not displaced merely because the target is still farther away.
    let mut one_in_flight = game.clone();
    one_in_flight.spawn_test_unit("settler", 0, home);
    let later_plan = StrategicPlan {
        desired_cities: 3,
        ..plan.clone()
    };
    live.redirect_repeatable_projects_for_settlement_gap(&mut one_in_flight, 0, &later_plan);
    assert_eq!(one_in_flight.cities[&city].queue.first(), Some(&grant));

    // A major war remains the force-production path's responsibility.
    let mut wartime = game.clone();
    wartime.at_war.insert((0, 1));
    live.redirect_repeatable_projects_for_settlement_gap(&mut wartime, 0, &plan);
    assert_eq!(wartime.cities[&city].queue.first(), Some(&grant));

    live.redirect_repeatable_projects_for_settlement_gap(&mut game, 0, &plan);
    assert!(matches!(
        game.cities[&city].queue.first(),
        Some(Item::Unit { unit }) if unit == "settler"
    ));
}

#[test]
fn severe_amenity_crisis_reclaims_one_research_grant_for_the_repair_chain() {
    // Live run `civvis-20260815T051714Z` kept every city on Campus Research
    // Grants while five host cities sat in the -3 through -5 bands. The
    // regular amenity lane is sound; the failure is that it never receives
    // an empty queue from the explicit Science producer.
    let (mut game, city, home) = empire_with_a_capital(71_110);
    game.at_war.clear();
    let other = found_nearby_test_city(&mut game, 0, home);
    game.players[0]
        .civics
        .insert(crate::name!("games_recreation"));
    game.players[0].techs.insert(crate::name!("writing"));
    for cid in [city, other] {
        let deficit_pop = (6..30)
            .find(|pop| {
                game.cities.get_mut(&cid).unwrap().pop = *pop;
                game.city_amenity_surplus(&game.cities[&cid]) <= -3
            })
            .expect("fixture reaches the severe Amenity band");
        game.cities.get_mut(&cid).unwrap().pop = deficit_pop;
        install_ai_test_district(&mut game, cid, "campus");
        let grant = Item::Project {
            project: crate::name!("campus_research_grants"),
        };
        assert!(game.can_produce(0, cid, &grant));
        game.apply(
            0,
            &Action::Produce {
                city: cid,
                item: grant,
            },
        )
        .expect("queue Campus Research Grants");
    }
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 2,
        assessed_turn: game.turn,
        rush: false,
    };

    // Ordinary and frozen controllers leave the historic project loop
    // alone; this is a separately ablatable live repair.
    let ordinary = AdvancedAi::new();
    assert!(!ordinary.amenity_project_preemption);
    ordinary.redirect_repeatable_projects_for_amenity_crisis(&mut game, 0, &plan, false);
    assert!(
        [city, other].into_iter().all(|cid| matches!(
            game.cities[&cid].queue.first(),
            Some(Item::Project { project }) if *project == crate::name!("campus_research_grants")
        )),
        "the live-only gate leaves normal project ordering unchanged"
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    assert!(live.amenity_project_preemption);
    live.redirect_repeatable_projects_for_amenity_crisis(&mut game, 0, &plan, false);
    let repair_city = [city, other]
            .into_iter()
            .find(|cid| matches!(
                game.cities[cid].queue.first(),
                Some(Item::District { district, .. }) if game.rules.districts[district].amenity > 0.0
            ))
            .expect("one severe city pauses its grant for an amenity district");
    let project_city = if repair_city == city { other } else { city };
    assert!(matches!(
        game.cities[&project_city].queue.first(),
        Some(Item::Project { project }) if *project == crate::name!("campus_research_grants")
    ));

    // One in-flight repair reserves the whole intervention. The next city
    // keeps its research grant instead of turning the emergency into a
    // blanket district order.
    live.redirect_repeatable_projects_for_amenity_crisis(&mut game, 0, &plan, false);
    assert!(matches!(
        game.cities[&project_city].queue.first(),
        Some(Item::Project { project }) if *project == crate::name!("campus_research_grants")
    ));

    // Once the district exists, the next reservation continues its direct
    // amenity building before starting a second district elsewhere.
    game.cities.get_mut(&repair_city).unwrap().queue.clear();
    install_ai_test_district(&mut game, repair_city, "entertainment_complex");
    let legal_repair_items = game.producible_items(0, repair_city);
    live.redirect_repeatable_projects_for_amenity_crisis(&mut game, 0, &plan, false);
    assert!(matches!(
            game.cities[&repair_city].queue.first(),
            Some(Item::Building { building }) if game.rules.buildings[building].amenity > 0.0
        ),
            "the next repair stage must be a direct Amenity building; legal: {legal_repair_items:?}, queued: {:?}",
            game.cities[&repair_city].queue.first()
        );
    live.disable_amenity_project_preemption();
    assert!(!live.amenity_project_preemption);
}

/// The Entertainment Complex carries no amenity of its own; the Arena it
/// hosts does. Priced by the district spec alone it scored like an empty
/// plot: no Entertainment Complex in four of the last five live runs and
/// 57–83% of city-turns Displeased. See `amenity_district_path`.
#[test]
fn an_amenity_district_is_worth_the_arena_it_hosts() {
    let (mut game, capital, _home) = empire_with_a_capital(71_113);
    game.players[0]
        .civics
        .insert(crate::name!("games_recreation"));
    // A Displeased city, host-calibrated the way the live mirror does it.
    let modeled = game.city_amenity_surplus(&game.cities[&capital]);
    game.observed_city_amenity_adjustments
        .insert(capital, -1 - modeled);
    let site = game
        .district_sites(capital, crate::name!("entertainment_complex"))
        .into_iter()
        .next()
        .expect("the capital has a plot for an Entertainment Complex");
    let complex = Item::District {
        district: crate::name!("entertainment_complex"),
        pos: site,
    };
    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let counts = EmpireCounts::default();

    assert_eq!(
        AdvancedAi::hosted_amenity_path(&game, 0, &crate::name!("entertainment_complex")),
        game.rules.buildings["arena"].amenity * HOSTED_AMENITY_DISCOUNT,
        "the Arena is the first-tier amenity building the district hosts"
    );
    assert_eq!(
        AdvancedAi::hosted_amenity_path(&game, 0, &crate::name!("campus")),
        0.0,
        "a Campus hosts no amenity building"
    );
    game.players[0]
        .civics
        .remove(&crate::name!("games_recreation"));
    assert_eq!(
        AdvancedAi::hosted_amenity_path(&game, 0, &crate::name!("entertainment_complex")),
        0.0,
        "and a building the player cannot yet build is not counted"
    );
    game.players[0]
        .civics
        .insert(crate::name!("games_recreation"));

    let ordinary = AdvancedAi::new();
    assert!(!ordinary.amenity_district_path);
    let frozen = AdvancedAi::legacy();
    assert!(!frozen.amenity_district_path);
    let stock = ordinary.production_value(&game, 0, capital, &complex, &plan, &counts);
    assert_eq!(
        frozen.production_value(&game, 0, capital, &complex, &plan, &counts),
        stock,
        "the frozen anchor prices the district exactly as the ordinary controller"
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    assert!(live.amenity_district_path);
    let priced = live.production_value(&game, 0, capital, &complex, &plan, &counts);
    let lift_displeased = priced - stock;
    assert!(
        lift_displeased > 0.0,
        "the live seat adds the hosted Arena at the district's amenity weight: \
             {priced} against {stock}"
    );
    // The lift is the hosted amenity at the district arm's own weight,
    // `55 + 35 × need`, behind the same build-time normaliser as the rest
    // of the value: a city short by two (still Displeased, so the same
    // production and the same normaliser) lifts by exactly 125/90 of one
    // short by one. A Content city produces more, so its normaliser
    // differs; there the lift is only bounded — present, and smaller.
    game.observed_city_amenity_adjustments
        .insert(capital, -2 - modeled);
    let stock_two = ordinary.production_value(&game, 0, capital, &complex, &plan, &counts);
    let priced_two = live.production_value(&game, 0, capital, &complex, &plan, &counts);
    assert!(
        ((priced_two - stock_two) / lift_displeased - 125.0 / 90.0).abs() < 1e-6,
        "short by two: lift {} against {lift_displeased}, expected ratio 125/90",
        priced_two - stock_two
    );
    game.observed_city_amenity_adjustments
        .insert(capital, -modeled);
    let stock_content = ordinary.production_value(&game, 0, capital, &complex, &plan, &counts);
    let priced_content = live.production_value(&game, 0, capital, &complex, &plan, &counts);
    let lift_content = priced_content - stock_content;
    assert!(
        lift_content > 0.0 && lift_content < lift_displeased,
        "a Content city still values the hosted Arena, less: {lift_content} against \
             {lift_displeased}"
    );
    game.observed_city_amenity_adjustments
        .insert(capital, -1 - modeled);

    live.disable_amenity_district_path();
    assert_eq!(
        live.production_value(&game, 0, capital, &complex, &plan, &counts),
        stock,
        "the control arm prices it like stock again"
    );
}

/// A Zoo reaches every own city within six tiles; priced as one city's
/// +1 it never outbid a Library. See `amenity_district_path`.
/// ★★★★ The tally pays three for a civic and two for a tech, and the
/// Science lane priced culture at a quarter of a beaker: eight Campuses
/// and zero Theater Squares in nine cities (civvis-20260816T093036Z), 36–41
/// civics against rivals' 43–53 in every batch-4 game. See
/// `tally_culture`. On the live seat a point of culture is worth no less
/// than a point of science under the Science lane, the Culture lane keeps
/// its own higher culture weight, and the strategic governor's Theater
/// Square carries the Campus's Science-lane weight; stock and frozen
/// controllers are unchanged.
#[test]
fn on_the_tally_seat_a_point_of_culture_is_worth_a_point_of_science() {
    let culture_only = Yields {
        culture: 1.0,
        ..Yields::default()
    };
    let science_only = Yields {
        science: 1.0,
        ..Yields::default()
    };
    let stock = AdvancedAi::new();
    let frozen = AdvancedAi::legacy();
    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(live.tally_culture, "the live seat carries the treatment");

    assert!(
        stock.yield_value(culture_only, GrandStrategy::Science)
            < stock.yield_value(science_only, GrandStrategy::Science),
        "the stock Science lane prices culture below science"
    );
    assert_eq!(
        frozen.yield_value(culture_only, GrandStrategy::Science),
        stock.yield_value(culture_only, GrandStrategy::Science),
        "the frozen anchor prices exactly as stock"
    );
    assert_eq!(
        live.yield_value(culture_only, GrandStrategy::Science),
        live.yield_value(science_only, GrandStrategy::Science),
        "the tally seat prices a point of culture at the Science lane's beaker"
    );
    for lane in [
        GrandStrategy::Expansion,
        GrandStrategy::Conquest,
        GrandStrategy::Recovery,
        GrandStrategy::Diplomacy,
        GrandStrategy::Religion,
    ] {
        assert!(
            live.yield_value(culture_only, lane) >= live.yield_value(science_only, lane),
            "under {lane:?} culture is worth no less than science on the tally seat"
        );
        assert!(
            live.yield_value(science_only, lane) == stock.yield_value(science_only, lane),
            "and the beaker itself is priced as before under {lane:?}"
        );
    }
    assert_eq!(
        live.yield_value(culture_only, GrandStrategy::Culture),
        stock.yield_value(culture_only, GrandStrategy::Culture),
        "the Culture lane keeps its own, higher, culture weight"
    );

    // The strategic governor: a Theater Square is priced like a Campus
    // under the Science lane on the tally seat, and below it as stock.
    let (mut game, capital, _home) = empire_with_a_capital(71_113);
    game.players[0].techs.insert(crate::name!("writing"));
    game.players[0].civics.insert(crate::name!("drama_poetry"));
    let campus_site = game
        .district_sites(capital, crate::name!("campus"))
        .into_iter()
        .next()
        .expect("the capital has a plot for a Campus");
    // The same plot serves both, so the comparison is the district alone.
    let theater_site = game
        .district_sites(capital, crate::name!("theater_square"))
        .into_iter()
        .find(|site| *site == campus_site)
        .or_else(|| {
            game.district_sites(capital, crate::name!("theater_square"))
                .into_iter()
                .next()
        })
        .expect("the capital has a plot for a Theater Square");
    let campus = Item::District {
        district: crate::name!("campus"),
        pos: campus_site,
    };
    let theater = Item::District {
        district: crate::name!("theater_square"),
        pos: theater_site,
    };
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let counts = EmpireCounts::default();
    let stock_gap = stock.production_value(&game, 0, capital, &campus, &plan, &counts)
        - stock.production_value(&game, 0, capital, &theater, &plan, &counts);
    let live_gap = live.production_value(&game, 0, capital, &campus, &plan, &counts)
        - live.production_value(&game, 0, capital, &theater, &plan, &counts);
    assert!(
        live_gap < stock_gap,
        "the tally seat closes the Campus-over-Theater gap ({live_gap} vs {stock_gap})"
    );

    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge();
    withheld.disable_tally_culture();
    assert_eq!(
        withheld.yield_value(culture_only, GrandStrategy::Science),
        stock.yield_value(culture_only, GrandStrategy::Science)
    );
    assert!(!stock.tally_culture);
    assert!(!frozen.tally_culture);
}

/// ★★★★ `research_debt` pays a Campus building 240 for the Campus standing
/// over it, and `BUILDINGS_BEFORE_PROJECTS` makes a Great Person race wait
/// behind a Library — and neither knows the Theater Square exists. Over 25
/// live games and 204 cities: Library 72% against Amphitheater 21%,
/// University 53% against Museum 7%, Research Lab 23% against Broadcast
/// Center 1%; a 250-turn A/B replay of civvis-20260816T233226Z ordered an
/// Amphitheater zero times in either arm. See `culture_building_debt`.
#[test]
fn a_theater_square_owes_its_buildings_the_way_a_campus_does() {
    let (mut game, capital, _home) = empire_with_a_capital(71_113);
    game.players[0].civics.insert(crate::name!("drama_poetry"));
    game.players[0].techs.insert(crate::name!("writing"));
    game.players[0].techs.insert(crate::name!("currency"));
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let counts = EmpireCounts::default();
    let amphitheater = Item::Building {
        building: crate::name!("amphitheater"),
    };

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(
        live.culture_building_debt,
        "the live seat carries the treatment"
    );
    live.refresh_research_weight(&game);
    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge();
    withheld.disable_culture_building_debt();
    withheld.refresh_research_weight(&game);

    // No Theater Square: nothing is owed, and the two arms agree.
    assert_eq!(
        live.production_value(&game, 0, capital, &amphitheater, &plan, &counts),
        withheld.production_value(&game, 0, capital, &amphitheater, &plan, &counts),
        "a city with no Theater Square owes it no buildings"
    );

    // With the district standing the cheap half is owed, exactly as a
    // Library is owed to a Campus.
    install_ai_test_district(&mut game, capital, "theater_square");
    let owed = live.production_value(&game, 0, capital, &amphitheater, &plan, &counts);
    let unowed = withheld.production_value(&game, 0, capital, &amphitheater, &plan, &counts);
    assert!(
        owed > unowed,
        "the Theater Square owes its Amphitheater: {owed} vs {unowed}"
    );

    // And a repeatable Great Person race waits behind it, the way #1811
    // makes it wait behind a Library. The city holds a Commercial Hub WITH
    // its Market, so the project's own family owes nothing and only the
    // culture chain is under test.
    install_ai_test_district(&mut game, capital, "commercial_hub");
    game.cities
        .get_mut(&capital)
        .unwrap()
        .buildings
        .push(crate::name!("market"));
    game.turn = 60;
    game.players[0].gpp.insert("merchant".to_string(), 30.0);
    assert!(
        game.can_produce(0, capital, &amphitheater),
        "the Amphitheater is owed and buildable"
    );
    for science in ["library", "university", "research_lab", "workshop"] {
        let owed_science = Item::Building {
            building: Name::new(science),
        };
        if game.can_produce(0, capital, &owed_science) {
            game.cities
                .get_mut(&capital)
                .unwrap()
                .buildings
                .push(Name::new(science));
        }
    }
    let capped = live.district_project_value(&game, 0, capital, "commercial_hub_investment", &plan);
    let free =
        withheld.district_project_value(&game, 0, capital, "commercial_hub_investment", &plan);
    assert!(
        capped <= PROJECT_BEHIND_BUILDINGS_CAP,
        "capped while the Amphitheater is owed: {capped}"
    );
    assert!(
        free > capped,
        "the withheld arm prices the race in full: {free} vs {capped}"
    );

    // #1811 is left exactly as it was measured: its own list still names
    // only the science chain.
    assert_eq!(
        BUILDINGS_BEFORE_PROJECTS,
        ["library", "university", "research_lab", "workshop"]
    );
    // The constants are known at compile time, so clippy folds the
    // comparison to a literal; the ordering is still the thing under
    // test, so assert on values it cannot fold.
    assert!(
        std::hint::black_box(CULTURE_BUILDING_DEBT) < std::hint::black_box(RESEARCH_BUILDING_DEBT)
    );
    assert!(!AdvancedAi::new().culture_building_debt);
    assert!(!AdvancedAi::legacy().culture_building_debt);
}

/// ★★★★★ Eight Campuses and six Theater Squares stood empty to turn 205 of
/// run civvis-20260819T000800Z: 174 produce orders, not one Library,
/// University or Amphitheater. The Library was legal on 133 replayed
/// city-turns at a median value of 23 while the queue winner stood 55
/// higher; the Amphitheater never reached a price at all, because under an
/// explicit non-Culture target the great-work veto returns before
/// `culture_building_debt` is computed. See `district_building_chain`: a
/// specialty district the city already stands owes its own buildings, the
/// debt decays with each building of the family the city holds, the veto
/// yields to a Theater Square the city has, and nothing changes for a city
/// without the district, for a unit, for a wonder, or for the frozen and
/// stock controllers.
#[test]
fn a_standing_district_owes_its_own_buildings_whatever_the_lane() {
    let (mut game, capital, _home) = empire_with_a_capital(71_115);
    game.players[0].civics.insert(crate::name!("drama_poetry"));
    game.players[0].techs.insert(crate::name!("writing"));
    game.players[0].techs.insert(crate::name!("currency"));
    game.players[0].techs.insert(crate::name!("education"));
    game.turn = 60;
    let plan = StrategicPlan {
        strategy: GrandStrategy::Diplomacy,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let counts = EmpireCounts::default();
    let library = Item::Building {
        building: crate::name!("library"),
    };
    let university = Item::Building {
        building: crate::name!("university"),
    };
    let amphitheater = Item::Building {
        building: crate::name!("amphitheater"),
    };
    let monument = Item::Building {
        building: crate::name!("monument"),
    };

    // The seat that plays the ladder: an explicit Diplomacy target with the
    // live bundle, and the same seat with only this treatment withheld.
    let mut live = AdvancedAi::targeting(VictoryTarget::Diplomacy);
    live.enable_live_bridge();
    assert!(
        live.district_building_chain,
        "the live seat carries the treatment"
    );
    live.refresh_research_weight(&game);
    let mut withheld = AdvancedAi::targeting(VictoryTarget::Diplomacy);
    withheld.enable_live_bridge();
    withheld.disable_district_building_chain();
    withheld.refresh_research_weight(&game);

    // No Campus, no Theater Square: nothing is owed and the two arms agree
    // — including the veto, which still refuses the Amphitheater to a city
    // with no Theater Square under a non-Culture target.
    assert_eq!(
        live.production_value(&game, 0, capital, &library, &plan, &counts),
        withheld.production_value(&game, 0, capital, &library, &plan, &counts),
        "a city with no Campus owes it no Library"
    );
    install_ai_test_district(&mut game, capital, "campus");
    install_ai_test_district(&mut game, capital, "theater_square");
    assert!(game.can_produce(0, capital, &library));
    assert!(game.can_produce(0, capital, &amphitheater));

    // The Campus owes its Library; the debt is the constant over the
    // payback horizon (full this early), on top of the unchanged price.
    let owed = live.production_value(&game, 0, capital, &library, &plan, &counts);
    let unowed = withheld.production_value(&game, 0, capital, &library, &plan, &counts);
    let cost = game.item_remaining_cost_for_city(0, capital, &library);
    let production = game.city_yields(capital).production.max(1.0);
    let denominator = 7.0 + (cost / production).max(1.0);
    let expected = DISTRICT_BUILDING_CHAIN_DEBT
        * AdvancedAi::campus_payback_horizon(&game)
        * live.production_category_gene(&library)
        / denominator;
    assert!(
        (owed - unowed - expected).abs() < 1e-6,
        "the standing Campus owes its Library the chain debt: {owed} - {unowed} != {expected}"
    );

    // The Theater Square's building reaches a price on this seat: the veto
    // that returned -10_000 before any debt was computed yields to a
    // district the city already stands. Withheld, the veto stands.
    let amph_live = live.production_value(&game, 0, capital, &amphitheater, &plan, &counts);
    let amph_withheld = withheld.production_value(&game, 0, capital, &amphitheater, &plan, &counts);
    assert!(
        amph_live > 0.0,
        "the standing Theater Square's Amphitheater is priced, not vetoed: {amph_live}"
    );
    assert_eq!(
        amph_withheld, -10_000.0,
        "withheld, the great-work veto is unchanged"
    );

    // A building outside every specialty district collects nothing.
    assert_eq!(
        live.production_value(&game, 0, capital, &monument, &plan, &counts),
        withheld.production_value(&game, 0, capital, &monument, &plan, &counts),
        "a Monument is owed by no district"
    );

    // With the Library built, the University is owed less: one tier decayed.
    game.cities
        .get_mut(&capital)
        .unwrap()
        .buildings
        .push(crate::name!("library"));
    assert!(game.can_produce(0, capital, &university));
    let owed_university = live.production_value(&game, 0, capital, &university, &plan, &counts);
    let unowed_university =
        withheld.production_value(&game, 0, capital, &university, &plan, &counts);
    let cost = game.item_remaining_cost_for_city(0, capital, &university);
    let denominator = 7.0 + (cost / production).max(1.0);
    let expected_tier_two = DISTRICT_BUILDING_CHAIN_DEBT
        * DISTRICT_BUILDING_CHAIN_TIER_DECAY
        * AdvancedAi::campus_payback_horizon(&game)
        * live.production_category_gene(&university)
        / denominator;
    assert!(
        (owed_university - unowed_university - expected_tier_two).abs() < 1e-6,
        "the second building of the chain is owed one tier less: \
         {owed_university} - {unowed_university} != {expected_tier_two}"
    );

    // Frozen and stock controllers never carry it, and the debt is a
    // building-arm term: the Campus district's own price is untouched.
    assert!(!AdvancedAi::new().district_building_chain);
    assert!(!AdvancedAi::legacy().district_building_chain);
    assert!(std::hint::black_box(DISTRICT_BUILDING_CHAIN_TIER_DECAY) < 1.0);
}

/// The old non-Culture veto used a Great Work slot as a proxy for the Culture
/// district. That refuses National History Museum in the Government Plaza and
/// lets slotless Marae through, neither of which is the actual policy boundary.
/// `advanced_great_work_veto_by_district` is the isolated, Science-targeted
/// evaluator treatment; production remains slot-keyed until it is priced.
#[test]
fn a_district_keyed_great_work_veto_exempts_the_government_plaza() {
    let (game, capital, _home) = empire_with_a_capital(71_114);
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let counts = EmpireCounts::default();
    let amphitheater = Item::Building {
        building: crate::name!("amphitheater"),
    };
    let marae = Item::Building {
        building: crate::name!("marae"),
    };
    let national_history_museum = Item::Building {
        building: crate::name!("national_history_museum"),
    };

    let mut slot_keyed = AdvancedAi::targeting(VictoryTarget::Science);
    let mut district_keyed = AdvancedAi::targeting(VictoryTarget::Science);
    district_keyed.enable_great_work_veto_by_district();
    slot_keyed.refresh_research_weight(&game);
    district_keyed.refresh_research_weight(&game);

    assert_eq!(
        slot_keyed.victory_target(),
        Some(VictoryTarget::Science),
        "the control is the deployment launcher’s Science-targeted seat"
    );
    assert!(
        game.rules.buildings[&crate::name!("marae")]
            .great_work_slots
            .is_empty(),
        "Marae is the Theater Square boundary case without a Great Work slot"
    );
    assert!(
        !game.rules.buildings[&crate::name!("national_history_museum")]
            .great_work_slots
            .is_empty(),
        "National History Museum is the Government Plaza boundary case with slots"
    );

    let value =
        |ai: &AdvancedAi, item: &Item| ai.production_value(&game, 0, capital, item, &plan, &counts);

    assert_eq!(value(&slot_keyed, &amphitheater), -10_000.0);
    assert_eq!(value(&district_keyed, &amphitheater), -10_000.0);
    assert!(
        value(&slot_keyed, &marae) > -10_000.0,
        "the historical slot key lets a slotless Theater Square building through"
    );
    assert_eq!(value(&district_keyed, &marae), -10_000.0);
    assert_eq!(value(&slot_keyed, &national_history_museum), -10_000.0);
    assert!(
        value(&district_keyed, &national_history_museum) > -10_000.0,
        "the district key lets an unrelated Government Plaza building be valued"
    );
    assert!(!AdvancedAi::new().great_work_veto_by_district);
    assert!(!AdvancedAi::legacy().great_work_veto_by_district);
}

/// The debt was previously checked only on an untargeted controller, even
/// though the hard veto means it can act in targeted deployment only in the
/// Culture lane. Keep the target equal, enabling just the debt, so the second
/// pre-registered comparison has a reachable mechanism.
#[test]
fn a_culture_target_reaches_the_theater_building_debt() {
    let (mut game, capital, _home) = empire_with_a_capital(71_115);
    game.players[0].civics.insert(crate::name!("drama_poetry"));
    install_ai_test_district(&mut game, capital, "theater_square");
    let plan = StrategicPlan {
        strategy: GrandStrategy::Culture,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let amphitheater = Item::Building {
        building: crate::name!("amphitheater"),
    };
    let counts = EmpireCounts::default();
    let mut treated = AdvancedAi::targeting(VictoryTarget::Culture);
    treated.enable_culture_building_debt();
    let mut withheld = AdvancedAi::targeting(VictoryTarget::Culture);
    treated.refresh_research_weight(&game);
    withheld.refresh_research_weight(&game);

    assert_eq!(treated.victory_target(), Some(VictoryTarget::Culture));
    assert!(treated.culture_building_debt);
    assert!(!withheld.culture_building_debt);
    let owed = treated.production_value(&game, 0, capital, &amphitheater, &plan, &counts);
    let unowed = withheld.production_value(&game, 0, capital, &amphitheater, &plan, &counts);
    assert!(
        owed > unowed,
        "a Culture-targeted seat reaches the debt instead of the non-Culture veto: {owed} vs {unowed}"
    );
}

/// ★★★★ `tally_culture` fixed the PRICE of culture and left the COVERAGE
/// alone, and over 204 cities in 25 live games the coverage is the gap:
/// Campus 82% of cities, Theater Square 27%; Library 72%, Amphitheater 21%;
/// University 53%, Museum 7%; Research Lab 23%, Broadcast Center 1%. Two
/// terms belong to the Campus alone — `research_coverage` and the
/// `campus_every_city` exemption from `balanced_core`'s half-the-empire
/// cliff. See `culture_coverage`: the tally seat gives the Theater Square
/// both, once a specialty district already stands in the city, and stock
/// and frozen controllers are unchanged.
#[test]
fn a_city_without_a_theater_square_is_a_culture_hole_on_the_tally_seat() {
    let (mut game, capital, _home) = empire_with_a_capital(71_113);
    game.players[0].techs.insert(crate::name!("writing"));
    game.players[0].civics.insert(crate::name!("drama_poetry"));
    let theater_site = game
        .district_sites(capital, crate::name!("theater_square"))
        .into_iter()
        .next()
        .expect("the capital has a plot for a Theater Square");
    let theater = Item::District {
        district: crate::name!("theater_square"),
        pos: theater_site,
    };
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let counts = EmpireCounts::default();

    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    assert!(live.culture_coverage, "the live seat carries the treatment");
    live.refresh_research_weight(&game);
    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge_universe();
    withheld.disable_culture_coverage();
    withheld.refresh_research_weight(&game);

    // A city with no specialty district yet keeps the Campus first: the
    // hole is not paid until the city has somewhere to put the rest.
    assert_eq!(
        game.city_specialty_district_count(&game.cities[&capital]),
        0,
        "the fresh capital carries no specialty district"
    );
    assert_eq!(
        live.production_value(&game, 0, capital, &theater, &plan, &counts),
        withheld.production_value(&game, 0, capital, &theater, &plan, &counts),
        "a one-district town is not handed a Theater Square instead of its Campus"
    );

    // With a Campus standing the hole is real and the treated seat pays it.
    install_ai_test_district(&mut game, capital, "campus");
    let hole = live.production_value(&game, 0, capital, &theater, &plan, &counts)
        - withheld.production_value(&game, 0, capital, &theater, &plan, &counts);
    assert!(
        hole > 0.0,
        "the culture hole is priced on the tally seat: {hole}"
    );

    // Once the Theater Square stands the coverage payment stops — it buys
    // the first one, not a second. What is left of the gap is the other
    // half of the treatment: this one-city empire is now past
    // `balanced_core`'s half-the-empire cliff, and only the treated seat
    // keeps asking. The Campus has had exactly that exemption since
    // `campus_every_city`, and it is why Campus coverage reached 82% of
    // cities while the Theater Square stopped at 27%.
    install_ai_test_district(&mut game, capital, "theater_square");
    let cliff = live.production_value(&game, 0, capital, &theater, &plan, &counts)
        - withheld.production_value(&game, 0, capital, &theater, &plan, &counts);
    assert!(
        cliff > 0.0 && cliff < hole,
        "coverage stops at the first Theater Square and the cliff exemption \
             remains: {cliff} left of {hole}"
    );
    assert!(!AdvancedAi::new().culture_coverage);
    assert!(!AdvancedAi::legacy().culture_coverage);
    // Both are consts, so clippy folds the comparison to a literal; the
    // ordering is the thing under test, so assert on values it cannot fold.
    assert!(
        std::hint::black_box(CULTURE_THEATER_COVERAGE)
            < std::hint::black_box(RESEARCH_CAMPUS_COVERAGE),
        "the culture hole is held one rung under the research hole"
    );
}

#[test]
fn a_regional_amenity_building_counts_the_cities_it_reaches() {
    // `found_nearby_test_city` sites a city 4–10 tiles out; keep seeding
    // until at least one lands inside the Zoo's six-tile reach.
    let range = 6;
    let (mut game, capital, cities) = (71_114..71_140)
        .find_map(|seed| {
            let (mut game, capital, home) = empire_with_a_capital(seed);
            let mut cities = vec![capital];
            for _ in 0..3 {
                cities.push(found_nearby_test_city(&mut game, 0, home));
            }
            cities[1..]
                .iter()
                .any(|city| game.wdist(game.cities[&capital].pos, game.cities[city].pos) <= range)
                .then_some((game, capital, cities))
        })
        .expect("some seed sites a city within the Zoo's reach");
    for civic in ["games_recreation", "natural_history"] {
        game.players[0].civics.insert(Name::new(civic));
    }
    install_ai_test_district(&mut game, capital, "entertainment_complex");
    game.cities
        .get_mut(&capital)
        .unwrap()
        .buildings
        .push(crate::name!("arena"));
    for city in &cities {
        let modeled = game.city_amenity_surplus(&game.cities[city]);
        game.observed_city_amenity_adjustments
            .insert(*city, -1 - modeled);
    }
    let zoo = Item::Building {
        building: crate::name!("zoo"),
    };
    assert!(
        game.can_produce(0, capital, &zoo),
        "the fixture must offer the Zoo"
    );
    let spec = game.rules.buildings["zoo"].clone();
    assert_eq!(
        spec.regional_range, range,
        "the Zoo is a six-tile regional building"
    );
    let reached = cities[1..]
        .iter()
        .filter(|city| game.wdist(game.cities[&capital].pos, game.cities[city].pos) <= range)
        .count();
    assert!(
        reached >= 1,
        "the fixture sites a city inside the Zoo's range"
    );

    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let counts = EmpireCounts::default();
    let ordinary = AdvancedAi::new();
    let stock = ordinary.production_value(&game, 0, capital, &zoo, &plan, &counts);
    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    let priced = live.production_value(&game, 0, capital, &zoo, &plan, &counts);
    assert!(
        priced > stock,
        "each Displeased city in range adds its own weight: {priced} against {stock} \
             for {reached} cities"
    );
    assert_eq!(
        AdvancedAi::regional_amenity_reach(
            &game,
            0,
            &game.cities[&capital],
            &crate::name!("zoo"),
            &spec
        ),
        reached as f64 * (30.0 + 1.0 * 22.0) * REGIONAL_AMENITY_REACH_DISCOUNT,
        "the reach is one local weight per Displeased city in range, discounted"
    );
    let unreached = AdvancedAi::new();
    assert!(!unreached.amenity_district_path);
    assert_eq!(
        unreached.production_value(&game, 0, capital, &zoo, &plan, &counts),
        stock
    );

    // A second Zoo whose reach is already covered adds nothing regional.
    let other = cities[1..]
        .iter()
        .copied()
        .find(|city| game.wdist(game.cities[&capital].pos, game.cities[city].pos) <= range)
        .expect("the second Zoo is placed in the first Zoo's range");
    // The first half prices every reached city. Keep only the pair that
    // establishes the non-stacking case below, so another city incidentally
    // in `other`'s range cannot look like a second Zoo benefit.
    for city in cities
        .iter()
        .copied()
        .filter(|city| *city != capital && *city != other)
    {
        game.mirror_remove_city(city);
    }
    install_ai_test_district(&mut game, other, "entertainment_complex");
    game.cities
        .get_mut(&other)
        .unwrap()
        .buildings
        .push(crate::name!("arena"));
    game.cities
        .get_mut(&capital)
        .unwrap()
        .buildings
        .push(crate::name!("zoo"));
    assert_eq!(
        AdvancedAi::regional_amenity_reach(
            &game,
            0,
            &game.cities[&other],
            &crate::name!("zoo"),
            &spec
        ),
        0.0,
        "cities the standing Zoo already reaches earn a second one nothing"
    );
}

#[test]
fn widespread_live_amenity_pressure_reserves_one_idle_arena_during_conquest() {
    // At t250 of `civvis-20260815T164852Z`, all eight Roman cities were
    // short by eleven Amenities total. Four core cities already had an
    // Entertainment Complex but no Arena, and an empty Rome started a
    // Builder under the active Conquest plan. Reproduce the important
    // constraints: host-calibrated deficits, an active war, and an
    // existing Builder that must not be displaced.
    let (mut game, capital, home) = empire_with_a_capital(71_112);
    let mut cities = vec![capital];
    for _ in 0..3 {
        cities.push(found_nearby_test_city(&mut game, 0, home));
    }
    game.players[0]
        .civics
        .insert(crate::name!("games_recreation"));
    for city in &cities {
        install_ai_test_district(&mut game, *city, "entertainment_complex");
        let modeled = game.city_amenity_surplus(&game.cities[city]);
        game.observed_city_amenity_adjustments
            .insert(*city, -1 - modeled);
        let arena = Item::Building {
            building: crate::name!("arena"),
        };
        assert!(game.can_produce(0, *city, &arena));
    }
    let builder = Item::Unit {
        unit: crate::name!("builder"),
    };
    game.apply(
        0,
        &Action::Produce {
            city: capital,
            item: builder.clone(),
        },
    )
    .expect("queue the active Builder that the Amenity repair must preserve");
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 5,
        assessed_turn: game.turn,
        rush: false,
    };

    let ordinary = AdvancedAi::new();
    ordinary.reserve_idle_entertainment_path_for_widespread_crisis(&mut game, 0, &plan);
    assert_eq!(game.cities[&capital].queue.first(), Some(&builder));
    assert!(
        cities[1..]
            .iter()
            .all(|city| game.cities[city].queue.is_empty()),
        "the frozen/live-disabled controller must not create an Amenity reservation"
    );

    // A deep local deficit stays with ordinary production and policies;
    // this direct handoff is reserved for the broad pressure recorded in
    // the live run, not a way to override a war queue for one city.
    let mut local = game.clone();
    for city in &cities {
        local.observed_city_amenity_adjustments.remove(city);
    }
    let local_city = cities[1];
    let modeled = local.city_amenity_surplus(&local.cities[&local_city]);
    local
        .observed_city_amenity_adjustments
        .insert(local_city, -4 - modeled);
    let mut local_live = AdvancedAi::new();
    local_live.enable_live_bridge_universe();
    local_live.reserve_idle_entertainment_path_for_widespread_crisis(&mut local, 0, &plan);
    assert_eq!(local.cities[&capital].queue.first(), Some(&builder));
    assert!(
        cities[1..]
            .iter()
            .all(|city| local.cities[city].queue.is_empty()),
        "one deeply unhappy city must not trigger the widespread queue reservation"
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    live.reserve_idle_entertainment_path_for_widespread_crisis(&mut game, 0, &plan);
    assert_eq!(game.cities[&capital].queue.first(), Some(&builder));
    let reserved = cities[1..]
        .iter()
        .filter(|city| {
            matches!(
                game.cities[city].queue.first(),
                Some(Item::Building { building }) if *building == crate::name!("arena")
            )
        })
        .count();
    assert_eq!(reserved, 1, "one idle city starts the direct repair chain");
    assert_eq!(
        cities[1..]
            .iter()
            .filter(|city| !game.cities[city].queue.is_empty())
            .count(),
        1,
        "the widespread crisis reserves one queue, not every eligible city"
    );

    // The in-flight Arena owns the reservation until it completes.
    live.reserve_idle_entertainment_path_for_widespread_crisis(&mut game, 0, &plan);
    assert_eq!(
        cities[1..]
            .iter()
            .filter(|city| !game.cities[city].queue.is_empty())
            .count(),
        1
    );
}

#[test]
fn widespread_live_amenity_pressure_starts_one_idle_entertainment_complex() {
    // The live Rome at t171 had eight cities at -1/-2, no Entertainment
    // Complex, and every strategic queue preferred a Bath, project, or
    // ordinary development. The direct-building reservation could not
    // fire because there was no district to host an Arena. Reproduce that
    // broad-but-not-severe shape while preserving a non-idle queue.
    let (mut game, capital, home) = empire_with_a_capital(71_115);
    let mut cities = vec![capital];
    for _ in 0..3 {
        cities.push(found_nearby_test_city(&mut game, 0, home));
    }
    game.players[0]
        .civics
        .insert(crate::name!("games_recreation"));
    for city in &cities {
        game.cities.get_mut(city).unwrap().pop = 7;
        install_ai_test_district(&mut game, *city, "campus");
        let modeled = game.city_amenity_surplus(&game.cities[city]);
        game.observed_city_amenity_adjustments
            .insert(*city, -1 - modeled);
    }
    assert!(cities.iter().all(|city| {
        !game.cities[city]
            .districts
            .keys()
            .any(|district| game.district_family(*district) == "entertainment_complex")
    }));
    assert!(cities[1..].iter().any(|city| {
        game.producible_items(0, *city).iter().any(|item| {
            matches!(item, Item::District { district, .. }
                    if game.district_family(*district) == "entertainment_complex")
        })
    }));
    let builder = Item::Unit {
        unit: crate::name!("builder"),
    };
    game.apply(
        0,
        &Action::Produce {
            city: capital,
            item: builder.clone(),
        },
    )
    .expect("queue the active Builder that the Amenity path must preserve");
    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 5,
        assessed_turn: game.turn,
        rush: false,
    };

    let ordinary = AdvancedAi::new();
    ordinary.reserve_idle_entertainment_path_for_widespread_crisis(&mut game, 0, &plan);
    assert_eq!(game.cities[&capital].queue.first(), Some(&builder));
    assert!(
        cities[1..]
            .iter()
            .all(|city| game.cities[city].queue.is_empty()),
        "the frozen/live-disabled controller must not reserve a district"
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    live.reserve_idle_entertainment_path_for_widespread_crisis(&mut game, 0, &plan);
    assert_eq!(game.cities[&capital].queue.first(), Some(&builder));
    let reserved = cities[1..]
        .iter()
        .filter(|city| {
            matches!(
                game.cities[city].queue.first(),
                Some(Item::District { district, .. })
                    if game.district_family(*district) == "entertainment_complex"
            )
        })
        .count();
    assert_eq!(reserved, 1, "one idle city opens the Entertainment path");
    assert_eq!(
        cities[1..]
            .iter()
            .filter(|city| !game.cities[city].queue.is_empty())
            .count(),
        1,
        "the broad deficit reserves one queue, not every eligible city"
    );

    // The in-flight district owns the reservation until it completes.
    live.reserve_idle_entertainment_path_for_widespread_crisis(&mut game, 0, &plan);
    assert_eq!(
        cities[1..]
            .iter()
            .filter(|city| !game.cities[city].queue.is_empty())
            .count(),
        1
    );
}

#[test]
fn broad_wartime_amenity_pressure_reclaims_one_repeatable_project_before_slots_close() {
    // In `civvis-20260815T230003Z` at t88, three of four cities were at
    // -1 while Arretium's one-turn Theater project occupied a legal second
    // specialty slot. The generic Conquest governor filled the other slots
    // with Commercial Hubs, after which no direct Amenity district could
    // be started. The broad arm can reserve an idle slot or interrupt that
    // one repeatable project, but never a unit or an active district.
    let (mut game, capital, home) = empire_with_a_capital(71_113);
    let mut cities = vec![capital];
    for _ in 0..3 {
        cities.push(found_nearby_test_city(&mut game, 0, home));
    }
    game.players[0]
        .civics
        .insert(crate::name!("games_recreation"));
    game.players[0].techs.insert(crate::name!("writing"));
    for city in &cities {
        game.cities.get_mut(city).unwrap().pop = 7;
        install_ai_test_district(&mut game, *city, "campus");
    }
    let grant = Item::Project {
        project: crate::name!("campus_research_grants"),
    };
    assert!(game.can_produce(0, capital, &grant));
    game.apply(
        0,
        &Action::Produce {
            city: capital,
            item: grant.clone(),
        },
    )
    .expect("queue the repeatable project that may yield one safe slot");
    let builder = Item::Unit {
        unit: crate::name!("builder"),
    };
    assert!(game.can_produce(0, cities[1], &builder));
    game.apply(
        0,
        &Action::Produce {
            city: cities[1],
            item: builder.clone(),
        },
    )
    .expect("a wartime unit/build queue remains out of bounds");
    for (city, target) in cities.iter().zip([-1, -1, -1, 0]) {
        let modeled = game.city_amenity_surplus(&game.cities[city]);
        game.observed_city_amenity_adjustments
            .insert(*city, target - modeled);
    }
    let fixture_shortfalls: Vec<i64> = cities
        .iter()
        .map(|city| (-game.city_amenity_surplus(&game.cities[city])).max(0))
        .collect();
    assert_eq!(fixture_shortfalls, vec![1, 1, 1, 0]);
    assert!(game.players[1].alive && game.is_at_war(0, 1));
    let legal = game.producible_items(0, capital);
    assert!(
        legal.iter().any(|item| matches!(
            item,
            Item::District { district, .. }
                if game.district_family(*district) == "entertainment_complex"
        )),
        "the fixture needs a usable Entertainment Complex slot: {legal:?}"
    );
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 5,
        assessed_turn: game.turn,
        rush: false,
    };

    // A two-city shortfall is still ordinary wartime production, not an
    // excuse to interrupt the project.
    let mut below_threshold = game.clone();
    *below_threshold
        .observed_city_amenity_adjustments
        .get_mut(&cities[2])
        .expect("the third city has the calibrated -1 adjustment") += 1;
    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    live.redirect_repeatable_projects_for_amenity_crisis(&mut below_threshold, 0, &plan, true);
    assert_eq!(
        below_threshold.cities[&capital].queue.first(),
        Some(&grant),
        "a merely local wartime shortage preserves the project"
    );

    let ordinary = AdvancedAi::new();
    ordinary.redirect_repeatable_projects_for_amenity_crisis(&mut game, 0, &plan, true);
    assert_eq!(
        game.cities[&capital].queue.first(),
        Some(&grant),
        "the frozen/live-disabled controller keeps the historic queue"
    );

    live.redirect_repeatable_projects_for_amenity_crisis(&mut game, 0, &plan, true);
    let queues: Vec<_> = cities
        .iter()
        .map(|city| (*city, game.cities[city].queue.first()))
        .collect();
    assert!(matches!(
            game.cities[&capital].queue.first(),
            Some(Item::District { district, .. })
                if game.district_family(*district) == "entertainment_complex"
        ), "the broad handoff turns exactly one repeatable project into the missing Entertainment Complex: {queues:?}");
    assert_eq!(
        game.cities[&cities[1]].queue.first(),
        Some(&builder),
        "the wartime exception must never replace an active unit queue"
    );
    assert!(
        cities[2..]
            .iter()
            .all(|city| game.cities[city].queue.is_empty()),
        "one repair owns the intervention instead of turning every city into an amenity build"
    );
}

#[test]
fn widespread_observed_amenity_deficits_slot_liberalism_over_aesthetics() {
    // At turn 175 of `civvis-20260815T120417Z`, Rome, Mediolanum, and
    // Arretium each had multiple specialty districts, a host-confirmed
    // Amenity deficit, and a yield penalty, while Aesthetics occupied an
    // economic/wildcard lane. Liberalism pays immediately in all three;
    // the existing project repair cannot help until its build completes.
    let build = |live: bool, deficits: bool| {
        let mut game = Game::new(2, 32, 24, 71_111, 250, 0);
        let settler = game
            .player_unit_ids(0)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .expect("starting settler");
        game.apply(0, &Action::FoundCity { unit: settler })
            .expect("found city");
        let capital = game.player_city_ids(0)[0];
        let other = found_test_city(&mut game, 0);
        game.players[0].government = Some("theocracy".to_string());
        game.players[0].civics.extend([
            crate::name!("the_enlightenment"),
            crate::name!("medieval_faires"),
            crate::name!("opera_ballet"),
            crate::name!("scorched_earth"),
        ]);
        for city in [capital, other] {
            install_ai_test_district(&mut game, city, "campus");
            install_ai_test_district(&mut game, city, "theater_square");
            if deficits {
                // This is the additive correction the live mirror writes:
                // hold each city at -4 regardless of its modeled luxuries.
                let modeled = game.city_amenity_surplus(&game.cities[&city]);
                game.observed_city_amenity_adjustments
                    .insert(city, -4 - modeled);
            }
        }
        for _ in 0..4 {
            game.spawn_test_unit("warrior", 0, game.cities[&capital].pos);
        }
        for policy in ["aesthetics", "grand_opera", "expropriation"] {
            game.apply(
                0,
                &Action::SlotPolicy {
                    policy: Name::new(policy),
                },
            )
            .unwrap_or_else(|error| panic!("slot {policy}: {error}"));
        }

        let mut ai = AdvancedAi::new();
        // Keep Expropriation in the live Conquest portfolio; the policy
        // relief must make room without sacrificing active expansion.
        ai.enable_wide_map_capacity();
        if live {
            ai.enable_amenity_project_preemption();
        }
        ai.refresh_research_weight(&game);
        ai.strategic_policies(&mut game, 0, GrandStrategy::Conquest);
        game.players[0].policies.clone()
    };

    let ordinary = build(false, true);
    let healthy = build(true, false);
    let relieved = build(true, true);
    for control in [&ordinary, &healthy] {
        assert!(
            control.contains(&crate::name!("aesthetics")),
            "the live gate and a real deficit are both required: {control:?}"
        );
        assert!(
            !control.contains(&crate::name!("liberalism")),
            "normal or healthy decks keep their existing culture card: {control:?}"
        );
    }
    assert!(
        relieved.contains(&crate::name!("liberalism")),
        "two developed deficit cities should get the immediate Amenity repair: {relieved:?}"
    );
    assert!(
        !relieved.contains(&crate::name!("aesthetics")),
        "Liberalism needs a same-slot donor rather than another inert wish: {relieved:?}"
    );
    assert!(
        relieved.contains(&crate::name!("grand_opera"))
            && relieved.contains(&crate::name!("expropriation")),
        "Amenity relief must preserve theater-building culture and active expansion: {relieved:?}"
    );
}

