#[test]
fn support_search_builds_air_defense_only_for_a_real_hostile_air_threat() {
    let mut game = Game::new_full(2, 24, 16, 71_011, 160, 0, false);
    for pid in 0..2 {
        game.current = pid;
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    game.players[0]
        .techs
        .insert(crate::name!("advanced_ballistics"));
    game.at_war.insert((0, 1));
    let city = game.player_city_ids(0)[0];
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: game.player_city_ids(1).first().copied(),
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);
    ai.base.book_pos = 4;
    let item = Item::Unit {
        unit: crate::name!("anti_air_gun"),
    };
    let counts = ai.counts(&game, 0);
    assert_eq!(counts.air_defense, 0);
    assert!(ai.production_value(&game, 0, city, &item, &plan, &counts) < -9_000.0);

    let hostile_base = game.cities[&game.player_city_ids(1)[0]].pos;
    game.spawn_test_unit("bomber", 1, hostile_base);
    let counts = ai.counts(&game, 0);
    assert!(ai.production_value(&game, 0, city, &item, &plan, &counts) > 0.0);
    ai.advanced_support_production(&mut game, 0, &plan);
    assert!(matches!(
        game.cities[&city].queue.first(),
        Some(Item::Unit { unit }) if unit == "anti_air_gun"
    ));

    game.cities.get_mut(&city).unwrap().queue.clear();
    let city_pos = game.cities[&city].pos;
    game.spawn_test_unit("anti_air_gun", 0, city_pos);
    let counts = ai.counts(&game, 0);
    assert_eq!(counts.air_defense, 1);
    assert!(ai.production_value(&game, 0, city, &item, &plan, &counts) < -9_000.0);
}

#[test]
fn force_readiness_excludes_aircraft_from_ground_armies() {
    let mut game = Game::new_full(2, 24, 16, 71_004, 120, 0, false);
    game.at_war.insert((0, 1));
    let staging = game
        .map
        .tiles
        .iter()
        .find(|(position, tile)| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && game.units_at(**position).is_empty()
        })
        .map(|(position, _)| *position)
        .unwrap();
    let warrior = game.spawn_test_unit("warrior", 0, staging);
    let bomber = game.spawn_test_unit("bomber", 0, staging);
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);

    ai.rebuild_force_groups(&game, 0, &plan);

    let army = ai
        .force_groups
        .iter()
        .find(|group| group.units.contains(&warrior))
        .expect("the ground unit forms an army order");
    assert!(!army.units.contains(&bomber));
    assert!(ai.force_groups.iter().all(|group| {
        group
            .units
            .iter()
            .all(|unit| game.rules.units[game.units[unit].kind].domain.as_deref() != Some("air"))
    }));
}

#[test]
fn command_radius_is_a_group_diameter_not_a_transitive_chain() {
    let mut game = Game::new_full(2, 24, 16, 71_005, 120, 0, false);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    game.at_war.insert((0, 1));
    let chain = [
        game.spawn_test_unit("warrior", 0, (2, 5)),
        game.spawn_test_unit("warrior", 0, (8, 5)),
        game.spawn_test_unit("warrior", 0, (14, 5)),
    ];
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);

    ai.rebuild_force_groups(&game, 0, &plan);

    assert!(ai.force_groups.iter().all(|group| {
        group.units.iter().all(|left| {
            group
                .units
                .iter()
                .all(|right| game.wdist(game.units[left].pos, game.units[right].pos) <= 6)
        })
    }));
    assert!(!ai
        .force_groups
        .iter()
        .any(|group| chain.iter().all(|unit| group.units.contains(unit))));
}

#[test]
fn local_superiority_prices_the_objective_city_defense() {
    let mut game = Game::new_full(2, 24, 16, 71_006, 120, 0, false);
    game.current = 1;
    let settler = game
        .player_unit_ids(1)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(1, &Action::FoundCity { unit: settler }).unwrap();
    let target_city = game.player_city_ids(1)[0];
    for unit in game.player_unit_ids(1) {
        game.remove_unit(unit);
    }
    game.players[1]
        .counters
        .insert("strongest_unit_built".to_string(), 80);
    let city_pos = {
        let city = game.cities.get_mut(&target_city).unwrap();
        city.buildings.push(crate::name!("walls"));
        city.wall_hp = 100;
        city.pos
    };
    let staging = game
        .nbrs(city_pos)
        .into_iter()
        .find(|position| {
            game.map
                .get(*position)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
                && game.units_at(*position).is_empty()
        })
        .unwrap();
    let warrior = game.spawn_test_unit("warrior", 0, staging);
    game.at_war.insert((0, 1));
    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);

    let ratio = ai.local_strength_ratio(&game, 0, &[warrior], &[1], game.cities[&target_city].pos);

    assert!(
        ratio < 0.72,
        "one Warrior must not claim superiority over an intact defended city: {ratio}"
    );
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: Some(target_city),
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    ai.rebuild_force_groups(&game, 0, &plan);
    let order = ai
        .force_groups
        .iter()
        .find(|group| group.units.contains(&warrior))
        .unwrap();
    assert_eq!(order.posture, ForcePosture::Hold);
    assert_eq!(
        match order.posture {
            ForcePosture::Muster | ForcePosture::Hold | ForcePosture::Recover => order.anchor,
            ForcePosture::Engage => order.focus_target.unwrap_or(order.objective),
            ForcePosture::Advance => order.objective,
        },
        order.anchor,
        "an inferior force must hold its formation rather than target the city"
    );

    game.cities.get_mut(&target_city).unwrap().wall_hp = 0;
    game.cities.get_mut(&target_city).unwrap().hp = 1;
    ai.rebuild_force_groups(&game, 0, &plan);
    assert_eq!(
        ai.force_groups
            .iter()
            .find(|group| group.units.contains(&warrior))
            .unwrap()
            .posture,
        ForcePosture::Engage,
        "a forcing city capture must override the otherwise inferior local ratio"
    );
}

/// Build a game with player 0's capital founded, every other unit of its
/// cleared away, and a declared war so force orders are built at all.
fn empire_with_a_capital(seed: u64) -> (Game, u32, Pos) {
    let mut game = Game::new_full(2, 74, 46, seed, 200, 0, false);
    game.current = 0;
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    let home = game.cities[&city].pos;
    for unit in game.player_unit_ids(0) {
        game.remove_unit(unit);
    }
    game.at_war.insert((0, 1));
    (game, city, home)
}

/// ★★★★ Two colonies founded at −19 Loyalty a turn, each lost within eight
/// turns (civvis-20260816T123936Z: Arpinum 18 tiles from the nearest own
/// city, Lugdunum 11), while the mirror's forecast — which sums only the
/// cities on the board — said nothing. See `frontier_loyalty`. A site far
/// beyond the capital's reach on fogged ground is doomed on the live seat
/// and judged sound by the forecast alone; the same site on fully explored
/// ground, and a site inside the capital's halo, are judged as before.
#[test]
fn a_colony_beyond_the_empires_loyalty_reach_on_fogged_ground_is_not_founded() {
    let (mut game, capital, home) = empire_with_a_capital(71_119);
    // ⚠ A pop-1 capital: the rule must not depend on how big it is (the
    // pressure-sum version refused every site of a young empire and
    // stopped run civvis-20260816T142911Z at one city until turn 100).
    game.cities.get_mut(&capital).unwrap().pop = 1;
    // The seat has explored only the capital's neighbourhood.
    let known: Vec<Pos> = game.wdisk(home, 6);
    game.players[0].explored.clear();
    game.players[0].explored.extend(known);
    let far = anchor_at(&game, home, 14);
    let near = anchor_at(&game, home, 4);
    let edge = anchor_at(&game, home, 7);
    let eight = anchor_at(&game, home, 8);

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(live.frontier_loyalty, "the live seat carries the treatment");
    assert!(
        AdvancedAi::beyond_loyalty_reach(&game, 0, far),
        "fourteen tiles out with fog within nine is beyond reach"
    );
    assert!(
        !AdvancedAi::beyond_loyalty_reach(&game, 0, near),
        "four tiles from the capital is inside its reach, whatever its size"
    );
    assert!(
        !AdvancedAi::beyond_loyalty_reach(&game, 0, edge),
        "seven tiles from a pop-1 capital is inside the reach the record shows"
    );
    assert!(
        AdvancedAi::beyond_loyalty_reach(&game, 0, eight),
        "eight tiles out on fogged ground is where the measured colonies revolted"
    );
    assert!(
        live.settle_site_loyalty_verdict(&game, 0, edge).is_none(),
        "a young empire's ordinary sites are not refused"
    );
    let why = live
        .settle_site_loyalty_verdict(&game, 0, far)
        .expect("the live seat dooms the far fogged site");
    assert!(why.contains("beyond the empire's Loyalty reach"), "{why}");
    assert!(live.settle_site_loyalty_verdict(&game, 0, far).is_some());
    assert!(
        live.settle_site_loyalty_verdict(&game, 0, near).is_none(),
        "a site inside the halo with no rival near is sound"
    );

    // Fully explored ground: the far site is judged by the forecast alone,
    // and with no rival city on the board it is sound.
    let mut charted = game.clone();
    let all: Vec<Pos> = charted.map.tiles.keys().copied().collect();
    charted.players[0].explored.extend(all);
    assert!(!AdvancedAi::beyond_loyalty_reach(&charted, 0, far));
    assert!(live.settle_site_loyalty_verdict(&charted, 0, far).is_none());

    // The forecast alone, as stock and the withheld arm see it: sound.
    let stock = AdvancedAi::new();
    assert!(!stock.frontier_loyalty);
    assert!(!AdvancedAi::legacy().frontier_loyalty);
    assert!(stock.settle_site_loyalty_verdict(&game, 0, far).is_none());
    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge();
    withheld.disable_frontier_loyalty();
    assert!(withheld
        .settle_site_loyalty_verdict(&game, 0, far)
        .is_none());
}

/// A city need not be in the mirror's immediate -8-per-turn emergency to be
/// a bad settlement. A young city caught between equal-distance capitals can
/// look merely "Wavering" on its founding turn yet still flip before it has
/// grown into the investment the Settler was meant to make. The advanced
/// settlement forecast must reject that middle band as well, while the
/// ordinary controller keeps its historical selection path.
#[test]
fn advanced_settlers_refuse_a_city_that_will_flip_within_its_growth_horizon() {
    let (mut game, capital, home) = empire_with_a_capital(71_122);
    for position in game.map.tiles.keys().copied().collect::<Vec<_>>() {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
        tile.hills = false;
        tile.resource = None;
        tile.improvement = None;
        tile.district = None;
        tile.wonder = None;
        game.players[0].explored.insert(position);
    }
    for unit in game.player_unit_ids(1) {
        game.remove_unit(unit);
    }

    // Put the rival capital eight tiles out and choose the midpoint. The
    // founding minimum is three tiles, so both four-tile distances are legal.
    let (rival_pos, target) = game
        .map
        .tiles
        .keys()
        .copied()
        .filter(|rival| game.wdist(home, *rival) == 8)
        .find_map(|rival| {
            game.map
                .tiles
                .keys()
                .copied()
                .find(|target| game.wdist(home, *target) == 4 && game.wdist(rival, *target) == 4)
                .map(|target| (rival, target))
        })
        .expect("fixture needs a four-tile midpoint between the capitals");
    let rival = game.found_city_for(1, rival_pos, None);
    game.cities.get_mut(&capital).unwrap().pop = 6;
    game.cities.get_mut(&rival).unwrap().pop = 10;

    let loyalty_per_turn = {
        let mut forecast = game.speculative_clone();
        let city = forecast.found_city_for(0, target, None);
        forecast.city_loyalty_per_turn(&forecast.cities[&city])
    };
    assert!(
        loyalty_per_turn < -100.0 / SETTLE_TARGET_LOYALTY_RISK_TURNS
            && loyalty_per_turn > -8.0,
        "fixture needs the overlooked middle band, not the old immediate emergency: {loyalty_per_turn}"
    );

    // Ensure the test exercises a real choice rather than the score floor.
    for position in game.wdisk(target, 2) {
        if let Some(tile) = game.map.tiles.get_mut(&position) {
            tile.resource = Some(crate::name!("rice"));
        }
    }
    for position in game.map.tiles.keys().copied().collect::<Vec<_>>() {
        if position != target {
            game.blocked_city_sites.insert(position);
        }
    }
    let settler = game.spawn_test_unit("settler", 0, target);
    game.units.get_mut(&settler).unwrap().moves_left = 2.0;
    assert!(game.can_found_city(settler));

    let mut ordinary_board = game.clone();
    let mut ordinary = AdvancedAi::new();
    assert!(
        ordinary.advanced_settler_step(&mut ordinary_board, 0, settler),
        "the ordinary controller retains its established non-forecast path"
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    let why = live
        .settle_site_loyalty_verdict(&game, 0, target)
        .expect("the advanced forecast rejects a city that will flip before it grows");
    assert!(why.contains("revolt in about"), "{why}");
    assert!(
        !live.advanced_settler_step(&mut game, 0, settler),
        "the advanced controller must retire the risky founding rather than spend the Settler"
    );
    assert!(live.settler_site_is_dead(settler, target));
    assert_eq!(game.player_city_ids(0).len(), 1);
}

/// ★★★★ A border with no city behind it is a city in the fog. Run
/// civvis-20260818T155552Z: Setia, founded t55 two tiles from Vietnam's border
/// with none of Vietnam's four cities on the board, read −13.3 Loyalty a turn
/// on its first export and flipped at t63; the forecast had passed it because
/// it sums the cities it can see. See `UNSEEN_MAJOR_BORDER_RADIUS` and
/// `Game::unseen_major_borders`: on the live seat a site within three tiles of
/// such a border is refused before the walk; four tiles out, an empty set,
/// stock and the withheld arm judge by the forecast alone as before.
#[test]
fn a_site_beside_an_unseen_majors_border_is_doomed_before_the_walk() {
    let (mut game, capital, home) = empire_with_a_capital(71_121);
    game.cities.get_mut(&capital).unwrap().pop = 4;
    // Fully explored, so the fog rule cannot be what refuses.
    let all: Vec<Pos> = game.map.tiles.keys().copied().collect();
    game.players[0].explored.extend(all);
    let site = anchor_at(&game, home, 4);
    let border = anchor_at(&game, site, 2);
    let far_border = anchor_at(&game, site, 4);

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(live.frontier_loyalty);
    assert!(
        live.settle_site_loyalty_verdict(&game, 0, site).is_none(),
        "no unseen border on the board: the site is sound"
    );

    game.unseen_major_borders.insert(border);
    assert!(AdvancedAi::beside_unseen_major_border(&game, site));
    let why = live
        .settle_site_loyalty_verdict(&game, 0, site)
        .expect("the live seat dooms a site two tiles from an unseen major's border");
    assert!(
        why.contains("border whose city the seat has never seen"),
        "{why}"
    );

    // Four tiles from the border: outside the radius, judged by the forecast.
    game.unseen_major_borders.clear();
    game.unseen_major_borders.insert(far_border);
    assert!(!AdvancedAi::beside_unseen_major_border(&game, site));
    assert!(live.settle_site_loyalty_verdict(&game, 0, site).is_none());

    // Stock and the withheld arm never read the set.
    game.unseen_major_borders.insert(border);
    let stock = AdvancedAi::new();
    assert!(stock.settle_site_loyalty_verdict(&game, 0, site).is_none());
    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge();
    withheld.disable_frontier_loyalty();
    assert!(withheld
        .settle_site_loyalty_verdict(&game, 0, site)
        .is_none());
}

/// A tile at exactly `distance` from `home`, chosen deterministically so
/// the assertion is about the radius and not about map iteration order.
fn anchor_at(game: &Game, home: Pos, distance: i32) -> Pos {
    let mut candidates: Vec<Pos> = game
        .map
        .tiles
        .keys()
        .copied()
        .filter(|position| game.wdist(*position, home) == distance)
        .collect();
    candidates.sort_unstable();
    *candidates
        .first()
        .unwrap_or_else(|| panic!("no tile sits exactly {distance} hexes from the capital"))
}

/// The defect this exists for: the siege appetite was one unit for any
/// target city at all, so a capital behind 400 points of wall was
/// provisioned exactly like an unwalled frontier town — and once that one
/// unit existed the appetite went to zero.
#[test]
fn the_siege_train_is_sized_by_the_wall_it_has_to_breach() {
    let (mut game, _capital, home) = empire_with_a_capital(71_104);
    let mut sites: Vec<Pos> = game
        .map
        .tiles
        .iter()
        .filter(|(position, tile)| {
            game.wdist(**position, home) >= 15
                && game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
        })
        .map(|(position, _)| *position)
        .collect();
    sites.sort_unstable();
    game.current = 1;
    for site in sites {
        let settler = game.spawn_test_unit("settler", 1, site);
        if game.apply(1, &Action::FoundCity { unit: settler }).is_ok() {
            break;
        }
        game.remove_unit(settler);
    }
    game.current = 0;
    let target = *game.player_city_ids(1).first().expect("a target city");

    let assessed_turn = game.turn;
    let plan_for = move |city: Option<u32>| StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: city,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn,
        rush: false,
    };

    // The city is out of sight, so every reading below comes from the
    // belief layer. Look at it once, the way a scout would.
    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);
    ai.enable_siege_tracks_the_wall();
    let watchtower = game
        .nbrs(game.cities[&target].pos)
        .into_iter()
        .find(|position| game.map.get(*position).is_some())
        .expect("a tile beside the city");
    let scout = game.spawn_test_unit("scout", 0, watchtower);

    let wanted = move |ai: &AdvancedAi, game: &Game, city: Option<u32>| {
        ai.siege_units_wanted(game, 0, &plan_for(city))
    };

    // No target at all: no siege train, walls or not.
    assert_eq!(wanted(&ai, &game, None), 0);

    // An unwalled target does not need one either — melee takes the city
    // and siege units can never land the capturing blow.
    game.cities.get_mut(&target).unwrap().wall_hp = 0;
    assert_eq!(wanted(&ai, &game, Some(target)), 0);

    // One tier of wall, one train; four tiers, the cap.
    game.cities.get_mut(&target).unwrap().wall_hp = 100;
    assert_eq!(wanted(&ai, &game, Some(target)), 1);
    game.cities.get_mut(&target).unwrap().wall_hp = 300;
    assert_eq!(wanted(&ai, &game, Some(target)), 2);
    game.cities.get_mut(&target).unwrap().wall_hp = 400;
    assert_eq!(
        wanted(&ai, &game, Some(target)),
        SIEGE_UNITS_MAX,
        "a fully walled capital is worth the whole train"
    );

    // The wall is read from memory once the scout leaves, so a fogged
    // capital still provisions the campaign that has to breach it.
    ai.belief.observe(&game, 0);
    game.remove_unit(scout);
    assert!(
        !game.player_can_see(0, game.cities[&target].pos),
        "the target must be fogged for the memory path to be exercised"
    );
    assert_eq!(
        wanted(&ai, &game, Some(target)),
        SIEGE_UNITS_MAX,
        "the wall a city had when we last looked still sizes the train"
    );

    // The control still refuses to guess. The live fog repair instead
    // requests the conservative one-tier floor for a city it has never
    // seen, which is enough to put a siege unit in the production plan.
    let mut unseen = AdvancedAi::targeting(VictoryTarget::Domination);
    unseen.enable_siege_tracks_the_wall();
    assert_eq!(wanted(&unseen, &game, Some(target)), 0);
    unseen.enable_blind_objective_strength();
    assert_eq!(wanted(&unseen, &game, Some(target)), 1);

    // The shipped agent is unchanged: one unit for any target, zero
    // otherwise, whatever the wall is doing.
    let shipped = AdvancedAi::targeting(VictoryTarget::Domination);
    assert!(!shipped.siege_tracks_the_wall);
    assert_eq!(wanted(&shipped, &game, Some(target)), 1);
    assert_eq!(wanted(&shipped, &game, None), 0);
    game.cities.get_mut(&target).unwrap().wall_hp = 0;
    assert_eq!(
        wanted(&shipped, &game, Some(target)),
        1,
        "the shipped rule never looked at the wall"
    );
}

/// The defect this exists for: the movement score charged for the threat a
/// tile accepts and credited nothing for the attack it opens, so a melee
/// unit never volunteered for the tile it has to occupy to swing.
#[test]
fn a_tile_is_worth_the_attack_it_opens() {
    let (mut game, _capital, home) = empire_with_a_capital(71_106);
    let ours = game.spawn_test_unit("warrior", 0, anchor_at(&game, home, 2));
    let target = anchor_at(&game, home, 4);
    let theirs = game.spawn_test_unit("warrior", 1, target);

    let group = ForceGroup {
        id: ours,
        domain: ForceDomain::Land,
        units: vec![ours],
        anchor: game.units[&ours].pos,
        objective: target,
        focus_target: Some(target),
        posture: ForcePosture::Engage,
        readiness: 1.0,
        local_strength_ratio: 1.0,
    };
    let enemies = vec![1usize];
    let adjacent = game
        .nbrs(target)
        .into_iter()
        .find(|position| game.map.get(*position).is_some())
        .expect("a tile beside the enemy");

    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);
    assert!(!ai.strike_opening, "the shipped default must be unchanged");
    assert_eq!(
        ai.strike_opening_value(&game, 0, ours, adjacent, &group, &enemies, None),
        0.0,
        "the shipped agent credits nothing"
    );

    ai.enable_strike_opening();
    let in_contact = ai.strike_opening_value(&game, 0, ours, adjacent, &group, &enemies, None);
    assert!(
        in_contact > 0.0,
        "a tile that puts the target in reach must be worth something: {in_contact}"
    );
    // Two even warriors: odds are 0.5, so the credit is half the scale.
    assert!(
        (in_contact - STRIKE_OPENING_SCALE * 30.0 * 0.5).abs() < 1.5,
        "even odds should pay about half the scale, got {in_contact}"
    );

    // A tile out of reach opens nothing.
    let far = anchor_at(&game, home, 1);
    assert_eq!(
        ai.strike_opening_value(&game, 0, ours, far, &group, &enemies, None),
        0.0,
        "a tile the target cannot be struck from is worth nothing"
    );

    // Only while prosecuting. A group that is holding is not paid to close.
    let holding = ForceGroup {
        posture: ForcePosture::Hold,
        ..group.clone()
    };
    assert_eq!(
        ai.strike_opening_value(&game, 0, ours, adjacent, &holding, &enemies, None),
        0.0,
        "a held group must not be pulled into contact"
    );

    // A wounded defender is worth more than a fresh one, because the odds
    // of the strike are better.
    game.units.get_mut(&theirs).unwrap().hp = 30;
    let wounded = ai.strike_opening_value(&game, 0, ours, adjacent, &group, &enemies, None);
    assert!(
        wounded > in_contact,
        "pouncing on a wounded target must score higher: {wounded} vs {in_contact}"
    );
}

/// The defect this exists for: the army target was a headcount keyed to
/// our own city count, so an empire being outweighed two to one declared
/// its army finished and went back to building markets.
#[test]
fn the_army_target_rises_when_the_enemy_outweighs_us() {
    let (mut game, _capital, home) = empire_with_a_capital(71_105);
    let mut sites: Vec<Pos> = game
        .map
        .tiles
        .iter()
        .filter(|(position, tile)| {
            game.wdist(**position, home) >= 15
                && game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
        })
        .map(|(position, _)| *position)
        .collect();
    sites.sort_unstable();
    let muster = sites[0];

    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);
    ai.enable_army_target_weighs_the_enemy();
    let shipped = AdvancedAi::targeting(VictoryTarget::Domination);

    // An army of ours that comfortably outweighs theirs. `empire_with_a_capital`
    // strips our starting units, so this is the whole of our power.
    for step in 0..6 {
        game.spawn_test_unit("warrior", 0, anchor_at(&game, home, 1 + step));
    }
    game.spawn_test_unit("warrior", 1, muster);
    assert_eq!(
        ai.enemy_weighted_army_target(&game, 0, 12),
        12,
        "while we are ahead the shipped target is exactly what it was"
    );

    // They pass us. The target rises with the gap and never falls below
    // the shipped floor.
    for _ in 0..12 {
        game.spawn_test_unit("warrior", 1, muster);
    }
    let raised = ai.enemy_weighted_army_target(&game, 0, 12);
    assert!(
        raised > 12,
        "an army twice ours must want more than the peacetime twelve: {raised}"
    );
    assert!(raised <= 24, "the 2x ceiling holds: {raised}");

    // However far ahead they run, the empire is not asked to become
    // nothing but soldiers.
    for _ in 0..60 {
        game.spawn_test_unit("warrior", 1, muster);
    }
    assert_eq!(
        ai.enemy_weighted_army_target(&game, 0, 12),
        24,
        "a runaway rival is still capped at WARTIME_ARMY_CEILING"
    );

    // Peace with the same strong rival: the wartime scaling must not apply.
    game.at_war.remove(&(0, 1));
    game.at_war.remove(&(1, 0));
    assert_eq!(
        ai.enemy_weighted_army_target(&game, 0, 12),
        12,
        "a rival we are not fighting does not size our army"
    );

    // And the shipped agent never moves at all, war or not.
    game.at_war.insert((0, 1));
    assert!(!shipped.army_target_weighs_the_enemy);
    assert_eq!(shipped.enemy_weighted_army_target(&game, 0, 12), 12);
}

/// The defect this exists for: both army targets were blind until the war
/// started. Run `civvis-20260803T220954Z` founded seven cities, Mali
/// declared at t157 holding 894 military against our 481, and six of the
/// seven fell at loyalty 100 — sieges, not revolts, including the capital.
/// A target that asks "who could kill me" only after the declaration asks
/// too late; deterrence has to exist while the peace still holds.
#[test]
fn the_army_target_deters_the_strongest_met_major_in_peacetime() {
    let (mut game, _capital, home) = empire_with_a_capital(71_106);
    let mut sites: Vec<Pos> = game
        .map
        .tiles
        .iter()
        .filter(|(position, tile)| {
            game.wdist(**position, home) >= 15
                && game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
        })
        .map(|(position, _)| *position)
        .collect();
    sites.sort_unstable();
    let muster = sites[0];

    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);
    ai.enable_peacetime_deterrence();

    // Everyone is at peace, and the rival has been met.
    game.at_war.remove(&(0, 1));
    game.at_war.remove(&(1, 0));
    game.players[0].met.insert(1);
    game.players[1].met.insert(0);

    // While we outweigh the met rival the shipped target stands.
    for step in 0..6 {
        game.spawn_test_unit("warrior", 0, anchor_at(&game, home, 1 + step));
    }
    game.spawn_test_unit("warrior", 1, muster);
    assert_eq!(
        ai.enemy_weighted_army_target(&game, 0, 12),
        12,
        "a weaker met major does not size our peacetime army"
    );

    // They pass us in peace. The target rises — but under the deterrence
    // ceiling, which sits far below the wartime doubling.
    for _ in 0..12 {
        game.spawn_test_unit("warrior", 1, muster);
    }
    let raised = ai.enemy_weighted_army_target(&game, 0, 12);
    assert!(
        raised > 12,
        "a met major outweighing us must raise the peacetime target: {raised}"
    );
    assert!(
        raised <= 18,
        "deterrence wants a standing army, not a war footing: {raised}"
    );

    // However far ahead they run, peace never asks for a war footing.
    for _ in 0..60 {
        game.spawn_test_unit("warrior", 1, muster);
    }
    assert_eq!(
        ai.enemy_weighted_army_target(&game, 0, 12),
        18,
        "the peacetime ceiling holds however strong the met major grows"
    );

    // A major this seat has never met cannot size its army — the floor
    // reads no information fog has not released.
    game.players[0].met.remove(&1);
    assert_eq!(
        ai.enemy_weighted_army_target(&game, 0, 12),
        12,
        "an unmet major must not reach the peacetime target through fog"
    );

    // ⚠ `has_met` answers `true` for a TEAMMATE, so an ally's army would
    // otherwise deter us. `ai_eval` seats a free-for-all (`teams` empty,
    // every `player.team` None), so this arm is unreachable there and the
    // guard is inert in every evaluated game — but it is reachable in a
    // team lobby, which is why it is pinned rather than argued.
    game.players[0].met.insert(1);
    game.players[0].team = Some(1);
    game.players[1].team = Some(1);
    assert_eq!(
        ai.enemy_weighted_army_target(&game, 0, 12),
        12,
        "an ally on our own team must not size our army"
    );
    game.players[0].team = None;
    game.players[1].team = None;

    // War with the same rival escalates past the deterrence ceiling: the
    // wartime term takes over under its larger ceiling.
    game.players[0].met.insert(1);
    game.at_war.insert((0, 1));
    ai.enable_army_target_weighs_the_enemy();
    assert_eq!(
        ai.enemy_weighted_army_target(&game, 0, 12),
        24,
        "once the war is real the wartime ceiling governs, not the floor"
    );

    // The shipped agent never moves at all.
    let shipped = AdvancedAi::targeting(VictoryTarget::Domination);
    assert!(!shipped.peacetime_deterrence);
    game.at_war.remove(&(0, 1));
    assert_eq!(shipped.enemy_weighted_army_target(&game, 0, 12), 12);
}

/// The defect this exists for: `do_promote` heals up to 50 and costs the
/// unit its turn, and promotions were taken the instant they appeared — so
/// 43% of the 359 promotions in the corpus were taken at full health and
/// threw the whole heal away.
#[test]
fn a_promotion_waits_until_its_healing_would_land() {
    let (mut game, _capital, home) = empire_with_a_capital(71_107);
    let warrior = game.spawn_test_unit("warrior", 0, anchor_at(&game, home, 1));
    game.units.get_mut(&warrior).unwrap().xp = 200;
    game.units.get_mut(&warrior).unwrap().level = 1;

    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);
    assert!(
        !ai.promote_when_wounded,
        "the shipped default must be unchanged"
    );
    assert!(
        !ai.promotion_heal_is_wasted(&game, warrior),
        "the shipped agent never holds a promotion back"
    );

    ai.enable_promote_when_wounded();
    // Full health: every point of the heal would be thrown away.
    game.units.get_mut(&warrior).unwrap().hp = 100;
    assert!(ai.promotion_heal_is_wasted(&game, warrior));

    // Just above the ceiling is still a waste; at it, the promotion lands.
    game.units.get_mut(&warrior).unwrap().hp = PROMOTE_HEAL_HP_CEILING + 1;
    assert!(ai.promotion_heal_is_wasted(&game, warrior));
    game.units.get_mut(&warrior).unwrap().hp = PROMOTE_HEAL_HP_CEILING;
    assert!(!ai.promotion_heal_is_wasted(&game, warrior));

    // A badly hurt unit promotes and is healed for it — the whole point.
    game.units.get_mut(&warrior).unwrap().hp = 40;
    assert!(!ai.promotion_heal_is_wasted(&game, warrior));
    let before = game.units[&warrior].hp;
    if let Some(promotion) = game.available_promotions(warrior).into_iter().next() {
        game.units.get_mut(&warrior).unwrap().moves_left = 2.0;
        game.apply(
            0,
            &Action::Promote {
                unit: warrior,
                promotion: Name::new(&promotion),
            },
        )
        .expect("a banked promotion is available");
        assert_eq!(
            game.units[&warrior].hp,
            (before + 50).min(100),
            "promoting a wounded unit is worth up to 50 health"
        );
    }

    // A unit that no longer exists is not a promotion decision.
    assert!(!ai.promotion_heal_is_wasted(&game, u32::MAX));
}

/// The defect this exists for: a walled enemy capital the army cannot
/// currently see scored identically to an empty meadow, because
/// `local_strength_ratio` reached its `hostile <= 0.0` sentinel and
/// returned 3.0 — four times the superiority floor. One lone warrior
/// therefore read itself as locally dominant over a city.
#[test]
fn a_fogged_objective_city_is_priced_from_the_last_sighting() {
    let (mut game, _capital, home) = empire_with_a_capital(71_103);
    // An enemy city far enough away that nothing of ours can see it.
    let mut sites: Vec<Pos> = game
        .map
        .tiles
        .iter()
        .filter(|(position, tile)| {
            game.wdist(**position, home) >= 15
                && game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
        })
        .map(|(position, _)| *position)
        .collect();
    sites.sort_unstable();
    game.current = 1;
    for site in sites {
        let settler = game.spawn_test_unit("settler", 1, site);
        if game.apply(1, &Action::FoundCity { unit: settler }).is_ok() {
            break;
        }
        game.remove_unit(settler);
    }
    game.current = 0;
    let enemy_city = *game
        .player_city_ids(1)
        .first()
        .expect("the enemy must have somewhere to be attacked");
    let objective = game.cities[&enemy_city].pos;
    for unit in game.player_unit_ids(1) {
        game.remove_unit(unit);
    }

    // Korea's Seoul was no frontier outpost, so neither is this: an empire
    // fielding field cannons defends its cities at that standard.
    game.players[1]
        .counters
        .insert("strongest_unit_built".to_string(), 60);

    // One warrior, standing well outside its own sight range of the city.
    let warrior = game.spawn_test_unit("warrior", 0, anchor_at(&game, home, 6));
    assert!(
        !game.player_can_see(0, objective),
        "the setup must leave the objective fogged"
    );

    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);
    assert!(
        !ai.blind_objective_strength,
        "the shipped default must be unchanged"
    );
    assert_eq!(
        ai.local_strength_ratio(&game, 0, &[warrior], &[1], objective),
        3.0,
        "the shipped rule reads a fogged city as no enemy at all"
    );

    // A scout walks up, sees the city, and leaves. Nothing about the city
    // changed — only what this controller has observed of it.
    let watchtower = game
        .nbrs(objective)
        .into_iter()
        .find(|position| game.map.get(*position).is_some())
        .expect("a tile beside the city");
    let scout = game.spawn_test_unit("scout", 0, watchtower);
    let in_sight = ai.local_strength_ratio(&game, 0, &[warrior], &[1], objective);
    ai.belief.observe(&game, 0);
    game.remove_unit(scout);
    assert!(
        !game.player_can_see(0, objective),
        "the city is fogged again once the scout is gone"
    );
    assert!(
        ai.remembered_city(enemy_city).is_some(),
        "the sighting must survive the fog"
    );

    ai.enable_blind_objective_strength();
    let ratio = ai.local_strength_ratio(&game, 0, &[warrior], &[1], objective);
    assert_eq!(
        ratio, in_sight,
        "an unchanged city must read the same remembered as it did in sight"
    );
    assert!(
        ratio < LOCAL_SUPERIORITY_FLOOR,
        "one warrior is not locally superior to a city it remembers: {ratio}"
    );

    // Memory is still the preferred input, but a city this controller has
    // never seen receives the generic floor rather than scoring as absent.
    let mut unseen = AdvancedAi::targeting(VictoryTarget::Domination);
    unseen.enable_blind_objective_strength();
    let unseen_ratio = unseen.local_strength_ratio(&game, 0, &[warrior], &[1], objective);
    assert!(
        unseen_ratio < LOCAL_SUPERIORITY_FLOOR,
        "one warrior must not read an unseen city as locally dominant: {unseen_ratio}"
    );
}

#[test]
fn global_recovery_holds_an_unthreatened_front_but_keeps_a_forcing_finish() {
    // The t106 live-Rome shape: a declared major war and an enemy city
    // known outside current sight, but no local siege yet. The ordinary
    // fog-safe mover can still see a 3.00 local ratio here; Recovery must
    // make that a temporary home hold rather than an offensive march.
    let (mut game, _capital, home) = empire_with_a_capital(71_116);
    let enemy_site = game
        .map
        .tiles
        .iter()
        .filter(|(position, tile)| {
            game.wdist(**position, home) >= 15
                && game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
        })
        .map(|(position, _)| *position)
        .min()
        .expect("fixture needs a distant enemy city site");
    game.current = 1;
    let enemy_settler = game.spawn_test_unit("settler", 1, enemy_site);
    game.apply(
        1,
        &Action::FoundCity {
            unit: enemy_settler,
        },
    )
    .expect("found the distant enemy city");
    game.current = 0;
    let target_city = *game
        .player_city_ids(1)
        .first()
        .expect("the enemy must own its founded city");
    let objective = game.cities[&target_city].pos;
    for unit in game.player_unit_ids(1) {
        game.remove_unit(unit);
    }
    let launch = game
        .nbrs(home)
        .into_iter()
        .find(|position| {
            game.map.get(*position).is_some_and(|tile| {
                game.rules.is_passable(tile)
                    && !game.rules.is_water(tile)
                    && game.city_at(*position).is_none()
                    && game.units_at(*position).is_empty()
            })
        })
        .expect("the capital has an empty land launch tile");
    let warrior = game.spawn_test_unit("warrior", 0, launch);
    assert!(
        !game.player_can_see(0, objective),
        "the objective must be outside the turn-start sight frame"
    );

    let conquest = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: Some(target_city),
        threatened_city: None,
        desired_cities: 2,
        assessed_turn: game.turn,
        rush: false,
    };
    let recovery = StrategicPlan {
        strategy: GrandStrategy::Recovery,
        ..conquest.clone()
    };
    let mut ai = AdvancedAi::new();
    ai.enable_bounded_recovery();
    assert!(
        ai.bounded_recovery,
        "the explicit bounded-Recovery treatment carries the bounded policy"
    );

    ai.rebuild_force_groups(&game, 0, &conquest);
    assert_eq!(
        ai.force_groups()
            .iter()
            .find(|group| group.units.contains(&warrior))
            .expect("the warrior receives a normal force order")
            .posture,
        ForcePosture::Advance,
        "outside Recovery the fogged city remains the ordinary campaign objective"
    );

    ai.rebuild_force_groups(&game, 0, &recovery);
    let holding = ai
        .force_groups()
        .iter()
        .find(|group| group.units.contains(&warrior))
        .expect("the warrior receives a Recovery force order");
    assert_eq!(holding.objective, objective);
    assert_eq!(
            holding.posture,
            ForcePosture::Hold,
            "an outmatched Recovery plan without a threatened city must not advance on a fogged campaign objective"
        );

    let mut legacy = AdvancedAi::legacy();
    legacy.rebuild_force_groups(&game, 0, &recovery);
    assert_eq!(
        legacy
            .force_groups()
            .iter()
            .find(|group| group.units.contains(&warrior))
            .expect("the frozen controller receives the same force order")
            .posture,
        ForcePosture::Advance,
        "the legacy anchor leaves bounded Recovery off and keeps its historical campaign movement"
    );

    // A finishable adjacent unit still overrides the home hold. This is
    // the existing forcing-focus exception, not a second attack policy.
    let contact = game
        .nbrs(launch)
        .into_iter()
        .find(|position| {
            game.map.get(*position).is_some_and(|tile| {
                game.rules.is_passable(tile)
                    && !game.rules.is_water(tile)
                    && game.city_at(*position).is_none()
                    && game.units_at(*position).is_empty()
            })
        })
        .expect("the warrior has an empty adjacent land contact");
    let enemy = game.spawn_test_unit("warrior", 1, contact);
    game.units.get_mut(&enemy).unwrap().hp = 1;
    ai.rebuild_force_groups(&game, 0, &recovery);
    assert_eq!(
        ai.force_groups()
            .iter()
            .find(|group| group.units.contains(&warrior))
            .expect("the warrior keeps its force order at contact")
            .posture,
        ForcePosture::Engage,
        "Recovery may still finish a visible enemy it can immediately remove"
    );
}

#[test]
fn bomber_exact_result_search_prefers_a_kill_over_static_strength() {
    let mut game = Game::new_full(2, 24, 16, 71_005, 120, 0, false);
    game.at_war.insert((0, 1));
    for unit in game.player_unit_ids(0) {
        game.remove_unit(unit);
    }
    for unit in game.player_unit_ids(1) {
        game.remove_unit(unit);
    }
    let base = game
        .map
        .tiles
        .iter()
        .find(|(position, tile)| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && game.city_at(**position).is_none()
        })
        .map(|(position, _)| *position)
        .unwrap();
    let mut targets: Vec<Pos> =
        game.wdisk(base, game.rules.units["bomber"].range)
            .into_iter()
            .filter(|position| {
                *position != base
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
                    && game.city_at(*position).is_none()
            })
            .take(2)
            .collect();
    assert_eq!(targets.len(), 2);
    targets.sort_unstable();
    let bomber = game.spawn_test_unit("bomber", 0, base);
    game.spawn_test_unit("modern_armor", 1, targets[0]);
    let warrior = game.spawn_test_unit("warrior", 1, targets[1]);
    game.units.get_mut(&warrior).unwrap().hp = 1;
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let ai = AdvancedAi::targeting(VictoryTarget::Domination);

    assert_eq!(
        ai.advanced_air_action(&game, 0, bomber, &plan),
        Some(Action::AirStrike {
            unit: bomber,
            target: targets[1],
        })
    );
}

#[test]
fn bomber_planners_choose_high_value_air_pillage_over_low_value_strikes() {
    let mut game = Game::new_full(2, 24, 16, 71_006, 120, 0, false);
    game.at_war.insert((0, 1));
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    let enemy_center = game
        .map
        .tiles
        .iter()
        .find(|(_, tile)| game.rules.is_passable(tile) && !game.rules.is_water(tile))
        .map(|(position, _)| *position)
        .unwrap();
    let enemy_city = game.found_city_for(1, enemy_center, None);
    let target = game
        .nbrs(enemy_center)
        .into_iter()
        .find(|position| {
            game.map
                .get(*position)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
        })
        .unwrap();
    {
        let tile = game.map.tiles.get_mut(&target).unwrap();
        tile.owner_city = Some(enemy_city);
        tile.improvement = Some(crate::name!("airstrip"));
        tile.pillaged = false;
    }
    let base =
        game.wdisk(target, game.rules.units["bomber"].range)
            .into_iter()
            .find(|position| {
                *position != target
                    && *position != enemy_center
                    && game.wdist(*position, target) >= 3
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .unwrap();
    game.found_city_for(0, base, None);
    let bomber = game.spawn_test_unit("bomber", 0, base);
    let expected = Action::AirPillage {
        unit: bomber,
        target,
    };
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: Some(enemy_city),
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };

    assert_eq!(
        BasicAi::new().doctrine_action(&game, 0, bomber),
        Some(expected.clone())
    );
    assert_eq!(
        AdvancedAi::targeting(VictoryTarget::Domination)
            .advanced_air_action(&game, 0, bomber, &plan),
        Some(expected)
    );
}

