#[test]
fn exact_ground_search_prefers_the_high_value_kill_over_a_static_tie() {
    let mut game = Game::new_full(2, 24, 16, 71_009, 120, 0, false);
    game.at_war.insert((0, 1));
    let rival_origin = game
        .player_unit_ids(1)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .map(|unit| game.units[&unit].pos)
        .unwrap();
    game.found_city_for(1, rival_origin, None);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    let (base, mut targets) = game
        .map
        .tiles
        .iter()
        .filter(|(position, tile)| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && game.city_at(**position).is_none()
                && game
                    .cities
                    .values()
                    .all(|city| game.wdist(**position, city.pos) > 5)
        })
        .find_map(|(base, _)| {
            let targets: Vec<Pos> = game
                .nbrs(*base)
                .into_iter()
                .filter(|position| {
                    game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    }) && game.city_at(*position).is_none()
                })
                .collect();
            (targets.len() >= 2).then_some((*base, targets))
        })
        .expect("test map has an isolated two-target engagement");
    targets.sort_unstable();
    let robot = game.spawn_test_unit("giant_death_robot", 0, base);
    let warrior = game.spawn_test_unit("warrior", 1, targets[0]);
    let armor = game.spawn_test_unit("modern_armor", 1, targets[1]);
    game.units.get_mut(&warrior).unwrap().hp = 1;
    game.units.get_mut(&armor).unwrap().hp = 1;
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);

    assert_eq!(
        ai.base.exchange_score(&game, robot, targets[0], true),
        ai.base.exchange_score(&game, robot, targets[1], true),
        "the static evaluator intentionally sees two one-hit kills"
    );
    let warrior_value = ai.tactical_attack_value(
        &game,
        0,
        robot,
        &Action::Ranged {
            unit: robot,
            target: targets[0],
        },
        &plan,
    );
    let armor_value = ai.tactical_attack_value(
        &game,
        0,
        robot,
        &Action::Ranged {
            unit: robot,
            target: targets[1],
        },
        &plan,
    );
    assert!(armor_value > warrior_value + 100.0);
    assert!(ai.advanced_military_step(&mut game, 0, robot, &plan));
    assert!(!game.units.contains_key(&armor));
    assert!(game.units.contains_key(&warrior));
    assert!(matches!(
        game.log.last(),
        Some((0, Action::Attack { target, .. } | Action::Ranged { target, .. }))
            if *target == targets[1]
    ));
}

#[test]
fn army_declines_a_captured_settler_when_no_city_site_remains() {
    let mut game = Game::new_full(2, 20, 14, 71_019, 120, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.found_city_for(pid, game.units[&settler].pos, None);
        game.remove_unit(settler);
    }
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    let home = game.cities[&game.player_city_ids(0)[0]].pos;
    let origin = game.nbrs(home)[0];
    let target = game
        .nbrs(origin)
        .into_iter()
        .find(|position| *position != home && game.wdist(home, *position) <= 2)
        .unwrap();
    let city_centers: BTreeSet<Pos> = game.cities.values().map(|city| city.pos).collect();
    for (position, tile) in &mut game.map.tiles {
        if ![home, origin, target].contains(&position) && !city_centers.contains(&position) {
            tile.terrain = crate::name!("ocean");
            tile.feature = None;
        }
    }
    for position in [origin, target] {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    game.at_war.insert((0, 1));
    let warrior = game.spawn_test_unit("warrior", 0, origin);
    let settler = game.spawn_test_unit("settler", 1, target);
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: game.player_city_ids(1).first().copied(),
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    assert!(!ai.base.has_practical_settle_site(&game, 0));
    let mut direct_capture = game.clone();
    let capture_result = direct_capture.apply(
        0,
        &Action::Move {
            unit: warrior,
            to: target,
        },
    );
    assert!(
        capture_result.is_ok(),
        "staged capture was not legal: {capture_result:?}"
    );
    assert_eq!(direct_capture.units[&settler].owner, 0);

    let _ = ai.advanced_military_step(&mut game, 0, warrior, &plan);

    assert_eq!(
        game.units.get(&settler).map(|unit| unit.owner),
        Some(1),
        "capturing the civilian would create a settler with no legal city site"
    );

    game.remove_unit(warrior);
    let scout = game.spawn_test_unit("scout", 0, origin);
    let _ = ai.advanced_military_step(&mut game, 0, scout, &plan);
    assert_eq!(
        game.units.get(&settler).map(|unit| unit.owner),
        Some(1),
        "a recon fallback must not bypass the unwanted-settler guard"
    );
}

#[test]
fn army_takes_a_free_settler_after_reaching_its_planned_city_count() {
    let mut game = Game::new_full(2, 20, 14, 71_020, 120, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.found_city_for(pid, game.units[&settler].pos, None);
    }
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    let origin = game.cities[&game.player_city_ids(0)[0]].pos;
    let target =
        game.nbrs(origin)
            .into_iter()
            .find(|position| {
                game.city_at(*position).is_none()
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .unwrap();
    game.at_war.insert((0, 1));
    let warrior = game.spawn_test_unit("warrior", 0, origin);
    let settler = game.spawn_test_unit("settler", 1, target);
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: game.player_city_ids(1).first().copied(),
        threatened_city: None,
        desired_cities: 1,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    assert!(ai.base.has_practical_settle_site(&game, 0));

    assert!(ai.advanced_military_step(&mut game, 0, warrior, &plan));
    assert_eq!(game.units[&settler].owner, 0);
    assert!(matches!(
        game.log.last(),
        Some((0, Action::Move { unit, to })) if *unit == warrior && *to == target
    ));
}

#[test]
fn exact_hybrid_search_uses_melee_to_finish_a_city() {
    let mut game = Game::new_full(2, 24, 16, 71_010, 120, 0, false);
    let rival_origin = game
        .player_unit_ids(1)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .map(|unit| game.units[&unit].pos)
        .unwrap();
    let city = game.found_city_for(1, rival_origin, None);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    let target = game.cities[&city].pos;
    let staging = game
        .nbrs(target)
        .into_iter()
        .find(|position| {
            game.map
                .get(*position)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
                && game.units_at(*position).is_empty()
        })
        .unwrap();
    game.cities.get_mut(&city).unwrap().hp = 0;
    game.cities.get_mut(&city).unwrap().wall_hp = 0;
    let robot = game.spawn_test_unit("giant_death_robot", 0, staging);
    game.at_war.insert((0, 1));
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: Some(city),
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);

    assert!(ai.advanced_military_step(&mut game, 0, robot, &plan));
    assert_eq!(game.cities[&city].owner, 0);
    assert!(matches!(
        game.log.last(),
        Some((0, Action::Attack { unit, target: action_target }))
            if *unit == robot && *action_target == target
    ));
}

#[test]
fn conquest_waits_to_recapture_an_unholdable_original_capital() {
    let mut game = Game::new_full(3, 30, 18, 71_020, 120, 0, false);
    for pid in 0..3 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        let position = game.units[&settler].pos;
        game.found_city_for(pid, position, None);
    }
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }

    let target_city = game.player_city_ids(1)[0];
    let target = game.cities[&target_city].pos;
    let pressure_site =
        game.wdisk(target, 6)
            .into_iter()
            .find(|position| {
                (4..=6).contains(&game.wdist(*position, target))
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
                    && game.city_at(*position).is_none()
                    && game
                        .cities
                        .values()
                        .all(|city| game.wdist(city.pos, *position) >= 4)
            })
            .expect("test map has a nearby pressure city site");
    let pressure_city = game.found_city_for(1, pressure_site, Some("Pressure".to_string()));
    let remote_site = game
        .map
        .tiles
        .iter()
        .find_map(|(position, tile)| {
            (game.wdist(*position, target) > 9
                && game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && game.city_at(*position).is_none()
                && game
                    .cities
                    .values()
                    .all(|city| game.wdist(city.pos, *position) >= 4))
            .then_some(*position)
        })
        .expect("test map has a remote surviving city site");
    let remote_city = game.found_city_for(1, remote_site, Some("Reserve".to_string()));
    for city in game.cities.values_mut() {
        city.pop = 1;
    }
    game.cities.get_mut(&pressure_city).unwrap().pop = 40;
    game.cities.get_mut(&remote_city).unwrap().pop = 1;
    {
        let city = game.cities.get_mut(&target_city).unwrap();
        city.hp = 0;
        city.wall_hp = 0;
        city.loyalty = 100.0;
    }
    let staging = game
        .nbrs(target)
        .into_iter()
        .find(|position| {
            game.map
                .get(*position)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
                && game.units_at(*position).is_empty()
        })
        .expect("the capital has an open melee approach");
    let attacker = game.spawn_test_unit("giant_death_robot", 0, staging);
    game.at_war.insert((0, 1));
    game.current = 0;
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: Some(target_city),
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    };
    let capture = Action::Attack {
        unit: attacker,
        target,
    };
    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);
    let _target_observer = game.spawn_test_unit("scout", 0, game.cities[&target_city].pos);
    let _pressure_observer = game.spawn_test_unit("scout", 0, game.cities[&pressure_city].pos);
    ai.belief.observe(&game, 0);

    assert!(AdvancedAi::should_defer_city_capture(&game, 0, target_city));
    assert!(
        ai.campaign_city_value(
            &game,
            0,
            &game.cities[&target_city],
            GrandStrategy::Conquest
        ) > ai.campaign_city_value(
            &game,
            0,
            &game.cities[&pressure_city],
            GrandStrategy::Conquest,
        ),
        "the surrounding pressure city should become the campaign objective first"
    );
    assert_eq!(
        ai.tactical_attack_value(&game, 0, attacker, &capture, &plan),
        f64::NEG_INFINITY
    );
    let mut blocked = game.clone();
    let _ = ai.advanced_military_step(&mut blocked, 0, attacker, &plan);
    assert_eq!(
        blocked.cities[&target_city].owner, 1,
        "the army must not restart a forced capital recapture loop"
    );

    let mut supported = game;
    supported.cities.get_mut(&pressure_city).unwrap().owner = 0;
    assert_eq!(supported.player_city_ids(1).len(), 2);
    assert!(!AdvancedAi::should_defer_city_capture(
        &supported,
        0,
        target_city
    ));
    assert!(ai
        .tactical_attack_value(&supported, 0, attacker, &capture, &plan)
        .is_finite());
    assert!(ai.advanced_military_step(&mut supported, 0, attacker, &plan));
    assert_eq!(supported.cities[&target_city].owner, 0);
}

#[test]
fn culture_production_trains_one_archaeologist_for_available_artifact_slots() {
    let mut game = Game::new(2, 24, 16, 7_100, 1_500, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    clear_barbarian_fixture(&mut game);
    game.cities
        .get_mut(&city)
        .unwrap()
        .buildings
        .push(crate::name!("archaeological_museum"));
    game.players[0]
        .civics
        .insert(crate::name!("natural_history"));
    let site = game.cities[&city]
        .owned_tiles
        .iter()
        .copied()
        .find(|position| *position != game.cities[&city].pos)
        .unwrap();
    let tile = game.map.tiles.get_mut(&site).unwrap();
    tile.terrain = crate::name!("plains");
    tile.feature = None;
    tile.resource = Some(crate::name!("antiquity_site"));
    tile.improvement = None;
    tile.district = None;
    tile.wonder = None;
    let archaeologist_item = Item::Unit {
        unit: crate::name!("archaeologist"),
    };
    assert!(game.can_produce(0, city, &archaeologist_item));

    let plan = StrategicPlan {
        strategy: GrandStrategy::Culture,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::targeting(VictoryTarget::Culture);
    ai.advanced_production(&mut game, 0, &plan, false);
    assert!(
        matches!(
            game.cities[&city].queue.first(),
            Some(Item::Unit { unit }) if unit == "archaeologist"
        ),
        "queued {:?}",
        game.cities[&city].queue.first()
    );

    game.cities.get_mut(&city).unwrap().queue.clear();
    game.spawn_test_unit("archaeologist", 0, game.cities[&city].pos);
    ai.advanced_production(&mut game, 0, &plan, false);
    assert!(!matches!(
        game.cities[&city].queue.first(),
        Some(Item::Unit { unit }) if unit == "archaeologist"
    ));
}

#[test]
fn project_search_maintains_aged_reactors_and_marginal_conversion_avoids_churn() {
    let mut game = Game::new(2, 24, 16, 7_101, 200, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    install_ai_test_district(&mut game, city, "industrial_zone");
    game.cities.get_mut(&city).unwrap().buildings =
        vec![crate::name!("factory"), crate::name!("nuclear_power_plant")];
    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let counts = EmpireCounts::default();
    let ai = AdvancedAi::new();
    game.climate_phase = 5;
    game.players[0]
        .strategic_resources
        .insert(crate::name!("coal"), 0.1);
    let original_stock_value = 450.0
        + game.strategic_stockpile(0, crate::name!("coal")).min(50.0) * 18.0
        + game.climate_phase as f64 * -110.0;
    let regrouped_stock_value = 450.0
        + (game.strategic_stockpile(0, crate::name!("coal")).min(50.0) * 18.0
            + game.climate_phase as f64 * -110.0);
    assert_ne!(
        original_stock_value.to_bits(),
        regrouped_stock_value.to_bits(),
        "the regression fixture must distinguish floating-point evaluation order"
    );
    assert_eq!(
        AdvancedAi::stock_power_plant_value(&game, 0, "coal").to_bits(),
        original_stock_value.to_bits(),
        "the default-off path must preserve the stock expression bit for bit"
    );
    game.climate_phase = 0;
    let recommission = Item::Project {
        project: crate::name!("recommission_reactor"),
    };

    assert!(ai.production_value(&game, 0, city, &recommission, &plan, &counts) < -9_000.0);
    game.cities.get_mut(&city).unwrap().reactor_age = 30;
    assert!(ai.production_value(&game, 0, city, &recommission, &plan, &counts) > 0.0);

    game.cities.get_mut(&city).unwrap().buildings =
        vec![crate::name!("factory"), crate::name!("oil_power_plant")];
    game.climate_phase = 6;
    game.players[0]
        .strategic_resources
        .insert(crate::name!("coal"), 10.0);
    game.players[0]
        .strategic_resources
        .insert(crate::name!("uranium"), 10.0);
    let coal = Item::Project {
        project: crate::name!("convert_reactor_to_coal"),
    };
    let oil = Item::Project {
        project: crate::name!("convert_reactor_to_oil"),
    };
    let nuclear = Item::Project {
        project: crate::name!("convert_reactor_to_uranium"),
    };
    assert!(
        ai.production_value(&game, 0, city, &nuclear, &plan, &counts)
            > ai.production_value(&game, 0, city, &coal, &plan, &counts)
    );

    game.players[0]
        .strategic_resources
        .insert(crate::name!("oil"), 10.0);
    let mut marginal = ai.clone();
    marginal.reactor_marginal = true;
    assert!(
        marginal.production_value(&game, 0, city, &coal, &plan, &counts) < -9_000.0,
        "coal is worse than the current oil plant at climate phase six"
    );
    assert!(
        marginal.production_value(&game, 0, city, &nuclear, &plan, &counts) > 0.0,
        "uranium is a strict improvement over the current oil plant"
    );
    assert_eq!(
        ai.production_value(&game, 0, city, &recommission, &plan, &counts),
        marginal.production_value(&game, 0, city, &recommission, &plan, &counts),
        "the treatment must not change non-conversion scoring"
    );

    game.cities.get_mut(&city).unwrap().buildings =
        vec![crate::name!("factory"), crate::name!("nuclear_power_plant")];
    assert!(marginal.production_value(&game, 0, city, &coal, &plan, &counts) < -9_000.0);
    assert!(marginal.production_value(&game, 0, city, &oil, &plan, &counts) < -9_000.0);

    game.climate_phase = 0;
    game.players[0]
        .strategic_resources
        .insert(crate::name!("coal"), 50.0);
    game.players[0]
        .strategic_resources
        .insert(crate::name!("uranium"), 0.0);
    assert!(
        marginal.production_value(&game, 0, city, &coal, &plan, &counts) > 0.0,
        "a real fuel/climate utility reversal must remain eligible"
    );

    game.cities.get_mut(&city).unwrap().buildings = vec![crate::name!("factory")];
    assert!(
        marginal.production_value(&game, 0, city, &nuclear, &plan, &counts) < -9_000.0,
        "a missing current plant fails closed"
    );
    assert!(
        ai.production_value(&game, 0, city, &nuclear, &plan, &counts) > -9_000.0,
        "the default-off controller retains stock absolute valuation"
    );
    game.cities.get_mut(&city).unwrap().buildings.extend([
        crate::name!("oil_power_plant"),
        crate::name!("nuclear_power_plant"),
    ]);
    assert!(
        marginal.production_value(&game, 0, city, &coal, &plan, &counts) < -9_000.0,
        "an impossible multiple-plant state fails closed"
    );
}

#[test]
fn district_project_search_extends_only_concrete_great_person_races() {
    let mut game = Game::new(2, 24, 16, 7_103, 200, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    let campus = game.cities[&city]
        .owned_tiles
        .iter()
        .copied()
        .find(|position| *position != game.cities[&city].pos)
        .unwrap();
    game.map.tiles.get_mut(&campus).unwrap().district = Some(crate::name!("campus"));
    game.cities
        .get_mut(&city)
        .unwrap()
        .districts
        .insert(crate::name!("campus"), campus);
    game.players[0].techs.insert(crate::name!("writing"));

    let project = Item::Project {
        project: crate::name!("campus_research_grants"),
    };
    let library = Item::Building {
        building: crate::name!("library"),
    };
    assert!(game.can_produce(0, city, &project));
    assert!(game.can_produce(0, city, &library));
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let ai = AdvancedAi::targeting(VictoryTarget::Science);
    let counts = ai.counts(&game, 0);
    let undeveloped = ai.production_value(&game, 0, city, &project, &plan, &counts);
    let first_building = ai.production_value(&game, 0, city, &library, &plan, &counts);
    assert!(
        first_building > undeveloped,
        "the first Campus building must precede a quiet project: {first_building} <= {undeveloped}"
    );

    game.cities
        .get_mut(&city)
        .unwrap()
        .buildings
        .push(crate::name!("library"));
    let far = ai.production_value(&game, 0, city, &project, &plan, &counts);
    let award = game.project_completion_gpp_awards(0, city, "campus_research_grants")["scientist"];
    let cost = game.gp_cost(0, "scientist");
    game.players[0]
        .gpp
        .insert("scientist".to_string(), cost - award);
    game.players[1]
        .gpp
        .insert("scientist".to_string(), cost - award * 0.5);
    let forcing = ai.production_value(&game, 0, city, &project, &plan, &counts);
    assert!(
            forcing > far + 100.0,
            "a project that claims and overtakes in the live race must receive an extension: {forcing} <= {far}"
        );

    // The live class alone is not enough: a Campus project can be racing
    // for Hildegard of Bingen while Firaxis requires a Holy Site. The
    // mirror's named-offer blocker must remove the race tempo rather than
    // letting a generic Scientist valuation monopolize production.
    game.players[0]
            .live_great_person_offer_blockers
            .insert(
                "scientist".to_string(),
                "the live GREAT_PERSON_INDIVIDUAL_HILDEGARD_OF_BINGEN offer requires an active DISTRICT_HOLY_SITE".to_string(),
            );
    let blocked_offer = ai.production_value(&game, 0, city, &project, &plan, &counts);
    assert!(
            blocked_offer < far,
            "an unusable live offer keeps ordinary yields only, not the GPP race: {blocked_offer} >= {far}"
        );
    game.players[0].live_great_person_offer_blockers.clear();

    game.active_congress_effects
        .push(crate::game::CongressEffect {
            resolution: "patronage".to_string(),
            outcome: "B".to_string(),
            target: "scientist".to_string(),
            expires: game.turn + 30,
        });
    let disabled = ai.production_value(&game, 0, city, &project, &plan, &counts);
    assert!(
        disabled < far,
        "a Congress-disabled class must not retain Great Person race value: {disabled} >= {far}"
    );
}

#[test]
fn defensive_recovery_force_gap_outranks_rear_city_great_person_project() {
    let mut game = Game::new(2, 24, 16, 7_104, 200, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let threatened_city = game.player_city_ids(0)[0];
    let threatened_position = game.cities[&threatened_city].pos;
    let rear_city = found_nearby_test_city(&mut game, 0, threatened_position);
    install_ai_test_district(&mut game, rear_city, "theater_square");
    game.cities
        .get_mut(&rear_city)
        .unwrap()
        .buildings
        .push(crate::name!("amphitheater"));
    game.players[0].civics.insert(crate::name!("drama_poetry"));

    for unit in game.player_unit_ids(0) {
        if game.rules.units[game.units[&unit].kind].class == "military" {
            game.remove_unit(unit);
        }
    }
    for _ in 0..3 {
        game.spawn_test_unit("warrior", 0, game.cities[&rear_city].pos);
    }
    game.record_contact(0, 1);
    game.apply(0, &Action::DeclareWar { player: 1 }).unwrap();

    let project = Item::Project {
        project: crate::name!("theater_square_festival"),
    };
    let award =
        game.project_completion_gpp_awards(0, rear_city, "theater_square_festival")["writer"];
    let cost = game.gp_cost(0, "writer");
    game.players[0]
        .gpp
        .insert("writer".to_string(), cost - award);
    let plan = StrategicPlan {
        strategy: GrandStrategy::Recovery,
        target_player: Some(1),
        target_city: None,
        threatened_city: Some(threatened_city),
        desired_cities: 2,
        assessed_turn: game.turn,
        rush: false,
    };
    let ai = AdvancedAi::new();
    let counts = ai.counts(&game, 0);
    assert_eq!(counts.military, 3, "the two-city defense is one unit short");
    assert!(game.can_produce(0, rear_city, &project));
    assert!(
            ai.production_value(&game, 0, rear_city, &project, &plan, &counts) < -9_000.0,
            "a rear city must reinforce a threatened empire before forcing a cultural Great Person race"
        );
    let warrior = Item::Unit {
        unit: crate::name!("warrior"),
    };
    assert!(
        ai.production_value(&game, 0, rear_city, &warrior, &plan, &counts) > 0.0,
        "the missing land defender must remain a productive alternative"
    );

    let rear_position = game.cities[&rear_city].pos;
    game.spawn_test_unit("warrior", 0, rear_position);
    let reinforced = ai.counts(&game, 0);
    assert_eq!(reinforced.military, 4);
    assert!(
        ai.production_value(&game, 0, rear_city, &project, &plan, &reinforced) > -9_000.0,
        "Great Person races may resume once the defensive force gap is filled"
    );
}

#[test]
fn bread_and_circuses_value_tracks_real_loyalty_need() {
    let mut game = Game::new(1, 20, 14, 7_105, 160, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    let district = game.cities[&city]
        .owned_tiles
        .iter()
        .copied()
        .find(|position| *position != game.cities[&city].pos)
        .unwrap();
    game.map.tiles.get_mut(&district).unwrap().district =
        Some(crate::name!("entertainment_complex"));
    game.cities
        .get_mut(&city)
        .unwrap()
        .districts
        .insert(crate::name!("entertainment_complex"), district);
    game.cities
        .get_mut(&city)
        .unwrap()
        .buildings
        .push(crate::name!("arena"));

    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let ai = AdvancedAi::new();
    let safe = ai.district_project_value(&game, 0, city, "bread_and_circuses", &plan);
    game.cities.get_mut(&city).unwrap().loyalty = 50.0;
    let pressured = ai.district_project_value(&game, 0, city, "bread_and_circuses", &plan);
    assert!(
        pressured > safe + 700.0,
        "loyalty recovery must transform Bread and Circuses from quiet to forcing"
    );
}

/// ★★★★ A THOUSAND FAITH THAT NOTHING CAN SPEND. A seat with no religion and
/// a bank of 900 Faith, forty percent of the way to a Scientist: the shipped
/// gate buys only a person 85% earned, so the Faith sits; with
/// `idle_faith_patronage` the Faith buys the Scientist outright. Gold keeps
/// its gate, a founder keeps its Faith, and a bank under 600 is not idle.
#[test]
fn idle_faith_buys_a_great_person_outright_only_for_a_seat_with_no_religion() {
    let mut game = Game::new(2, 24, 16, 7_102, 200, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    let campus = game.cities[&city]
        .owned_tiles
        .iter()
        .copied()
        .find(|position| *position != game.cities[&city].pos)
        .unwrap();
    game.map.tiles.get_mut(&campus).unwrap().district = Some(crate::name!("campus"));
    game.cities
        .get_mut(&city)
        .unwrap()
        .districts
        .insert(crate::name!("campus"), campus);
    let cost = game.gp_cost(0, "scientist");
    game.players[0]
        .gpp
        .insert("scientist".to_string(), cost * 0.4);
    game.players[0].religion = None;
    game.players[0].gold = 0.0;
    game.players[0].faith = 900.0;
    let claimed = |game: &Game| {
        game.players[0]
            .gp_claimed
            .get("scientist")
            .copied()
            .unwrap_or(0)
    };

    let mut stock = game.clone();
    AdvancedAi::new().advanced_great_people(&mut stock, 0, GrandStrategy::Expansion);
    assert_eq!(
        claimed(&stock),
        0,
        "the shipped gate leaves a 40% race alone"
    );
    assert_eq!(stock.players[0].faith, 900.0);

    let mut ai = AdvancedAi::new();
    ai.enable_idle_faith_patronage();
    let mut idle = game.clone();
    ai.advanced_great_people(&mut idle, 0, GrandStrategy::Expansion);
    assert_eq!(claimed(&idle), 1, "idle Faith buys the Scientist");
    assert!(idle.players[0].faith < 900.0, "…with Faith");

    // A founder's Faith is not idle.
    let mut founder = game.clone();
    founder.players[0].religion = Some("Our Faith".to_string());
    ai.advanced_great_people(&mut founder, 0, GrandStrategy::Expansion);
    assert_eq!(claimed(&founder), 0);
    // Under 600 the bank is not idle either.
    let mut thin = game.clone();
    thin.players[0].faith = 500.0;
    ai.advanced_great_people(&mut thin, 0, GrandStrategy::Expansion);
    assert_eq!(claimed(&thin), 0);
    // Gold keeps its gate even with the gene on.
    let mut rich = game.clone();
    rich.players[0].faith = 0.0;
    rich.players[0].gold = 5_000.0;
    ai.advanced_great_people(&mut rich, 0, GrandStrategy::Expansion);
    assert_eq!(claimed(&rich), 0, "gold does not buy a 40% race");
}

/// The gene is an opt-in: off in every bundle, flippable by name, in
/// `PRODUCTION_OPT_INS`.
#[test]
fn idle_faith_patronage_is_a_native_opt_in() {
    let mut ai = AdvancedAi::new();
    ai.enable_live_bridge_universe();
    assert!(!ai.idle_faith_patronage);
    let (_, _, enable) = PRODUCTION_OPT_INS
        .iter()
        .find(|(_, tag, _)| *tag == "idle-faith-patronage")
        .expect("an opt-in row");
    enable(&mut ai);
    assert!(ai.idle_faith_patronage);
    ai.disable_idle_faith_patronage();
    assert!(!ai.idle_faith_patronage);
}

